INSERT INTO "public"."activity_forms" ("id", "user_id", "form_data", "created_at", "updated_at") VALUES ('00ffee4c-03a1-4c0c-92ee-2f9bf9da1864', '9676ac79-c1ac-478f-b09a-cf9f8eb596a6', '{"student":{"usn":"1RV22EC143","name":"Shreyansh Arya","period":"2022-2026","department":"Electronics & Communication Engineering","totalPoints":0},"activities":[{"id":"bOfpLoGlOGOS0kD9aRfQx","name":"Utsarga Marathon 2024","slNo":1,"place":"RVCE Campus","photos":[],"endDate":"","duration":0,"outcomes":"","semester":"3","startDate":"","hoursSpent":0,"description":"","aicteMapping":"","pointsEarned":10,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"CIa9iI5f0lVLfxH4iuBwf","name":"Utsarga Marathon 2025","slNo":2,"place":"RVCE Campus","photos":[],"endDate":"","duration":0,"outcomes":"","semester":"5","startDate":"","hoursSpent":0,"description":"","aicteMapping":"","pointsEarned":15,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"zYPy36OACou0a1_wk7TLw","name":"Unchained","slNo":3,"place":"RVCE Campus","photos":[],"endDate":"","duration":0,"outcomes":"","semester":"6","startDate":"","hoursSpent":0,"description":"","aicteMapping":"","pointsEarned":10,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"gaTJ3s8VTod0ig4OyUpnN","name":"Rush Hours 4.0","slNo":4,"place":"","photos":[],"endDate":"","duration":0,"outcomes":"","semester":"2","startDate":"","hoursSpent":0,"description":"","aicteMapping":"","pointsEarned":12,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"CpgTWuD0PlC7bQD5XrVbf","name":"Rendezvous with writing","slNo":5,"place":"","photos":[],"endDate":"","duration":0,"outcomes":"","semester":"2","startDate":"","hoursSpent":0,"description":"","aicteMapping":"","pointsEarned":2,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"rQ1RDdxKtJ3fioG40k-c_","name":"Paper Drive","slNo":6,"place":"","photos":[],"endDate":"","duration":0,"outcomes":"","semester":"4","startDate":"","hoursSpent":0,"description":"","aicteMapping":"","pointsEarned":8,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"wU32_Cgia4ab8IJt8pvTj","name":"Fistfull","slNo":7,"place":"RVCE Campus","photos":[],"endDate":"","duration":0,"outcomes":"","semester":"7","startDate":"","hoursSpent":0,"description":"","aicteMapping":"","pointsEarned":10,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"Fi_EHHUBtRgTus9ngZTFv","name":"Echlore","slNo":8,"place":"","photos":[],"endDate":"","duration":0,"outcomes":"","semester":"7","startDate":"","hoursSpent":0,"description":"","aicteMapping":"","pointsEarned":2,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-31 17:41:26.78291+00', '2026-01-31 18:01:28.720352+00'), ('01700057-30ac-4878-ba43-17f6b52f7c6a', '80aacda4-9a23-4940-a4a1-7b3a25b34622', '{"student":{"usn":"1RV23CD403","name":"Imraz Kousar ","period":"2022-2026","department":"Computer Science & Engineering - Data Science","totalPoints":0},"activities":[],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-02-01 11:14:19.703998+00', '2026-02-01 11:14:19.703998+00'), ('01abb37d-78aa-4922-9437-5e70a5094581', '95f0dab0-1128-42a4-a07a-60ae04120479', '{"student":{"usn":"1RV22IS008","name":"Aneesh Sai Grandhi","period":"2022-2026","department":"Information Science & Engineering","totalPoints":0},"activities":[{"id":"WOcTrowrOUxUOC7NKvnfp","name":"Fast Trek","slNo":1,"place":"Huthridurga Hills","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/arn8mfHn-Leore287JYoS.jpeg"],"endDate":"2023-02-12","duration":1,"outcomes":"Fast-Trek raised awareness about heart diseases affecting underprivileged children. A significant amount of financial aid was collected and pledged to support these children’s medical treatments. Participants expressed high satisfaction, highlighting the event as a well-organized, safe, and fun-filled activity that strengthened their bonds and sense of social commitment. ","semester":"1","startDate":"2023-02-12","hoursSpent":9,"description":"The social cause behind the project was to provide financial aid to underprivileged children suffering from heart diseases, aiming to make a positive social impact while promoting awareness and unity among students.  \\n \\nRotaract Club of RVCE conducted one of its flagship events, Fast Trek. The social cause behind this activity was to support underprivileged children suffering from heart diseases. The event started at 7:30 am where all participants boarded the buses and safety instructions were provided. The trek was a great success and the participants had a great time surrounded by the scenic hills of the Huthridurga Betta. Upon reaching the base of Huthridurga Betta, comprehensive safety instructions \\nwere provided to all participants, including the correct way to handle difficult terrain, the importance of staying hydrated, and emergency protocols. The event not only focused on adventure but also aimed at instilling a sense of social responsibility and teamwork.","aicteMapping":"Community Service","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/nwNtvxvQgaNs-8ALgyhMb.png","certificateAttached":true,"detailedReportPageNo":"1-2","signatureOfCounsellor":""},{"id":"ifIl4ZhAmitDN8CHgVOjO","name":"Blood Donation Camp","slNo":2,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/TuIGjpXcWaTshk88tDlLG.png"],"endDate":"2023-06-06","duration":1,"outcomes":"The Blood Donation Camp resulted in the successful collection of blood units that were contributed to the Lions Blood Bank, directly supporting patients requiring critical care and emergency treatment. It increased awareness among students about the importance and safety of blood donation, dispelling common myths and encouraging future participation. The event strengthened a culture of compassion, civic responsibility, and volunteerism, while instilling confidence and pride among donors for contributing to a life-saving cause.","semester":"2","startDate":"2023-06-06","hoursSpent":2,"description":"The Blood Donation Camp, organized in collaboration with the Lions Blood Bank, was a humanitarian initiative aimed at promoting voluntary blood donation and saving lives. The event encouraged students and staff to actively participate by donating blood, thereby supporting hospitals and patients in need of timely transfusions. Medical professionals ensured that the donation process was conducted safely and hygienically, while awareness was also created about the importance of regular blood donation and its role in emergency and healthcare services. The camp fostered a sense of social responsibility and collective service among participants, reinforcing the value of selfless contribution to society.","aicteMapping":"Community Service ","pointsEarned":6,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/e0i_8MDYDJcDqHMEpx_tS.jpeg","certificateAttached":true,"detailedReportPageNo":"3-4","signatureOfCounsellor":""},{"id":"Y7Ee8y1ZhYWwO3KiYDi8S","name":"Hack4Soc 2.0","slNo":3,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/TzJTxVpfUrvYNmVitQzXM.png"],"endDate":"2024-02-04","duration":2,"outcomes":"The hackathon resulted in the development of several innovative and socially impactful technological solutions addressing real-world challenges across the domains of Generative AI, Fintech, and Blockchain. Participants gained hands-on experience in problem identification, solution design, and rapid prototyping, strengthening their technical, analytical, and collaborative skills.","semester":"3","startDate":"2024-02-03","hoursSpent":33,"description":"This 24-hour hackathon focused on leveragi11g technology for societal benefit, encompassing three key verticals: Generative AI, Fintech, and Blockchain. \\n\\nThroughout the hackathon, students showcased their creativity and problem-solving skills, developing innovative solutions. The top three teams emerged victorious, each presenting \\ninnovative ideas. This flagship event not only provided a platform for learning and collaboration but also fostered a culture of innovation among the participants. ","aicteMapping":"Community Service","pointsEarned":12,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/Nksd9rxpycNyCTo0RNtWd.png","certificateAttached":true,"detailedReportPageNo":"5-6","signatureOfCounsellor":""},{"id":"zUFh-g8DlMdQE9cwyy7Ka","name":"Utsarga Marathon 2024","slNo":4,"place":"Bengaluru","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/4uUKdstmLVZK1kv9X0Q_p.png"],"endDate":"2024-02-04","duration":1,"outcomes":"Participating in the marathon felt empowering, knowing that my involvement directly supported education for underprivileged children. The donations from the 5 km and 10 km runs are making a tangible difference in providing educational resources and opportunities. Along the way, I had the chance to meet and make new friends who shared the same passion for helping others. After completing the race, I received a medal and a certificate, symbols of the effort put into both the race and the cause. It was an unforgettable experience to be part of such a meaningful event and to run alongside others committed to helping change the world for the better.","semester":"3","startDate":"2024-02-04","hoursSpent":3,"description":"The Utsarga Marathon, organized by NSS RVCE, was a special event aimed at promoting health and fitness while making a meaningful impact. I participated in the 5 km race, and the event proved to be an extraordinary experience. The theme, \"Help a Child - Change the World,\" was at the heart of the marathon, emphasizing the importance of education and social \\ncontribution. Every step I took was part of a larger mission to support children in need, helping to pave the way for their brighter futures. The marathon took place on February 4th, 2024, at R V College of Engineering, and it was an inspiring sight to see so many participants come together for a shared cause. It was not just about running but about being part of a movement. The event provided 10 activity points to everyone involved, \\nmaking it not only a fitness challenge but also an opportunity to contribute to a great cause. The race began at 8 AM, and the atmosphere was electric, with participants of all ages and backgrounds united in the same goal. It was a beautiful morning, filled with enthusiasm and a sense of purpose. The marathon promoted the health and clearly highlighted the theme \"Help a Child - Change the World,\" and at last everyone felt satiated and were given certificate for participation and also mark for participating in the social cause \\nemphasizing the theme of the marathon ","aicteMapping":"Community Development","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/lgIIEgK4HfsZtoP9KVbec.jpeg","certificateAttached":true,"detailedReportPageNo":"7-8","signatureOfCounsellor":""},{"id":"mW4MFQVJw3H-miZQGN69J","name":"Blood Donation Camp","slNo":5,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/6Ntn-rzOxeSU1-7ElKQy0.jpeg"],"endDate":"2024-06-28","duration":1,"outcomes":"The Blood Donation Camp resulted in the successful collection of blood units that were contributed to the Rashtrotthana Blood Center, directly supporting patients requiring critical care and emergency treatment. It increased awareness among students about the importance and safety of blood donation, dispelling common myths and encouraging future participation. The event strengthened a culture of compassion, civic responsibility, and volunteerism, while instilling confidence and pride among donors for contributing to a life-saving cause.","semester":"4","startDate":"2024-06-28","hoursSpent":2,"description":"The Blood Donation Camp, organized in collaboration with the Rashtrotthana Blood Center, was a humanitarian initiative aimed at promoting voluntary blood donation and saving lives. The event encouraged students and staff to actively participate by donating blood, thereby supporting hospitals and patients in need of timely transfusions. Medical professionals ensured that the donation process was conducted safely and hygienically, while awareness was also created about the importance of regular blood donation and its role in emergency and healthcare services. The camp fostered a sense of social responsibility and collective service among participants, reinforcing the value of selfless contribution to society.","aicteMapping":"Community Service","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/NjfYVcrpI3aoQ1mBI0RFB.jpeg","certificateAttached":true,"detailedReportPageNo":"9-10","signatureOfCounsellor":""},{"id":"FpGBuU-btglgBz43VGnap","name":" T-Shirt for Smiles","slNo":6,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/8W62_-sb2i2WAjvoicoCn.png"],"endDate":"2024-09-04","duration":1,"outcomes":"The T-Shirt for Smiles activity led to increased social awareness and a strong sense of empathy among students, highlighting the importance of giving back to the community. It successfully generated funds that contributed to the welfare and happiness of the children at Prajakirana Seva Charitable Trust Anathashram, bringing smiles and emotional support to their lives. The event encouraged teamwork, volunteerism, and a culture of compassion among participants, while also helping students understand the impact of collective efforts in addressing social needs. Overall, the activity strengthened students’ commitment to social responsibility and community engagement.","semester":"5","startDate":"2024-09-04","hoursSpent":1,"description":"T-Shirt for Smiles was a student-driven social initiative aimed at combining creativity, compassion, and community service. Students were encouraged to purchase specially designed T-shirts, with the proceeds from the sales dedicated to spreading happiness among the children of Prajakirana Seva Charitable Trust Anathashram, located at Kumbalgodu, Bengaluru.\\n\\nThe event emphasized the spirit of social responsibility and collective contribution, demonstrating how small individual actions can create a meaningful impact. The funds raised were used to support the needs and bring joy to the children at the anathashram, reinforcing values of empathy, generosity, and inclusiveness among students. T-Shirt for Smiles successfully fostered a culture of kindness and awareness, inspiring participants to actively engage in humanitarian efforts beyond the classroom.","aicteMapping":"Community Service","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/q6hQ5DdGY7JgvqWss4pwj.png","certificateAttached":true,"detailedReportPageNo":"11-12","signatureOfCounsellor":""},{"id":"LiqoB48UjWVIb8M-ezfzt","name":"Volunteering for the 8th International Conference on Computational Systems and Information Technology for Sustainable Solutions","slNo":7,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/9w0ulLOZShaeFsd25ZwzZ.png"],"endDate":"2024-11-23","duration":32,"outcomes":"The volunteering experience resulted in the successful and smooth execution of conference sessions, contributing to a well-organized and professionally managed international event. It enhanced my organizational, communication, and coordination skills, particularly in working with academicians, researchers, and international delegates. The activity improved my ability to manage responsibilities under time constraints, solve problems in real time, and work effectively as part of a team. Additionally, it provided valuable insights into the structure and workflow of academic conferences, strengthened my understanding of research dissemination processes, and fostered a sense of responsibility, leadership, and confidence in handling large-scale academic events.","semester":"5","startDate":"2024-10-23","hoursSpent":60,"description":"Volunteering for the 8th International Conference on Computational Systems and Information Technology for Sustainable Solutions, conducted from 7th to 9th November 2024, was an enriching experience that involved active participation in both the pre-conference planning and on-site execution of a large-scale international academic event. I volunteered for nearly one month, working closely with the organizing committee to ensure the smooth and professional conduct of the conference.\\n\\nDuring the preparatory phase, I contributed to the designing and creation of official invitations for distinguished guests, keynote speakers, and dignitaries, ensuring clarity, professionalism, and consistency with the conference theme. I also assisted in the verification of session chairs, helping confirm their availability, credentials, and assigned sessions to ensure well-structured and well-managed technical tracks. Additionally, I played a key role in designing participation certificates for research paper presenters and certificates for the Best PhD Thesis Award, ensuring accuracy, proper formatting, and timely availability.\\n\\nDuring the conference days, I actively volunteered in session management, coordinating with session chairs, presenters, and technical teams. My responsibilities included ensuring that presentations followed the scheduled timelines, assisting speakers with presentation setup, managing transitions between sessions, and addressing any logistical issues in real time. This role was critical in maintaining the smooth flow of paper presentations and ensuring a professional and engaging experience for all participants. Overall, the volunteering experience provided valuable exposure to the operational, academic, and collaborative aspects of organizing an international conference focused on sustainable technological solutions.","aicteMapping":"Contribution to International Research Conference","pointsEarned":20,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/9vpmYwa6NLJygoLKsSaJF.png","certificateAttached":true,"detailedReportPageNo":"13-14","signatureOfCounsellor":""},{"id":"fH-8LxMv8zTjr3w557mkC","name":"Vikasit Bharath Quiz","slNo":8,"place":"Online","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/L_Y58IrhP-0lgDctjQv3u.png"],"endDate":"2024-12-01","duration":1,"outcomes":"The Viksit Bharat Quiz 2024 resulted in enhanced awareness and understanding among participants regarding India’s development vision, government initiatives, and national priorities. It strengthened participants’ knowledge of economic growth strategies, digital transformation, sustainability, and governance reforms, while also encouraging analytical thinking and informed discussion on nation-building. The activity fostered a sense of civic responsibility, patriotism, and alignment with the goal of a developed India by 2047. Additionally, it promoted healthy competition, improved general knowledge, and motivated students and youth to actively engage with public policies and contribute positively to the country’s progress.","semester":"5","startDate":"2024-12-01","hoursSpent":1,"description":"The Viksit Bharat Quiz 2024, organized by the Government of India, was a nationwide awareness and knowledge-based initiative aimed at engaging youth and citizens in understanding the vision of a Developed India (Viksit Bharat). The quiz focused on key national priorities such as economic growth, innovation, digital transformation, sustainability, governance reforms, and India’s roadmap towards becoming a developed nation by 2047.\\n\\nConducted across educational institutions and online platforms, the quiz encouraged participants to deepen their knowledge about government policies, flagship schemes, historical milestones, and future-oriented initiatives launched by the Government of India. The activity fostered critical thinking, civic awareness, and a sense of national responsibility among students and young professionals.\\n\\nBy promoting active participation and healthy competition, the Viksit Bharat Quiz 2024 successfully inspired learners to align their aspirations with the nation’s development goals, reinforcing the spirit of informed citizenship and collective progress toward building a self-reliant and globally competitive India.","aicteMapping":"Social Awareness","pointsEarned":2,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/S94nXdcWWvVssezANooXV.png","certificateAttached":true,"detailedReportPageNo":"15-16","signatureOfCounsellor":""},{"id":"6ocH7lAS9KErxQWtPsT_h","name":"Fast Trek 3.0","slNo":9,"place":"Narayangiri Hills","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/GUzBBnRTQhOBLdwtDdlcP.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/6-vLG-YFdmVeKmOG-THu6.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/vbusGijF1yb7BxjjWgnFC.jpeg"],"endDate":"2025-01-12","duration":1,"outcomes":"The Fast Trek 3.0 encouraged combining environmental impact, student engagement, and community building. The cleanliness drive during the trek significantly contributed to preserving the natural beauty of Narayangiri Hills, while also instilling a strong sense of eco-consciousness and responsibility among participants. Over 500 students not only experienced the thrill of trekking but also actively engaged in social impact, reinforcing the Rotaract Club’s commitment to sustainability. The activity fostered teamwork, bonding, and motivation, as participants supported one another throughout the journey, creating lasting memories and shared experiences. Ultimately, the event left students feeling accomplished and inspired, setting a benchmark for future initiatives by blending adventure, social responsibility, and camaraderie into a single impactful activity.","semester":"5","startDate":"2025-01-12","hoursSpent":9,"description":"  \\nFast Trek 3.0, the biggest flagship event of the Rotaract Club of RVCE, took place on 12th January 2025 at the scenic Narayangiri Hills, bringing together over 500 enthusiastic participants from the college. This adventure-packed event combined trekking with a meaningful cleanliness drive, reinforcing the club’s commitment to environmental responsibility. The trek began early in the morning, with participants embarking on a thrilling journey through the rugged trails of Narayangiri Hills. Amidst breathtaking views, the team actively engaged in cleaning the surroundings, collecting litter, and promoting eco-consciousness. The event not only contributed to preserving the natural beauty of the hills but also instilled a sense of responsibility among students. Beyond the cause, Fast Trek 3.0 fostered incredible team bonding, as participants supported and motivated one another throughout the trek. Laughter, shared experiences, and the collective effort to make a difference created an unforgettable experience. The event concluded on a high note, with participants feeling both accomplished and inspired.\\n\\nWith its perfect blend of adventure, social impact, and camaraderie, Fast Trek 3.0 was a massive success, leaving a lasting impact on both the environment and the participants, setting a benchmark for future events.","aicteMapping":"Community Service","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/DLUma05UXQEiQngQFvYDV.png","certificateAttached":true,"detailedReportPageNo":"17-19","signatureOfCounsellor":""},{"id":"cj-Qy-GUlfiQDczdwpbmD","name":"Utsarga Marathon","slNo":10,"place":"Bengaluru","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/MlgudIK4z3FxxUiHNir42.jpeg"],"endDate":"2025-04-06","duration":1,"outcomes":"Participating in the marathon felt empowering, knowing that my involvement directly supported education for underprivileged children. The donations from the 5 km and 10 km runs are making a tangible difference in providing educational resources and opportunities. Along the way, I had the chance to meet and make new friends who shared the same passion for helping others. After completing the race, I received a medal and a certificate, symbols of the effort put into both the race and the cause. It was an unforgettable experience to be part of such a meaningful event and to run alongside others committed to helping change the world for the better.","semester":"6","startDate":"2025-04-06","hoursSpent":3,"description":"The Utsarga Marathon, organized by NSS RVCE, was a special event aimed at promoting health and fitness while creating a meaningful social impact. I participated in the 5 km race, and the event proved to be an extraordinary and memorable experience.\\n\\nThe marathon was centered around the inspiring theme “Help a Child – Change the World,” which emphasized the importance of education and social responsibility. Every step taken during the run symbolized a larger mission—to support children in need and help pave the way for their brighter futures.\\n\\nThe event was held on 6th April 2025, at R V College of Engineering. It was truly inspiring to witness a large number of participants come together for a shared cause. The marathon was not just about running; it was about being part of a movement that promoted compassion and collective responsibility.\\n\\nThe race began at 8:00 AM, and the atmosphere was energetic and uplifting. Participants from different age groups and backgrounds were united by a common goal. The beautiful morning was filled with enthusiasm, motivation, and a strong sense of purpose.\\n\\nAll participants were awarded 15 activity points, making the event both a fitness challenge and a valuable opportunity to contribute to a social cause. At the conclusion of the marathon, participants felt satisfied and fulfilled. Certificates of participation were distributed, acknowledging everyone’s involvement and contribution toward the cause highlighted by the marathon theme.\\n\\nOverall, the Utsarga Marathon successfully promoted health, social awareness, and community service, leaving a lasting impression on everyone involved.","aicteMapping":"Community Development","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/-B98dvnsDo45M7C2JaUPZ.jpeg","certificateAttached":true,"detailedReportPageNo":"20-21","signatureOfCounsellor":""},{"id":"Fo2409l8odDDKdTUNmM1n","name":"Sustainable Agriculture and Tractor Mechanics Workshop","slNo":11,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/Te_8COrR7tpZKuLbAGfap.jpeg"],"endDate":"2026-01-25","duration":1,"outcomes":"The workshop enhanced participants’ understanding of tractor mechanics and their significance in improving agricultural productivity and sustainability. It helped bridge the gap between theoretical knowledge and practical application by providing real-time demonstrations and hands-on exposure. Participants gained clarity on critical mechanical parameters such as engine performance, RPM, horsepower, braking systems, and PTO functionality, leading to a better appreciation of farm machinery operation and safety. The opportunity to drive the tractor boosted confidence, practical skills, and experiential learning, making the workshop both informative and engaging while fostering greater interest in sustainable agricultural technologies.","semester":"7","startDate":"2026-01-25","hoursSpent":2,"description":"The Sustainable Agriculture and Tractor Mechanics Workshop was a hands-on learning program designed to provide practical insights into the role of tractors in modern and sustainable agricultural practices. The workshop focused on explaining how tractors are effectively used in agriculture, with special emphasis on their working principles and mechanical aspects. Participants were introduced to key concepts such as the tractor engine, RPM, horsepower, the purpose of having two independent brakes, and the role of the Power Take-Off (PTO) in operating agricultural implements. The sessions combined theoretical explanations with real-world demonstrations, helping participants clearly understand how mechanical efficiency contributes to sustainable farming practices. Towards the end of the workshop, participants were also given the opportunity to drive the tractor, allowing them to apply their learning practically and gain a unique, first-hand experience of operating agricultural machinery.","aicteMapping":"Agriculture and Tractor Engineering","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/95f0dab0-1128-42a4-a07a-60ae04120479/crEw8gmmBQxaFLZJoimiX.jpeg","certificateAttached":true,"detailedReportPageNo":"22-23","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"Prof. Poornima Kulkarni","designation":"Assistant Professor"},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-29 13:19:20.15402+00', '2026-01-31 05:38:18.755992+00'), ('0239446b-2f3f-43d8-8bba-c0d106ac4c08', '28de1f75-bbc4-4c6a-bd02-5b8d577d91b5', '{"student":{"usn":"1RV22AI046","name":"Roshan John","period":"2022-2026","department":"Artificial Intelligence & Machine Learning","totalPoints":0},"activities":[{"id":"VLgseAZcRZrBTY6pLFom0","name":"Utsarga Marathon ","slNo":1,"place":"RVCE Campus","photos":[],"endDate":"2024-02-04","duration":1,"outcomes":"The overwhelming response from participants highlighted the deep-rooted commitment of RVCE towards community service and social responsibility. The event fostered a sense of camaraderie and unity among participants, reinforcing the spirit of teamwork and determination. \\n\\nAdditionally, the marathon acted as an awareness campaign, encouraging individuals to embrace an active lifestyle while giving back to society. The initiative not only strengthened the bond between students and the community but also showcased how small contributions, when combined, can drive impactful social change.\\n","semester":"3","startDate":"2024-02-04","hoursSpent":2,"description":"Utsarga Marathon is an annual event organized by the National Service Scheme (NSS) of RV College of Engineering, aiming to promote fitness, community engagement, and social responsibility. The event brings together students, faculty, and fitness enthusiasts who participate in the marathon by paying a registration fee. This fee serves a greater purpose, as all the proceeds collected are directed toward a noble cause, such as supporting underprivileged communities, funding healthcare initiatives, or contributing to environmental sustainability projects. The marathon not only encourages physical well-being but also fosters a sense of unity and collective action among participants. \\n\\nBeyond just a race, Utsarga Marathon symbolizes the spirit of giving and service. The event provides a platform for individuals to contribute to meaningful social initiatives while experiencing the thrill and satisfaction of completing a marathon. Participants take pride in knowing that their efforts go beyond personal achievement, as their involvement directly aids those in need. Organized with meticulous planning, the marathon includes well marked routes, hydration stations, and medical assistance to ensure a smooth and safe experience for all runners. Over the years, this initiative has gained widespread support, strengthening the values of empathy and community service within RVCE and beyond.\\n","aicteMapping":"Public awareness programmes and youth engagement","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/28de1f75-bbc4-4c6a-bd02-5b8d577d91b5/ewQUUnCaSeWAq8kGMEMrE.jpg","certificateAttached":true,"detailedReportPageNo":"1","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-31 01:44:32.004507+00', '2026-01-31 01:44:32.004507+00'), ('03010c50-4776-4248-90ae-ee9116284d6c', '20771ffc-f6cd-44db-8ed2-078b938acb21', '{"student":{"usn":"1RV22CS233","name":"VISHRUTH V","period":"2022-2026","department":"Computer Science & Engineering","totalPoints":0},"activities":[{"id":"eLUT-GPnxntpyvJQVet6k","name":"FAST TREK 2.0","slNo":1,"place":"Kunagalu Betta Hills","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/8Fw6TUriI21vZaQRCByOG.jpeg"],"endDate":"2024-01-28","duration":1,"outcomes":"Over 500 individuals enthusiastically engaged in the trekking experience, contributing to the event''s vibrant atmosphere and swelling the ranks of active environmental stewards. The massive turnout from students created electric energy, with diverse groups forming lasting connections amid the hills. The cleanliness drive yielded tangible results, removing several kilograms of waste and documenting efforts for future campaigns.\\nOverall, the trek left a lasting legacy of empowerment and unity. It transformed a simple hike into a catalyst for change, proving that adventures paired with purpose can mobilize hundreds toward environmental preservation and personal growth.","semester":"3","startDate":"2024-01-28","hoursSpent":16,"description":"The social cause at the heart of the project was a dedicated cleanliness drive during the trek, aimed at preserving the pristine environment of the Kunagalu Betta Hills. This initiative underscored sustainable tourism and collective responsibility toward nature. Participants gathered with passion for adventure and eco-consciousness, ready to blend physical challenge with meaningful stewardship. Commencing at 7:30 AM, over 750 enthusiastic individuals boarded chartered buses to the site, excitement building through songs and chatter. Organizers distributed water, snacks, and eco-bags ahead of a thorough safety briefing by guides and NSS volunteers.","aicteMapping":"Economic and Community Development ","pointsEarned":10,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"1","signatureOfCounsellor":""},{"id":"Q9eVdTiWTkvcIKFXnf_gr","name":"BLOOD DONATION CAMP","slNo":2,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/-p5G_l5SaAjiPU1heZnqI.jpeg"],"endDate":"2023-04-06","duration":1,"outcomes":"The event was highly successful as it helped collect valuable units of blood that can be used\\nfor patients requiring transfusions, thereby directly contributing to saving lives. It increased\\nawareness among students about the importance of regular blood donation and removed\\ncommon fears and misconceptions related to the process. The program strengthened social\\nresponsibility, empathy, and community service values among participants. It also motivated","semester":"2","startDate":"2023-04-06","hoursSpent":2,"description":"The event was organized by the Rotaract Club of RVCE with the objective of promoting voluntary blood donation and creating awareness about the importance of saving lives through\\nblood donation. The program was conducted in collaboration with a recognized medical institution to ensure safety and proper medical procedures. Participants actively volunteered to\\ndonate blood and were guided with necessary health checks and safety instructions. The event encouraged students to contribute selflessly toward society and support patients in need of blood for medical emergencies and treatments","aicteMapping":"Awareness Drive ","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/w9pDPVHhl_jfHCcwXKu6a.png","certificateAttached":true,"detailedReportPageNo":"2-3","signatureOfCounsellor":""},{"id":"gGclgtSSXJ78vWYrg-zVI","name":"UTSARGA Marathon ","slNo":3,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/O1mtjEOB6lAUo7n3r7ZGY.png"],"endDate":"2024-02-04","duration":26,"outcomes":"The involvement in publicity, sponsorship coordination, and on-the-day volunteering for the event contributed significantly to its successful execution. Through publicity activities, effective\\ncommunication and outreach were achieved, resulting in increased awareness and participation among students and the campus community. Sponsorship-related responsibilities provided practical exposure to professional communication, planning, and coordination, while helping mobilize resources necessary for the smooth conduct of the event. Volunteering on the day of the event enhanced teamwork, leadership, and problem-solving skills, as volunteers assisted in managing participants, logistics, and on-ground arrangements.\\nThe collective efforts ensured orderly execution, participant safety, and overall efficiency of the program. This experience strengthened a sense of social responsibility, discipline, and\\ncommitment to community service, while reinforcing the importance of collaboration and active participation in organizing impactful social initiatives.","semester":"3","startDate":"2024-01-10","hoursSpent":0,"description":"Utsarga Marathon is an annual event organized by the National Service Scheme (NSS) of RV College of Engineering, aiming to promote fitness, community engagement, and social responsibility. The event brings together students, faculty, and fitness enthusiasts who participate in the marathon by paying a registration fee. This fee serves a greater purpose, as all\\nthe proceeds collected are directed toward a noble cause, such as supporting underprivileged communities, funding healthcare initiatives, or contributing to environmental sustainability\\nprojects. The marathon not only encourages physical well-being but also fosters a sense of unity and collective action among participants. Beyond just a race, Utsarga Marathon symbolizes the spirit of giving and service. The event provides a platform for individuals to contribute to meaningful social initiatives while\\nexperiencing the thrill and satisfaction of completing a marathon. Participants take pride in knowing that their efforts go beyond personal achievement, as their involvement directly aids\\nthose in need. Organized with meticulous planning, the marathon includes well- marked routes, hydration stations, and medical assistance to ensure a smooth and safe experience for all runners. Over the years, this initiative has gained widespread support, strengthening the values of empathy and community service within RVCE and beyond.","aicteMapping":"Community Development ","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/Msgr2wQaXpXKURmgiqFSI.png","certificateAttached":true,"detailedReportPageNo":"4-5","signatureOfCounsellor":""},{"id":"HDqBKYmIRMGeKTJC-dhYi","name":"INDI - GENIUS : The India Quiz","slNo":4,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/rFl4baNq_IntC2CPoqshC.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/dWatkBdBu2YaqIYRBZzUB.jpeg"],"endDate":"2024-06-09","duration":3,"outcomes":"The event significantly improved my general awareness, problem-solving skills, and confidence\\nin competitive environments. It enhanced logical reasoning, memory recall, and time\\nmanagement abilities. The quiz also promoted healthy competition, teamwork, and effective\\ncommunication. Overall, the event contributed to intellectual development, boosted learning\\nmotivation, and provided valuable exposure to competitive academic platforms.","semester":"4","startDate":"2024-06-07","hoursSpent":4,"description":" I participated in the “Under the Peepal Tree – Indi-Genius: The India Quiz” organized by the QuizCorp Club of RVCE, which aimed to enhance knowledge, critical thinking, and awareness\\nabout India’s history, culture, current affairs, and general knowledge. The quiz was conducted at a national level with well-structured rounds that tested analytical ability, quick decision-making, and teamwork. The event provided a competitive yet engaging environment that encouraged\\nintellectual curiosity and collaborative learning among participants","aicteMapping":"QUIZ","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/_pSPNjGvExdzjxA7du0wx.png","certificateAttached":true,"detailedReportPageNo":"6-7","signatureOfCounsellor":""},{"id":"DIgUrMXrpPwhtBajE-4rG","name":"UTSARGA MARATHON 2025","slNo":5,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/GmWk8aTcHkMpg74ZNQxPo.png"],"endDate":"2025-04-06","duration":1,"outcomes":"The marathon significantly improved physical stamina, mental resilience, and self-discipline.\\nIt promoted awareness about the importance of fitness, perseverance, and community\\nparticipation. The event also strengthened team spirit, motivation, and leadership qualities\\namong participants. Completing the 5 km run boosted confidence and encouraged continued\\ninvolvement in social and health-oriented activities. Overall, the event created a positive","semester":"7","startDate":"2025-04-06","hoursSpent":4,"description":"I participated in the Utsarga Marathon 2025 organized under the National Service Scheme\\n(NSS), RV College of Engineering, with the objective of promoting community service, physical\\nfitness, and social responsibility. As part of the event, I successfully completed a 5 km run,\\ndemonstrating endurance, discipline, and commitment. The marathon encouraged students to\\nadopt a healthy lifestyle while contributing towards a social cause and community awareness.\\nThe event was well-coordinated with proper safety arrangements, volunteer support, and\\nguidance throughout the route, ensuring a smooth and motivating experience for all participants.","aicteMapping":"Economic and Community Development ","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/5UJJDFt7m-RjGnYl5XEa-.jpeg","certificateAttached":true,"detailedReportPageNo":"8-9","signatureOfCounsellor":""},{"id":"b2Bd1IQudlQRurl8MIO2V","name":"PROJECT PUSTAK","slNo":6,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/KETsA1tm1OsmQXtK7urR1.png"],"endDate":"2025-04-30","duration":4,"outcomes":"The campaign facilitated the provision of learning essentials to dozens of underprivileged children across Bengaluru''s underserved communities, directly equipping them with books, stationery, and materials to thrive in school. Donors'' generosity, spurred by the tiered points system, amassed hundreds of kits distributed at joyful handover events where Rotaract volunteers witnessed grateful smiles and eager hands flipping through new pages. This tangible support promoted education as a fundamental right, breaking cycles of poverty and igniting academic passion.\\nBy fostering brighter futures for many, the initiative reinforced Rotaract RVCE''s legacy of impactful service, with participants earning points toward resumes and reflections that deepened their sense of purpose. Follow-up stories from schools highlighted improved attendance and enthusiasm, proving small contributions create enduring change and inspiring campus-wide momentum for ongoing educational drives.\\n","semester":"6","startDate":"2025-04-27","hoursSpent":40,"description":"The Rotaract Club of RVCE launched a impactful education support initiative to uplift underprivileged children by supplying essential books, notebooks, pens, pencils, erasers, and interactive learning materials like charts and workbooks. This drive targeted students in local slums and rural areas around Bengaluru, where basic school supplies often remain out of reach. Rotaract members coordinated with nearby schools and NGOs to identify the most pressing needs, ensuring donations hit the ground running.\\n\\nContributions operated on an accessible two-tier system designed to reward generosity: a modest ₹100 donation earned 3 activity points, perfect for students dipping into service, while a ₹350 pledge unlocked 10 points for deeper commitment. Collection boxes dotted campus hostels, canteens, and department lounges, accompanied by posters featuring smiling kids with \"Knowledge for All\" slogans. Digital UPI links and QR pledges made giving seamless for everyone.\\n\\nThe initiative spread knowledge and smiles by directly enabling access to resources that spark learning and confidence. Stories poured in of children clutching new notebooks for their first time, eyes lighting up during distribution events where Rotaract volunteers hosted reading circles and goal-setting workshops. These moments turned donations into personal victories, bridging gaps between privileged and underserved youth.\\n","aicteMapping":"Economic and Community Development ","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/xuwPc681y16D3UYsgqXT9.png","certificateAttached":true,"detailedReportPageNo":"10-11","signatureOfCounsellor":""},{"id":"I-fkI9T0c7nk-H-9gt-PC","name":"FIST FULL 2025","slNo":7,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/HUjZ8HHyLZlKuruSdMB6T.jpeg"],"endDate":"2025-11-17","duration":14,"outcomes":"The pledge initiative effectively promoted awareness and individual responsibility towards drug-free living, contributing to the larger goal of a healthier, addiction-free India. \\n","semester":"7","startDate":"2025-11-04","hoursSpent":4,"description":"The Rotaract Club of RVCE organized a heartwarming event titled \"FIST FULL\" from November 4th to November 17th, 2025, rallying the campus community to combat hunger and spread kindness in a simple yet profound way. This two-week initiative invited students, faculty, and staff to make a daily pledge: set aside a fistful of rice or toor dal from every home-cooked or hostel meal. These small contributions accumulated into bulk donations, with participants encouraged to deliver 5 kg of rice or 2 kg of toor dal by the event''s end.\\n\\nThe beauty of \"FIST FULL\" lay in its accessibility; no grand gestures required, just a mindful handful per meal to symbolize shared empathy. Collection points sprouted across RVCE hostels, mess halls, and common areas, manned by enthusiastic Rotaract volunteers who weighed donations, shared uplifting stories, and tracked progress on a public leaderboard. QR codes linked to a digital pledge tracker, allowing participants to log their daily fistfuls and see the growing total in real-time.\\n\\nEngagement soared as word spread through posters, WhatsApp groups, and cafeteria announcements, drawing hundreds into the fold. Families joined remotely, mailing contributions, while creative twists emerged: dorm challenges for \"fistful relays\" and recipe shares using toor dal. Volunteers hosted mini-awareness sessions, discussing local hunger statistics and how staples like rice and dal sustain underprivileged families, turning donations into teachable moments.\\n","aicteMapping":"Economic and Community Development ","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/81nWvYQ58_l_ZefnxP5jE.jpeg","certificateAttached":true,"detailedReportPageNo":"12-13","signatureOfCounsellor":""},{"id":"_GsY1m4yOFnxYJd3N4hXP","name":"BLOOD DONATION CAMP ","slNo":8,"place":"RVCE ","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/5lJLelH73TInGN2hyJoXt.jpeg"],"endDate":"2024-06-28","duration":1,"outcomes":"The event was highly successful as it helped collect valuable units of blood that can be used\\nfor patients requiring transfusions, thereby directly contributing to saving lives. It increased\\nawareness among students about the importance of regular blood donation and removed\\ncommon fears and misconceptions related to the process. The program strengthened social\\nresponsibility, empathy, and community service values among participants. It also motivated","semester":"4","startDate":"2024-06-28","hoursSpent":4,"description":"The event was organized by the Rotaract Club of RVCE with the objective of promoting voluntary blood donation and creating awareness about the importance of saving lives through\\nblood donation. The program was conducted in collaboration with a recognized medical institution to ensure safety and proper medical procedures. Participants actively volunteered to\\ndonate blood and were guided with necessary health checks and safety instructions. The event encouraged students to contribute selflessly toward society and support patients in need of blood for medical emergencies and treatments","aicteMapping":"Economic and Community Development ","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/3yYnZsIi0xuv4BrXDsSaX.png","certificateAttached":true,"detailedReportPageNo":"14-15","signatureOfCounsellor":""},{"id":"dWBsT4PQjhooaG4heMSwZ","name":"DISCOM VOLUNTEERING - 8TH MILE","slNo":9,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/oJX046OTUemdnOuHXD7T4.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/ze2fJ0RRiUt4ct03gdhGm.jpeg"],"endDate":"2025-12-06","duration":3,"outcomes":"Through this volunteering experience, I developed effective teamwork and coordination skills, enhanced my communication and crowd management abilities, and learned to handle responsibilities in a real-time event environment. The activity improved my leadership, time management, and problem-solving skills, while also building a sense of discipline, social responsibility, and confidence in managing large groups during college-level events.","semester":"7","startDate":"2025-12-04","hoursSpent":30,"description":"I volunteered in the college fest DISCOM, where I was actively involved in crowd management and coordination of event arrangements. My responsibilities included guiding and managing attendees, assisting in venue setup, coordinating with the organizing team to ensure smooth execution of events, and maintaining discipline and safety throughout the fest. Through this experience, I developed teamwork, communication, and interpersonal skills, learned effective time management and responsibility, and gained practical exposure to handling real-time challenges during large-scale events, which contributed to my overall personal and professional development","aicteMapping":"SAFETY DRIVE","pointsEarned":20,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/20771ffc-f6cd-44db-8ed2-078b938acb21/g6xgBZu2qPbmFKj7HGR6r.jpeg","certificateAttached":true,"detailedReportPageNo":"16-17","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-02-01 12:52:32.078769+00', '2026-02-02 06:38:23.159389+00'), ('04016d2a-bd9f-438e-bd4c-3d6036ee399f', 'b64c6aa0-c314-4f5b-9d8e-3b2a6864cff2', '{"student":{"usn":"1RV23EI401","name":"Deepak Sourav R","period":"2023-2026","department":"Electronics & Instrumentation Engineering","totalPoints":0},"activities":[{"id":"QsK3IXXX2lDGjDrR6mLlq","name":"Utsarga Marathon 2024","slNo":1,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b64c6aa0-c314-4f5b-9d8e-3b2a6864cff2/BCZb7hRbbMgZglhtH92DK.jpg"],"endDate":"2024-02-04","duration":1,"outcomes":"By participating in an event themed \"Help a child – Change the world,\" I realized the impact that collective student action can have on fundraising and social advocacy.","semester":"3","startDate":"2024-02-04","hoursSpent":40,"description":"I participated in the UTSARGA Marathon, a flagship charity run organized by the NSS unit of RVCE. The event was held under the theme \"Help a child – Change the world!\" with the primary objective of raising awareness and funds for child welfare and social development.\\n\\nDuring the event, I participated in the 5 KM category. Beyond the physical challenge of the marathon, the event served as a platform to promote community health, fitness, and the spirit of social service embodied by the NSS motto, \"Not Me, But You.\"","aicteMapping":"Social Responsibility and Awareness","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b64c6aa0-c314-4f5b-9d8e-3b2a6864cff2/-c3qAH35ZCMPXrgbhVUxe.jpg","certificateAttached":true,"detailedReportPageNo":"1-2","signatureOfCounsellor":""},{"id":"UqJ1vKz4_DWAjTkgsGXgu","name":"Blood donation 2024","slNo":2,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b64c6aa0-c314-4f5b-9d8e-3b2a6864cff2/684-JNJ2dEHV1Q9hJanX1.jpg"],"endDate":"2024-06-28","duration":1,"outcomes":"Developed a sense of duty toward the community, understanding that as a healthy student, I have a responsibility to support public health initiatives. By participating, I helped normalize the act of donation among my peers, encouraging a culture of regular voluntary donation.","semester":"4","startDate":"2024-06-28","hoursSpent":40,"description":"I volunteered for and participated in the Blood Donation Camp organized on campus. The event aimed to address the perennial shortage in blood banks and support patients requiring emergency transfusions, surgeries, and treatments.","aicteMapping":"Social Awareness / Social Service","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b64c6aa0-c314-4f5b-9d8e-3b2a6864cff2/a2JBSKx-9_s-47EJFGxrG.jpg","certificateAttached":true,"detailedReportPageNo":"3-4","signatureOfCounsellor":""},{"id":"I33xLJMmrY-KwUU1anYO6","name":"Female Foeticide Walkathon","slNo":3,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b64c6aa0-c314-4f5b-9d8e-3b2a6864cff2/7am4C9QKAlTqhJ38z_Spp.jpeg"],"endDate":"2025-04-06","duration":1,"outcomes":"Successfully reached a diverse demographic of the local public, sparking conversations about the importance of protecting the rights of the girl child. Reinforced the idea of equal opportunity for all genders. The event highlighted that educating and empowering girls is key to social and economic progress.","semester":"5","startDate":"2025-04-06","hoursSpent":60,"description":"I participated in a community walkathon organized to raise public awareness about the declining child sex ratio and the social evil of female foeticide. The event involved a rally around our RVCE Campus, where volunteers carried placards, banners, and posters highlighting the importance of gender equality and the legal consequences of prenatal sex determination.","aicteMapping":"Social Responsibility and awareness","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b64c6aa0-c314-4f5b-9d8e-3b2a6864cff2/YZ08tDqFgI7xh9oSRTrw9.png","certificateAttached":true,"detailedReportPageNo":"5-6","signatureOfCounsellor":""},{"id":"9-GzwPSQMSelTS5T-MH8y","name":"Visit to International Drug awareness day event","slNo":4,"place":"Sree Kanteerava Stadium, Bengaluru","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b64c6aa0-c314-4f5b-9d8e-3b2a6864cff2/thHoQqwzSVdRjFLbqCWm_.jpeg"],"endDate":"2025-05-26","duration":1,"outcomes":"Gained a comprehensive understanding of the Nasha Mukt Bharat Abhiyan and the state''s role in executing national health and safety directives. Learned about the strict laws surrounding narcotics in India and the proactive measures taken by the police to curb trafficking. Recognized the role of youth as \"Ambassadors of Change\" in identifying and preventing drug abuse within peer groups and neighborhoods.","semester":"5","startDate":"2025-05-26","hoursSpent":20,"description":"I attended the massive state-level awareness programme organized by the Karnataka State Police and Bengaluru City Police at Kanteerava Stadium to observe the International Day Against Drug Abuse. The event was inaugurated by the Hon''ble Home Minister, Dr. G. Parameshwara, in the presence of senior police officials and thousands of students.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b64c6aa0-c314-4f5b-9d8e-3b2a6864cff2/-lB71kVq1JcmQRaf3LSJE.jpeg","certificateAttached":true,"detailedReportPageNo":"7-8","signatureOfCounsellor":""},{"id":"I-XhhILyAnRCAPXHu9DEQ","name":"Utsarga Marathon 2025","slNo":5,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b64c6aa0-c314-4f5b-9d8e-3b2a6864cff2/C40mxREIrJJhMFnS_2Shw.jpeg"],"endDate":"2025-06-26","duration":1,"outcomes":"Gained a deeper understanding of the challenges faced by underprivileged children. By participating in an event themed \"Help a child – Change the world,\" I realized the impact that collective student action can have on fundraising and social advocacy.","semester":"6","startDate":"2025-06-26","hoursSpent":60,"description":"I participated in the UTSARGA Marathon, a flagship charity run organized by the NSS unit of RVCE. The event was held under the theme \"Help a child – Change the world!\" with the primary objective of raising awareness and funds for child welfare and social development.","aicteMapping":"Social Responsibility and Awareness","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b64c6aa0-c314-4f5b-9d8e-3b2a6864cff2/gwxGrwM1Urbnibbr8dK-4.jpg","certificateAttached":true,"detailedReportPageNo":"9-10","signatureOfCounsellor":""},{"id":"mZkZDRcmRxkhXCDZq1deF","name":"Blood donation camp 2025","slNo":6,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b64c6aa0-c314-4f5b-9d8e-3b2a6864cff2/wwC-AagSPjt7Dl8ndPjpW.jpg"],"endDate":"2025-10-30","duration":1,"outcomes":"Developed a sense of duty toward the community, understanding that as a healthy student, I have a responsibility to support public health initiatives. By participating, I helped normalize the act of donation among my peers, encouraging a culture of regular voluntary donation.\\n","semester":"7","startDate":"2025-10-30","hoursSpent":40,"description":"I volunteered for and participated in the Blood Donation Camp organized on campus. The event aimed to address the perennial shortage in blood banks and support patients requiring emergency transfusions, surgeries, and treatments.\\n","aicteMapping":"Social Service / Awareness","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b64c6aa0-c314-4f5b-9d8e-3b2a6864cff2/6_TnbpQGwr5NNJbl7W6C_.jpg","certificateAttached":true,"detailedReportPageNo":"11-12","signatureOfCounsellor":""},{"id":"tLDF8pq5SHWXoowIFDVHP","name":"Fist full 2025","slNo":7,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b64c6aa0-c314-4f5b-9d8e-3b2a6864cff2/PGY65Y_6OM8Bad5gAzCn2.jpg"],"endDate":"2025-11-21","duration":19,"outcomes":"My contribution, along with the collective efforts of the student body, helped provide essential food supplies to local NGOs, ensuring that vulnerable individuals had access to basic nutrition. Gained a deeper awareness of the issues surrounding food waste and the critical importance of food security in urban social development. Developed a sense of empathy and altruism, reinforcing the habit of contributing a portion of my resources toward social welfare.","semester":"7","startDate":"2025-11-03","hoursSpent":40,"description":"I participated in the \"Fist Full\" initiative, a signature community service project organized by the Rotaract Club of RVCE. The program is based on the philosophy that small, individual contributions—when aggregated—can significantly impact food security for the underprivileged. I contributed 5kg of rice to the collection point on campus. These collected grains were then consolidated and donated to verified local orphanages and shelter homes in Bengaluru.","aicteMapping":"Social Service / Awareness","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b64c6aa0-c314-4f5b-9d8e-3b2a6864cff2/aIKvGD8JMnsyXHATGrxzF.jpeg","certificateAttached":true,"detailedReportPageNo":"13-14","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-30 16:49:30.614794+00', '2026-01-31 03:04:07.835842+00'), ('042377fb-826c-48ab-9662-d7abf7571535', 'c05d8bab-955f-41f2-bc6a-cb9cc893584c', '{"student":{"usn":"","name":"","period":"2022-2026","department":"","totalPoints":0},"activities":[],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-30 15:21:38.057813+00', '2026-01-30 15:21:39.533525+00'), ('046e968f-3f8e-47bc-b195-f593eaae8806', '2975e15e-a7c1-4a3a-b494-c3690ecb3b0f', '{"student":{"usn":"1RV22EC176","name":"Varsha GM","period":"2022-2026","department":"Electronics & Communication Engineering","totalPoints":0},"activities":[{"id":"m1E133VHgokoT9YK_dHqP","name":"Mera Phale Vote Desh Ke Liye","slNo":1,"place":"Online","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2975e15e-a7c1-4a3a-b494-c3690ecb3b0f/WzgR0JKm1vrYk7GKbs9wO.jpg"],"endDate":"2024-03-06","duration":1,"outcomes":"The “Mera Phale Vote Desh Keliye” initiative successfully\\nencourages first-time voters to participate actively in the electoral process. It creates awareness about voting rights and strengthens democratic values among youth. The program helps reduce voter apathy and motivates young citizens to make informed choices. It also increases overall voter turnout by building confidence in RV college of Engineering® Bengaluru AICTE activity points new voters. Overall, the initiative promotes responsible citizenship and supports a stronger, more participatory Democracy.","semester":"2","startDate":"2024-03-06","hoursSpent":0,"description":"The \"Mera Pehla Vote, Desh Ke Liye\" initiative by the Indian government is a significant campaign aimed at encouraging firsttime voters to actively participate in the democratic process and exercise their fundamental right to vote. Recognizing the importance of youth involvement in shaping the nation''s future, this program seeks to instill a deep sense of responsibility, civic duty, and national pride among young citizens who are eligible to\\nvote for the first time. As a part of this initiative, individuals take a pledge, committing\\nthemselves to vote responsibly, make informed choices, and support leaders who work towards the progress and well-being of the country.  The campaign also leverages social media, educational institutions, and community engagement programs to reach a wider audience, ensuring that young voters are motivated and well-prepared to take part in the\\nelectoral process. By fostering a culture of informed and responsible voting, \"Mera Pehla Vote, Desh Ke Liye\" serves as a crucial step in empowering the youth and reinforcing the\\nprinciples of democracy, ensuring that every vote contributes to the nation’s growth and stability.","aicteMapping":"Spreading Public Awareness","pointsEarned":4,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2975e15e-a7c1-4a3a-b494-c3690ecb3b0f/z9GrdPKR0H56uH0UP2B3f.png","certificateAttached":true,"detailedReportPageNo":"1-2","signatureOfCounsellor":""},{"id":"PVNs46GhSKFQIHHgZfbp2","name":"Utsarga Marathon 2024","slNo":1,"place":" Around RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2975e15e-a7c1-4a3a-b494-c3690ecb3b0f/dO9QvQoDjet3lLSaF-Rzt.jpg"],"endDate":"2024-02-04","duration":1,"outcomes":"The event promoted physical fitness, empathy, and social awareness among participants. It strengthened teamwork, leadership, and volunteerism while fostering a sense of fulfillment through contribution to a meaningful social cause. Additionally, the marathon encouraged a spirit of unity and collective responsibility, inspiring participants to actively engage in community service initiatives. The experience reinforced the importance of sustained individual effort in creating a positive and lasting social impact. Participants, reinforcing the spirit of\\nteamwork and determination. The well-organized event featured\\nstructured routes, hydration stations, and medical assistance,\\nensuring a smooth and safe experience for all runners.\\nAdditionally, the marathon acted as an awareness campaign,\\nencouraging individuals to embrace an active lifestyle while\\ngiving back to society. ","semester":"3","startDate":"2024-02-04","hoursSpent":4,"description":"Utsarga Marathon is a 5-kilometer charity marathon that symbolized a commitment to health, fitness, and social responsibility, while contributing meaningfully toward shaping a child’s future. Guided by the theme “Help a Child, Change the World,” the event emphasized the role of collective effort in supporting education for underprivileged children. The marathon featured both 5 km and 10 km run categories, encouraging inclusive participation across varied fitness levels. With an impressive turnout of over 1,650 participants, including students, faculty members, and external runners, the event reflected strong community involvement and social commitment. The presence of esteemed dignitaries such as the Principal, Vice-Principal, Dean of Student Affairs, and Dean of Academics added significance and reinforced the values of service, leadership, and civic responsibility upheld by NSS RVCE. The event was meticulously \\norganized with the coordinated efforts of nearly 200 dedicated \\nvolunteers,  structured  into  specialized teams  managing  publicity, registrations, route coordination, refreshments, hospitality, and logistics.","aicteMapping":"Spreading Publice Awareness","pointsEarned":10,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"3-4","signatureOfCounsellor":""},{"id":"YzIJeXdT8vtex3_HfGtg1","name":"Azadi Ka Kalotsav","slNo":2,"place":"Manekshaw Parade Ground","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2975e15e-a7c1-4a3a-b494-c3690ecb3b0f/NLcixfUzbGLt9Wd4fa4_X.jpg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2975e15e-a7c1-4a3a-b494-c3690ecb3b0f/PO20f8Z0DuO0BagTYq_r_.jpeg"],"endDate":"2024-08-15","duration":1,"outcomes":"The event fostered a strong sense of national pride and significantly enhanced awareness of democratic and constitutional values among participants. It inspired students to uphold the ideals of freedom, unity, discipline, and social responsibility in their personal and professional lives. \\nThe program encouraged informed and responsible citizenship, motivating students to actively participate in democratic processes and contribute positively toward nation-building, social harmony, and the preservation of national integrity.","semester":"4","startDate":"2024-08-15","hoursSpent":10,"description":"Azadi Ka Kalotsav was organized to commemorate the 76th Independence Day of India at the Manekshaw Parade Ground. The event celebrated the nation’s freedom by honoring the immense sacrifices made by freedom fighters and highlighting the core values of unity, discipline, and patriotism. Ceremonial activities such as flag hoisting, patriotic performances, and inspirational addresses were conducted to instill a deep sense of national pride among participants. The program emphasized the importance of national integrity, constitutional values, and civic responsibility, encouraging citizens—especially the youth—to uphold democratic ideals and contribute positively toward the progress and unity of the nation.","aicteMapping":"Spreading Public Awareness","pointsEarned":30,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2975e15e-a7c1-4a3a-b494-c3690ecb3b0f/Wjb-9_y36lwHfTeN-NK4d.png","certificateAttached":true,"detailedReportPageNo":"5-6","signatureOfCounsellor":""},{"id":"a847VSJFKEp8m6lepsyPc","name":"Fistfull 2024  ","slNo":5,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2975e15e-a7c1-4a3a-b494-c3690ecb3b0f/KOSL72iRF8rNWUyNNz2ma.png"],"endDate":"2024-12-10","duration":1,"outcomes":"6700+ kg of Rice and 800+ kg of Toor Dal was collected. The donation phase held on 10th Dec 2024. Seven NGOs namely,\\n1) A.I.R Humanitarian Homes.\\n2)Pruthvi Foundation. \\n3)Sai Aashraya Super Specialty Hospital.\\n4)Amrutavani Old Age Home.\\n5)Sneha Jyothi Orphanage. \\n6)Hanuman Temple. \\n7) Nele Foundation were benefitted with tons of rice and hundreds of kilos of Toor Dal.","semester":"5","startDate":"2024-12-10","hoursSpent":1,"description":"Fistfull 2024 was a hunger alleviation and food donation drive aimed at addressing food insecurity among underprivileged communities. The initiative encouraged students to donate essential food grains, reinforcing the belief that small individual contributions, when combined, can create a significant and lasting social impact. The drive witnessed enthusiastic participation from students across various departments, reflecting a strong sense of empathy, social responsibility, and collective commitment toward community welfare.\\nThe activity served as a platform to sensitize students to the realities of food scarcity and the importance of sustainable humanitarian efforts. Through coordinated collection and distribution, the drive strengthened the spirit of volunteerism and demonstrated how organized student participation can effectively support vulnerable sections of society","aicteMapping":"Spreading Public Awareness","pointsEarned":10,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"6-7","signatureOfCounsellor":""},{"id":"zK18QoD880NKI9v0vVlfD","name":"Fast Trek 3.0  ","slNo":5,"place":"Narayanagiri Hills  ","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2975e15e-a7c1-4a3a-b494-c3690ecb3b0f/7egqnixr2vO9ZmjBaYbv2.png"],"endDate":"2025-01-12","duration":1,"outcomes":"The activity cultivated empathy and social responsibility among \\nparticipants. It resulted in participants demonstrating determination and cooperation while navigating the demanding terrain. The event also emphasized the importance of perseverance and unity in overcoming obstacles. ","semester":"5","startDate":"2025-01-12","hoursSpent":12,"description":"Fast Trek 3.0 was an endurance-based initiative designed to promote physical fitness, mental resilience, discipline, and teamwork among students. The trek encouraged participants to step beyond their comfort zones and collectively face physical as well as mental challenges, fostering a spirit of mutual support and collaboration. Conducted at the Naryanangiri Hills, the activity provided a challenging yet scenic environment that enhanced the overall learning and experiential value of the event.\\nParticipants demonstrated determination, adaptability, and cooperation while navigating the demanding terrain under varying conditions. The trek served as a platform for developing leadership qualities, stress management skills, and situational awareness. Emphasis was placed on perseverance, unity, and collective problem-solving, reinforcing the idea that coordinated effort and resilience are essential in overcoming obstacles. Overall, the event contributed to holistic personality development and encouraged students to adopt an active, disciplined, and health-conscious lifestyle.","aicteMapping":"Spreading Public Awareness","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2975e15e-a7c1-4a3a-b494-c3690ecb3b0f/jDvUd1LB2U_k7s7arD17g.png","certificateAttached":true,"detailedReportPageNo":"7-8","signatureOfCounsellor":""},{"id":"32uvU_B5ScQhwOwgSHa5N","name":"Utsarga Marathon - 2025  ","slNo":6,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2975e15e-a7c1-4a3a-b494-c3690ecb3b0f/2mERdk7R00AtdtK4B0JQB.jpg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2975e15e-a7c1-4a3a-b494-c3690ecb3b0f/WzobODO0uJmDvCBUH3q15.png"],"endDate":"2025-04-06","duration":1,"outcomes":"Successfully completed the 5km marathon run and helped in \\ncontributing towards a noble cause. Participants demonstrated strong enthusiasm and commitment, reflecting a growing awareness of the importance of maintaining a healthy lifestyle and contributing to social causes. Overall, the Utsarga Marathon 2025 made a positive and lasting impact by combining fitness, awareness, and service, reinforcing the role of youth as active contributors to a healthier and more socially responsible society .","semester":"6","startDate":"2025-04-06","hoursSpent":6,"description":"Participated in a 5-kilometer charity marathon that celebrated health and physical fitness while offering a meaningful opportunity to make a social impact. The event symbolized a commitment to reshaping a child’s future through collective action. Guided by the theme “Help a Child, Change the World,” the marathon emphasized the role of individual effort in supporting education for underprivileged children, where every step taken contributed toward a larger social cause.Conducted under the aegis of the National Service Scheme (NSS), the marathon brought together students, faculty members, alumni, and members of the public from diverse backgrounds to collectively run for a cause. The event effectively spread awareness about the importance of physical fitness, youth engagement, and community service. Utsarga Marathon 2025 fostered an energetic and inclusive environment, reinforcing the values of unity, service, and social responsibility, while inspiring participants to actively contribute toward nation-building and sustainable social development. ","aicteMapping":"Spreading Public Awareness","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2975e15e-a7c1-4a3a-b494-c3690ecb3b0f/yZtNGcqN8-C5H4Dnfqurx.png","certificateAttached":true,"detailedReportPageNo":"9-10","signatureOfCounsellor":""},{"id":"lyZgqmfALFCx95qA7SfIb","name":" Wildlife Conservation Walkathon ","slNo":7,"place":"Vidhan Soudha ","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2975e15e-a7c1-4a3a-b494-c3690ecb3b0f/PHZVVvTUFAHbK7wmuJIzl.png"],"endDate":"2025-10-02","duration":1,"outcomes":"The event aimed to raise awareness about the importance of wildlife conservation and the urgent need to protect the natural habitats of various species. It highlighted the role of ecological balance in sustaining biodiversity and emphasized the responsibility of citizens in preserving the environment. The initiative also drew attention to the proactive measures undertaken by the government to safeguard the state’s natural heritage, including the declaration of protected zones and conservation areas.","semester":"6","startDate":"2025-10-02","hoursSpent":8,"description":"NSS RVCE, in collaboration with EMPRI organised the Wildlife  Conservation Walkathon under the Environment Education Programme  \\n(EEP). Chief Minister Siddaramaiah inaugurated the week-long celebrations on October 2 by flagging off a walkathon from Vidhana \\nSoudha to Lalbagh in Bengaluru. The walkathon started from the Grand  Steps of Vidhana Soudha, with Deputy Chief Minister D K Shivakumar, Forest Minister Eshwar Khandre, and wildlife conservation ambassador \\nAnil Kumble participating. The program also highlighted the initiatives undertaken by the government to preserve the state’s natural heritage, including the declaration of protected zones and conservation areas. The walkathon concluded with an awareness-driven call to action, encouraging participants to adopt environmentally responsible practices, such as reducing pollution, protecting natural resources, and avoiding the use of firecrackers during festivals like Deepavali, thereby contributing to wildlife protection and environmental sustainability.","aicteMapping":"Spreading Publice Awareness","pointsEarned":8,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"11-12","signatureOfCounsellor":""},{"id":"d-Y1u5RlLSbD7-m01GBHw","name":"Wildlife Conservation Walkathon  ","slNo":8,"place":"Vidhan Soudha","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2975e15e-a7c1-4a3a-b494-c3690ecb3b0f/k2j9TjIcvK61ebx401jgL.png"],"endDate":"2025-10-02","duration":1,"outcomes":"The event aims to raise awareness about the importance of wildlife \\nconservation and the need to protect the natural habitat of various \\nspecies. The government has also been taking steps to preserve the \\nstate’s natural heritage, including declaring certain areas as protected \\nzones. The event concluded with a call to action for people to take \\nsteps to protect the environment and wildlife, including avoiding the \\nuse of firecrackers during festivals like Deepavali. ","semester":"6","startDate":"2025-10-02","hoursSpent":8,"description":"The Rotaract Club of RV College of Engineering (RVCE) organized the Wildlife Conservation Walkathon in collaboration with Rotaract District 3191 and the Government of Karnataka, with active support from the Karnataka Forest Department. The event was aimed at raising awareness about wildlife conservation, environmental sustainability, and the urgent need to protect natural ecosystems.\\nThe walkathon commenced from the Grand Steps of Vidhana Soudha, one of the most iconic landmarks of Bengaluru, lending significant visibility and impact to the initiative. The event was graced by the presence of Deputy Chief Minister D. K. Shivakumar, Forest Minister Eshwar Khandre, and renowned cricketer and wildlife conservation ambassador Anil Kumble, whose participation underscored the importance of collective responsibility toward environmental protection.The walkathon witnessed enthusiastic participation from students, volunteers, and members of the public, creating a strong platform for dialogue on conservation efforts, biodiversity protection, and sustainable coexistence with nature. Through this initiative, the Rotaract Club of RVCE successfully highlighted the role of youth-led movements in driving environmental awareness and inspiring community action toward preserving wildlife for future generations.","aicteMapping":"Spreading Public Awareness","pointsEarned":5,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"13-14","signatureOfCounsellor":""},{"id":"QXEBsNmJWYPeMcf0-y31t","name":"Fistfull – 2025","slNo":9,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2975e15e-a7c1-4a3a-b494-c3690ecb3b0f/njlsbB5IkeweRTZ6ylV9Z.png"],"endDate":"2025-11-17","duration":1,"outcomes":"Took part in a noble cause. Overall, 2146 students donated 4370 kg of rice and 2516 kg of dal and helped 7 beneficiaries such as: Hanuman Temple (1300 kg), Pruthvi Foundation (900 kg), Amrutavani Vridh Seva  Samithi (900 kg), Sai Ashraya Hospital (2000 kg), Sai Satguna Sangrama Trust (800 kg), Nele Foundation (900 kg) and nearby anganwadis. The collective effort resulted in the successful collection and distribution of food grains to the above listed beneficiaries. The project transformed individual contribution into large scale nutritional contribution to vulnerable communities.  ","semester":"7","startDate":"2025-11-17","hoursSpent":1,"description":"The Rotaract Club of RV College of Engineering (RVCE) organized the FistFull initiative as a voluntary community service event aimed at addressing food insecurity and supporting health and care institutions. Under this initiative, students were encouraged to contribute 5 kg of rice or 2 kg of toor dal, fostering a spirit of social responsibility and collective participation among the student community.\\nThe event was conducted with the support of Rotary Bangalore  under the Community Service Avenue, with its primary area of focus being Fighting Disease. By ensuring the availability of essential food supplies, the initiative sought to indirectly promote health, nutrition, and well-being among vulnerable populations residing in care and healthcare institutions.\\n","aicteMapping":"Spreading Public Awareness","pointsEarned":10,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"14-15","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-30 07:30:30.108304+00', '2026-01-31 03:07:56.102825+00'), ('0481ccb5-99c9-4872-b48f-f2d0a1bd489e', '9ad40624-fe2a-47f3-9aca-cc571946dd1a', '{"student":{"usn":"1RV22CV107","name":"Sudeep R Sirur","period":"2022-2026","department":"Civil Engineering","totalPoints":0},"activities":[{"id":"NwWJ2pfr-WDfz_5zFtrYi","name":"NSS Utsarga Marathon 2024","slNo":1,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/Q-G_Mb3k5JsPNY3tkrXb7.jpeg"],"endDate":"2024-02-04","duration":1,"outcomes":"The Utsarga Marathon successfully combined physical fitness with social impact, creating a meaningful platform for community engagement. By organizing the event at R V College of Engineering, the initiative motivated students and participants to adopt healthier lifestyles while contributing to a larger humanitarian cause. The marathon helped raise awareness and support for educational initiatives aimed at underprivileged children, reinforcing the idea that individual participation can directly contribute to social development. The provision of AICTE activity points further encouraged active involvement, ensuring strong participation and institutional recognition of social responsibility. \\n\\nThis initiative demonstrates that social causes can be effectively integrated with fitness and recreational activities to drive wider participation and impact. It highlights the value of holistic development—balancing physical well-being with empathy and civic responsibility. Participants learn that social change does not always require complex interventions; consistent effort and collective participation can make a tangible difference. The marathon also fosters discipline, teamwork, and a sense of purpose, reinforcing the role of students as active contributors to societal progress while nurturing both body and mind ","semester":"3","startDate":"2024-02-04","hoursSpent":40,"description":"The Utsarga Marathon is a social and fitness-oriented event organized at R V College of Engineering on February 4th, 2024, from 6:00 AM to 10:30 AM. The marathon is designed to promote physical well-being while fostering social responsibility among participants. More than just a running event, it carries a strong humanitarian message under the theme “Help a Child Change the World.” \\n\\nParticipants are encouraged to take part not only to celebrate health and fitness but also to contribute to a meaningful cause, as every step taken supports initiatives aimed at providing education to underprivileged children. By combining endurance, enthusiasm, and empathy, the Utsarga Marathon creates a platform where students and participants actively engage in social change while earning 10 AICTE activity points for their involvement. ","aicteMapping":"To skill rural population","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/efKDTD70ynlkXPyA2GFUM.jpeg","certificateAttached":true,"detailedReportPageNo":"1-2","signatureOfCounsellor":""},{"id":"Ehk5iKh8PnvsK5_BjTDn_","name":"NSS Village Camp","slNo":2,"place":"Hosadurga Kanakpur","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/REa_9KhSs-WoRf5RgOD9A.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/GiH6B4B2zpmzjCteOHmez.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/i3PI6vXPXfkGyIag431hH.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/r1LjLTjuk61E4QNIhyPWc.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/ibe2-yKYKKflY-ilhoEgL.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/HCRflbg7IETeUuDcR5yHC.jpeg"],"endDate":"2024-07-19","duration":6,"outcomes":"Team-building and an understanding of the camp''s goals and activities. Improved leadership skills and communication while working together in outdoor settings. Enhanced cultural awareness and appreciation for local heritage. Deepened connection with the community and awareness of health issues in rural areas. Gained skills in community outreach, survey techniques, and personal growth. \\n\\nLeadership, event management skills, and an understanding of social responsibility through cultural performances. Developed organizational and leadership abilities, understood the importance of gratitude and appreciation in teamwork. Understood the importance of discipline and organization in a camp setting. Strengthened communication developed trust within the group, and learned the value of staying active and engaged in team-building exercises. ","semester":"3","startDate":"2024-07-14","hoursSpent":160,"description":"\\nI took part in organizing the Special Village Camp by NSS RVCE which is organizing annually. We went for Hosadurga for Preliminary Survey to check the safety accommodation, lunch, what all are activities to be conducted and met with the Gram Panchayath leader ad helped us for the arrangements. \\n\\n\\nDAY 1 \\n\\n9:00 AM - 10:30 AM: \\nConducted a planning meeting as part of the core team to finalize the week''s schedule. Discussed and outlined daily activities, community engagement sessions, and special events tailored to address the village''s specific needs. Divided volunteers into groups with team leads. \\n\\n10:45 AM - 1:00 PM: \\nLed a team of volunteers in conducting a reconnaissance survey to: \\nFamiliarize with the village layout. Identify potential project areas such as infrastructure improvements and public facility upgrades. \\n\\n2:00 PM - 4:00 PM: Organized and facilitated focus group discussions and interviews with villagers. \\nTopics addressed: \\nLocal challenges like water scarcity, agricultural practices, healthcare access, education, and economic opportunities. Consolidated key insights for action planning. \\n\\n4:30 PM - 5:30 PM: \\nCoordinated cleaning and organizing efforts for volunteer living quarters. Ensured a hygienic and comfortable stay to maintain health and morale for the team. \\n\\n7:00 PM - 8:30 PM: \\nShared a communal dinner with fellow volunteers, fostering teamwork and camaraderie. Attended an inspiring address by NSS Officer Dr. M. Lokeshwari, who emphasized the significance of our efforts and motivated us to maintain dedication throughout the camp. \\n\\n\\n\\nDAY 2 \\n\\n4:00 AM - Premises Cleaning \\nTeam Rashtrakutas, under the guidance of core members, commenced the day with a cleaning drive at the school premises. \\nVolunteers created a serene atmosphere by playing Shiva stotrams during the activity. \\n\\n6:30 AM - Flag Hoisting and Morning Routine \\nAll participants assembled for the flag-hoisting ceremony, followed by basic exercises and drills to promote physical fitness. \\nThe morning assembly included a \"Thought for the Day\" session, highlighting the history of the Rashtrakuta dynasty and the art of rangoli. \\n\\nThe Chief Guest, along with NSS officer Dr. Lokeshwari, delivered an inaugural address that emphasized ongoing village development initiatives and local history. The session concluded with the NSS song and the National Anthem. \\n\\n8:00 AM - Village Cleaning Drive \\nVolunteers, divided into teams, conducted a cleanliness campaign across the village. Activities included trimming overgrown grass, collecting plastic waste, and managing its disposal. These efforts enhanced the village’s cleanliness and raised environmental awareness among the community. \\n\\n10:00 AM - Medical Camp \\nA comprehensive medical camp was organized at the government school, offering health checkups, eye examinations, and dental care. As a core member, I assisted in coordinating the camp logistics, ensuring smooth operations and efficient crowd management. Volunteers supported medical professionals, helping provide vital services and raising awareness about health issues. \\n\\n2:00 PM - Motivational Talk \\nA guest speaker delivered an inspiring session on spirituality, meditation, and personal development. The session aimed to motivate schoolchildren to excel both academically and personally, fostering resilience and purpose. \\n\\n6:00 PM - Evening Cultural Activities \\nDespite the rain, the cultural event was successfully organized.\\nThe performances included: A dance on the Ganesh Shloka. A Kannada folk song. A skit promoting dry and wet waste separation. A vibrant Shiv Tandava dance. These activities celebrated the rich cultural heritage of the village and brought the community together. \\n\\n\\n\\nDAY 3 \\n\\nEarly Morning (4:00 AM - 6:30 AM) \\nCleanup Drive: I Led by Team Kadamba, we cleaned the school premises to set a positive tone for the day. Spiritual Ambiance: Played Shiva stotrams to foster peace and calm. Flag-Hoisting Ceremony (6:30 AM - 8:30 AM) Organized the event with basic exercises and drills. Graced by Police Officer Hanumantappa and NSS Officer Lokeshwari Ma''am. Motivational speeches on youth''s role in community service. Morning Activities (8:30 AM - 12:30 PM) Spoken English & Career Guidance: Teams Chalukyas and Wodeyars conducted interactive sessions at Sri Rama High School. \\n\\nSanitary Awareness: Team Hoysalas educated on menstrual hygiene and safety, supported by NGO Yaanataranga. \\nCleanliness Drive: Team Rashtrakuta cleaned the primary healthcare center and school grounds. \\n\\nAfternoon Seminar (2:00 PM - 4:00 PM) \\nLearned about wildlife careers through a seminar by NGO Yaanataranga. Enjoyed folk song performances and practiced using a local instrument. Evening Cultural Program (5:00 PM - 7:00 PM) \\nTraditional Performances: \\nOur team, Kadamba, organized an engaging cultural evening. Volunteers performed traditional Indian dances like Bharatanatyam and Kathak. \\n\\nVillage Participation: \\nLocal children enthusiastically joined in, singing folk songs and performing dances. I had the privilege of portraying Shri Krishna, adding a special touch to the event. \\n\\nRecognition: \\nOutstanding young performers were rewarded with books and stationery to encourage their talents. \\n7:00 PM – 7:30 PM Dehoisted the flag to conclude a productive and fulfilling day. \\n\\n\\n\\n DAY 4 \\n\\n6:00 AM: Started the day with an energetic morning drill to promote discipline among volunteers. \\n\\n6:30 AM: Conducted the NSS flag hoisting ceremony with the Wodeyar team, managed by core members, including myself. \\n\\n10:00 AM - 3:30 PM: Coordinated a health camp in collaboration with the Wodeyar team to provide essential medical check-ups and consultations to 102 villagers. Key findings included: \\n\\nOrthopedic Issues: Identified in 86% of attendees (~88 villagers), highlighting significant medical needs. ENT Issues: Diagnosed in 35% of attendees (~36 villagers). Heart Problems: Observed in 12% of elderly participants (~12 villagers). Simultaneously, a Blood Donation Camp was organized in partnership with Mediscope Blood Camp, further contributing to community health support. \\n\\nGovernment Hospital Cleaning \\nLed efforts to clean and sanitize the local government hospital, covering wards, outpatient areas, and surroundings. Coordinated road cleaning to improve overall sanitation. \\n\\nCultural Event: A cultural program was planned to showcase local traditions and provide entertainment for the villagers and volunteers. Due to heavy rainfall, the event was canceled. Despite this, I worked with my team to ensure volunteers utilized the time effectively for team bonding and planning activities for the next day. \\n\\n \\n\\nDAY 5 \\n\\nEco-walk led by the core team explored the village’s scenic beauty. Guides shared insights on indigenous plants and their ecological roles. Concluded with a pooja at Ram Mandir, merging environmental awareness with spiritual reflection. Ethnic Day celebrated with vibrant traditional attire showcasing cultural diversity. Fashion show highlighted cultural significance of traditional outfits, fostering mutual respect and bonding. \\n\\nEvening: \\nCampfire with music, stories, and reflections created a sense of community. Ceremonial passing of the NSS flag emphasized teamwork, leadership continuity, and unity. \\n\\n\\n\\n DAY 6 \\n\\nMorning Activities: \\nThe day began with a morning drill, fostering unity among the volunteers. The final flag hoisting ceremony took place, symbolizing the dedication to community service. A hearty breakfast was served to prepare the volunteers for the day''s events. \\n\\nValedictory Function: \\nThe function was held near the banyan tree, next to the temple and Panchayat office. \\nDistinguished Guests: The event was attended by: \\nGeeta K.S. Ma''am – Vice Principal, RVCE \\nUmaDevi Ma''am – Dean of Student Academics, RVCE \\nShireesha Ma''am – Professor \\nRamaa Ma''am – Professor \\nRamesh – Village Panchayat President \\nMurthy – Panchayat Development Officer (PDO) \\nNetravati Ma''am – Founder, Pranava Foundation \\nRaakesh Sir – Founder, Pranava Foundation \\nGuests were welcomed with a ceremonial walk in appreciation. \\n\\nInaugural Ceremony: \\nThe event began with a Ganesh invocation, followed by a Mahabharata dance drama. Traditional Bharatanatyam and Kathak dances were performed. Guest Speeches and Acknowledgements: Guests praised the NSS camp''s success and the volunteers'' efforts. Lokeshwari Ma''am was honored by the village community for her leadership. \\n\\nConclusion of the Event: \\n\\nPranava Foundation distributed free books and stationery to schoolchildren. Volunteers enjoyed a farewell lunch before heading back to RVCE, Bengaluru, around 5:30 PM.","aicteMapping":"To skill rural population","pointsEarned":40,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/Pu8UauLgK5anlwwz4VJ1b.jpeg","certificateAttached":true,"detailedReportPageNo":"3-9","signatureOfCounsellor":""},{"id":"Rs5Oqrij26T7jbVMbbUsI","name":"Azadi Ka Kalotsav","slNo":3,"place":"Manekshaw Parade Ground","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/eYR3yFtDSTWA0tv9e7lB8.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/j8IKV4_Bu9ACXD7mM_cQJ.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/NI1-36HawZCHYdMIEk0vJ.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/TRCNQrVMf01tufybj8WFR.jpeg"],"endDate":"2024-08-15","duration":22,"outcomes":"Developed a strong sense of patriotism and national pride by participating in the 78th Independence Day state-level celebrations. Gained exposure to a large-scale state-level cultural programme, understanding its planning and execution. Improved discipline, punctuality, and time management through continuous practice from 25/07/2024 to 15/08/2024. Enhanced teamwork, coordination, and cooperation by working closely with fellow NSS volunteers and performers. Boosted self-confidence and stage presence by performing before a large audience and the Honourable Chief Minister of Karnataka. \\n\\nImproved physical fitness, stamina, and flexibility through regular dance practice and rehearsals. Developed a deeper appreciation for Indian culture and traditional dance forms, promoting cultural awareness. Strengthened commitment to the core values of the National Service Scheme (NSS) such as social responsibility, unity, and national integration. ","semester":"4","startDate":"2024-07-25","hoursSpent":120,"description":"\\nI was part of the 78th Independence Day Cultural Programme – 2024, a prestigious state-level event in which the NSS Unit of RV College of Engineering was officially selected by the Department of Youth Empowerment and Sports, Government of Karnataka, to participate in the Independence Day celebrations held on 15 August 2024 at the historic Field Marshal Manekshaw Parade Ground, Bengaluru. I participated in this programme as an NSS volunteer and cultural performer, representing my institution on a prominent public platform. \\n\\nThe programme was organised under the guidance of Shri. Prathap Lingaiah, State NSS Officer, National Service Scheme Cell, Department of Youth Empowerment and Sports, and was graced by the presence of the Honourable Chief Minister of Karnataka, Shri Siddaramaiah. The event brought together selected NSS units, cultural troupes, and youth representatives from across the state, making it a significant occasion that reflected the spirit of patriotism, unity, and national pride. \\n\\nThe cultural presentation was thematically designed to highlight the Five Guarantee Schemes of the Government of Karnataka, namely Gruha Lakshmi, Gruha Jyothi, Anna Bhagya, Shakti, and Yuva Nidhi. These schemes aim to promote social welfare, women empowerment, food security, energy support, mobility assistance, and youth development. Through artistic expression, the performances conveyed the importance of inclusive governance and social responsibility, aligning cultural heritage with contemporary social initiatives. \\n\\nI actively participated in the Peacock Dance, which symbolises grace, cultural richness, harmony, and national pride. The overall cultural programme was a well-structured and synchronised performance that incorporated a variety of classical, folk, and contemporary dance forms such as Bharatanatyam, Peacock Dance, Yakshagana, Dollu Kunita, and freestyle dance forms. Each dance form represented different aspects of Karnataka’s diverse cultural traditions and contributed to the effective communication of the programme’s central theme. \\n\\n The preparation for this prestigious event was extensive and disciplined. The practice sessions commenced on 25/07/2024 and continued regularly until the final performance on 15/08/2024. All rehearsals were conducted under the guidance of well-known and experienced professional dancers, who provided structured training in choreography, rhythm, expression, posture, and stage coordination. Equal emphasis was given to physical fitness, discipline, teamwork, and time management. The month-long preparation helped participants develop confidence and professionalism, enabling us to perform effectively before a large audience and distinguished dignitaries. \\n\\n Participation in this state-level programme also strengthened coordination among NSS volunteers, encouraged mutual support, and promoted a sense of collective responsibility. The experience of practising together, overcoming challenges, and refining the performance fostered unity and leadership qualities among the participants. The cultural programme served not only as a platform for artistic expression but also as a medium to promote national values and social awareness. \\n\\n Through the collective dedication, discipline, and commitment of all participants, the NSS Unit of RV College of Engineering secured a Special Prize in the 78th Independence Day Cultural Programme – 2024. This achievement brought pride and recognition to the institution and highlighted the active involvement of NSS volunteers in state-level cultural and national events. The recognition also served as motivation for students to actively participate in future cultural, social, and national initiatives. \\n\\n Overall, participation in the 78th Independence Day Cultural Programme was a highly enriching and memorable experience. Performing at the Manekshaw Parade Ground, a venue of national importance, in the presence of the Honourable Chief Minister of Karnataka, strengthened my sense of patriotism and responsibility as a citizen and NSS volunteer. The activity significantly contributed to my personal growth by enhancing confidence, discipline, teamwork, cultural awareness, and leadership skills. It also reinforced the values of national service, unity in diversity, and commitment to social welfare, which are the core objectives of the National Service Scheme. ","aicteMapping":"Food preservation/packaging","pointsEarned":30,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"10-12","signatureOfCounsellor":""},{"id":"hdXut8JB59YCOZcsUIIuQ","name":"NSS Utsarga Marathon 2025","slNo":4,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/70geakXQ-yh-g-sbRcGYD.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/dDEEvlaaKgVoSfN-_Qelm.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/rOzi3fD3gZl8rgnIEuS1N.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/9ad40624-fe2a-47f3-9aca-cc571946dd1a/fITh0ItHUqPRilJATelhF.jpeg"],"endDate":"2025-04-06","duration":1,"outcomes":"The event successfully raised funds for a meaningful cause, united volunteers, and inspired change, leaving us with a sense of accomplishment and contribution to society","semester":"6","startDate":"2025-04-06","hoursSpent":80,"description":"I served as the Core Operations Head of NSS RVCE for Utsarga Marathon 2025, the flagship annual event held on 6th April 2025 under the theme “Help a Child, Change the World.” The marathon featured 5 km and 10 km categories and saw enthusiastic participation in support of a noble social cause. \\n\\nThe event was graced by Mr. Prathap Lingaiah, Karnataka State NSS Officer and Ex-Officio Joint Secretary, NSS, Department of Youth Empowerment & Sports, Bengaluru, along with the respected Principal, Vice-Principal, Dean of Student Affairs, and Dean of Academics of RVCE. \\n\\nIn my role, I was involved in end-to-end planning and execution, including logistics coordination, volunteer deployment, registration workflow management, and inter-team operations. I worked closely with multiple teams such as Publicity & Registration, Stage & Hospitality, Production, and Design to ensure smooth coordination. I also supervised on-ground arrangements like systematic T-shirt and BIB distribution and managed real-time operations, including on-the-spot registrations","aicteMapping":"To skill rural population","pointsEarned":20,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"13-15","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-30 05:21:42.364213+00', '2026-01-30 09:32:27.458029+00'), ('050444d1-2fdb-4604-81c5-bc095b31969f', 'de538226-453b-459a-a050-8d475d0c7d98', '{"student":{"usn":"1RV22CS133","name":"Om Gupta","period":"2022-2026","department":"Computer Science & Engineering","totalPoints":0},"activities":[{"id":"1a9HX-lmIZXp7uYKfa9m8","name":"Fast Trek 2023","slNo":1,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/de538226-453b-459a-a050-8d475d0c7d98/OKX8eW0WM9O4Bk84cHkVD.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/de538226-453b-459a-a050-8d475d0c7d98/SxeBw73gMLzbuONMDfQEi.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/de538226-453b-459a-a050-8d475d0c7d98/NZPeI9-VX1mna-UG7nPrW.png","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/de538226-453b-459a-a050-8d475d0c7d98/pmCRxoj0sS1Bud0g0ozKe.png"],"endDate":"2023-02-12","duration":1,"outcomes":"Developed physical endurance and resilience by completing the trek. Learned the importance of team coordination and peer support in physically demanding situations, while also gaining a deeper appreciation for local geography and environmental conservation.","semester":"1","startDate":"2023-02-12","hoursSpent":10,"description":"Participated in the \"Fast Trek\" annual trekking expedition organized by the Rotaract Club of RVCE. This activity involved a rigorous physical trek designed to promote fitness, team bonding, and environmental appreciation among students. The event required navigating difficult terrains and trails while adhering to \"leave no trace\" principles to preserve the natural habitat.","aicteMapping":"Trekking Expedition","pointsEarned":5,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"1-2","signatureOfCounsellor":""},{"id":"HDoSyluTkzv6dkmVsLZPa","name":"Blood Donation Camp","slNo":2,"place":"RVCE","photos":[],"endDate":"2023-06-06","duration":1,"outcomes":"The outcome of this activity was the successful contribution to a vital life-saving resource, directly impacting the availability of blood for emergency and elective medical procedures. Personally, I developed a deeper sense of social accountability and understood the practical challenges involved in public health management. This engagement not only strengthened my empathy and ethical values but also demonstrated how individual actions, when aligned with organized community efforts like those of the Lions Club, can provide significant support to the healthcare system.","semester":"2","startDate":"2023-06-06","hoursSpent":2,"description":"On June 6, 2023, I participated in a voluntary blood donation drive at RVCE organized by the Lions Blood Centre (Bangalore Lions Service Trust), where I contributed O+ Positive blood to support local emergency medical reserves. This experience was a significant exercise in social responsibility and civic duty, allowing me to engage directly with humanitarian efforts aimed at strengthening the community''s healthcare infrastructure. By participating in this drive, I gained valuable insights into the logistical operations of social welfare programs and the importance of selfless service, successfully fulfilling the community engagement objectives required for AICTE Activity Points.","aicteMapping":"Community Development/Social Awareness","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/de538226-453b-459a-a050-8d475d0c7d98/wSgJaVaCE3qbStOoNQHsI.png","certificateAttached":true,"detailedReportPageNo":"3-4","signatureOfCounsellor":""},{"id":"fGAWGrqys57_o6pAr6T5h","name":"Utsarga Marathon 2024","slNo":3,"place":"RVCE","photos":[],"endDate":"2024-02-04","duration":1,"outcomes":"The primary outcome of this activity was the successful mobilization of resources and awareness for child welfare, directly supporting social initiatives focused on reshaping the lives of underprivileged children. Participation in this marathon enhanced my understanding of how fitness events can be effectively leveraged as tools for social impact and community building. By completing the run and earning 10 activity points, I demonstrated a sustained commitment to social causes and further developed my personal sense of empathy and civic responsibility.","semester":"3","startDate":"2024-02-04","hoursSpent":5,"description":"On February 4, 2024, I participated in the Utsarga Marathon 2024, a community initiative organized by the National Service Scheme (NSS) at RVCE. Running in the 5 KM category, I joined fellow students under the social theme, ''Help a Child Change the World,'' which aimed to raise awareness and provide support for children in need. This event served as a platform for promoting physical wellness and vitality while channeling collective student efforts toward a significant charitable cause, aligning with the community engagement goals of the AICTE Activity Points program.","aicteMapping":"Health and Hygiene/Wellness Awareness","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/de538226-453b-459a-a050-8d475d0c7d98/qZ-Q75a8sXQmMIgVILrLC.jpeg","certificateAttached":true,"detailedReportPageNo":"5-6","signatureOfCounsellor":""},{"id":"xEpZyt8bxz0Y8IXGVjUgG","name":"Blood Donation Camp","slNo":4,"place":"RVCE","photos":[],"endDate":"2024-06-28","duration":1,"outcomes":"The activity contributed to saving precious lives through voluntary blood donation and helped develop a strong sense of social responsibility and humanitarian values. It increased awareness about the significance of regular blood donation, encouraged community involvement, and reinforced commitment toward public service through official recognition from the Indian Red Cross Society.","semester":"4","startDate":"2024-06-28","hoursSpent":4,"description":"I voluntarily participated in a Blood Donation Camp organized by the Indian Red Cross Society, Karnataka State Branch, with the aim of contributing to community health and saving lives. The donation was carried out under proper medical supervision while following all safety and hygiene protocols. This activity helped promote awareness about the importance of blood donation and encouraged active participation in humanitarian and social welfare initiatives.","aicteMapping":"Community Service / Social Outreach Activities","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/de538226-453b-459a-a050-8d475d0c7d98/kHLnh72zpalslcBPh0oiw.png","certificateAttached":true,"detailedReportPageNo":"7-8","signatureOfCounsellor":""},{"id":"n0d7xfVUctXNjoXtGd7FB","name":"Fist Full 2024","slNo":5,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/de538226-453b-459a-a050-8d475d0c7d98/0n4fWFdVOPZyrbexwINUX.png","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/de538226-453b-459a-a050-8d475d0c7d98/U9An3ItDEyfkCEFEuFgpO.png"],"endDate":"2024-11-29","duration":15,"outcomes":"Gained a profound understanding of food insecurity issues within the city. Learned how micro-donations (a \"fistful\") from a large community can accumulate to create a massive macro-impact, feeding hundreds of needy individuals. ","semester":"5","startDate":"2024-11-15","hoursSpent":3,"description":"In this initiative by the Rotaract Club of RVCE in collaboration with Rotary Bangalore Spandana, students were encouraged to donate 5 kg of rice or 2 kg of toor daal, with daily collections in the Civil Department. The drive garnered an overwhelming response with the total amount of 6,700+ kg of rice and 800+ kg of toor dal donated by 1750+ students. This initiative highlighted the power of small efforts to drive significant societal change, reinforcing RVE''s dedication to community welfare and solidarity. ","aicteMapping":"Food preservation/packaging","pointsEarned":10,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"9-10","signatureOfCounsellor":""},{"id":"t0kcPJq42cx6ZzLXm9IPP","name":"Utsarga Marathon 2025","slNo":6,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/de538226-453b-459a-a050-8d475d0c7d98/NiEAL08rvlFaLqD-eteNJ.png"],"endDate":"2025-04-06","duration":1,"outcomes":"The activity strengthened my sense of social responsibility and commitment to community service. It enhanced awareness about the role of youth in nation-building, encouraged active participation in social initiatives, and contributed toward personal development through teamwork, discipline, and service-oriented values. The participation was officially recognized through the award of NSS activity points.","semester":"6","startDate":"2025-04-06","hoursSpent":5,"description":"I participated in UTSARGA Marathon 2025, organized under the National Service Scheme (NSS) by R V College of Engineering, as part of community service and social responsibility initiatives. The event aimed to promote social awareness, civic responsibility, and active participation in community welfare through collective engagement. Participation in the marathon reflected commitment toward serving society and contributing positively to social causes.","aicteMapping":"Community Service / Social Outreach Activities (NSS Activity)","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/de538226-453b-459a-a050-8d475d0c7d98/R66KCbIXX4WIRF9EZj85b.jpeg","certificateAttached":true,"detailedReportPageNo":"11-13","signatureOfCounsellor":""},{"id":"JNg7ByZTKCz1jPjo5R71C","name":"Lakshya Event","slNo":7,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/de538226-453b-459a-a050-8d475d0c7d98/IKaXnwbxRGv4Pp8Wu_dxc.png","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/de538226-453b-459a-a050-8d475d0c7d98/XoLf9CkRM6pOugpl8eFKc.png","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/de538226-453b-459a-a050-8d475d0c7d98/wxrkcWNSd0jjsCnDCj-d7.jpeg"],"endDate":"2025-04-27","duration":2,"outcomes":"The event successfully enhanced participants’ technical skills, concentration, and sense of discipline while ensuring safety and effective learning. The sapling distribution initiative fostered environmental consciousness and encouraged students to actively contribute to sustainability within the campus and beyond. Overall, Lakshya achieved a meaningful balance between physical skill development and social responsibility, creating a positive and lasting impact on student development.","semester":"6","startDate":"2025-04-26","hoursSpent":4,"description":"“Lakshya” was a shooting event organized by the NCC unit at R V College of Engineering on 26th and 27th April 2025, aimed at developing discipline, focus, and teamwork among students through supervised and structured shooting activities. The event also emphasized environmental responsibility through a sapling distribution drive, where each participant was provided with a sapling and proper instructions for planting and care, thereby integrating skill development with ecological awareness and promoting sustainable practices among students.","aicteMapping":"Community Service/Social Outreach Activities (NCC Activity)","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/de538226-453b-459a-a050-8d475d0c7d98/DrtsdhmjWOXB4kpe8_bzA.jpg","certificateAttached":true,"detailedReportPageNo":"14-16","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"Jyoti Shetty","designation":"Dr"},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-30 19:46:55.470399+00', '2026-02-01 15:24:13.649714+00'), ('05853693-9e67-4764-a55f-2f958ae23a80', 'd35c5425-15e1-4c65-b496-8c2e2f1d3e8b', '{"student":{"usn":"1RV22EI032","name":"Medha K S Puranik","period":"2022-2026","department":"Electronics & Instrumentation Engineering","totalPoints":0},"activities":[{"id":"G8G_oQ5ZEIJc8gjft1Hzo","name":"FistFul 2024","slNo":1,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/RNM8S_8AKxtBFOCiIy0sW.png"],"endDate":"2024-11-15","duration":1,"outcomes":"A. The Power of \"Micro-Giving\"\\nYou learned that you don''t need to be a wealthy philanthropist to make a difference. By saving just a \"fistful\" daily, you saw how small, consistent actions aggregate into a massive resource that can feed hundreds of people.\\n\\nB. Social Empathy & Awareness\\nParticipating in this event likely made you more aware of your own consumption. Setting aside grain every day serves as a daily reminder of food insecurity—the reality that while we have plenty, others struggle for a single meal.\\n\\nC. Resource Management & Logistics\\nYou gained insight into how a large-scale NGO operation works. From your individual collection to the club''s massive 6.5-ton distribution, you saw the importance of standardization (why they asked for specific weights) to ensure fair and organized distribution.\\n\\nD. Civic Responsibility\\nBy earning your AICTE activity points through this, you learned that your role as an engineer is not just technical, but social. You practiced \"Service Above Self,\" understanding that professional life and community service should go hand-in-hand.","semester":"6","startDate":"2024-11-15","hoursSpent":1,"description":"Core Objective: To address food insecurity and foster a spirit of mindful giving among students through the collection of essential food grains.\\n2. Description of the Activity\\n\"Fistful\" was a community service initiative designed to bridge the gap between individual households and underprivileged communities. The project was rooted in the philosophy that small, consistent contributions can lead to significant collective impact.\\n\\nThe Process:\\n\\nDaily Discipline: For a duration of 15 days, participants practiced the habit of setting aside a \"fistful\" of rice or toor dal every time they prepared a meal.\\n\\nSustainability & Awareness: This method encouraged participants to become more conscious of food waste and the value of basic staples.\\n\\nLogistics: Following the 15-day collection period, participants consolidated their contributions. To meet the standardized donation requirements and ensure a meaningful impact, the goal was set at either 5 kg of Rice or 2 kg of Toor Dal.\\n\\n3. Social Impact & Learning Outcomes\\nCommunity Welfare: The collected grains were distributed to local communities in need, directly contributing to hunger alleviation.\\n\\nCivic Responsibility: As a participant, this project reinforced the importance of the Rotary International motto, \"Service Above Self,\" and the role of students in supporting local NGOs.\\n\\nScale of Impact: By standardizing the donations, the Rotaract Club ensured that the total collection reached a volume capable of supporting multiple families or community kitchens for an extended period.","aicteMapping":"Food preservation/packaging","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/ywJV-CMV8yPqdsa7rXEy1.jpg","certificateAttached":true,"detailedReportPageNo":"1-4","signatureOfCounsellor":""},{"id":"sNO0Md4eIUuh6IbUy7YvM","name":"Fast Trek 2.0","slNo":2,"place":"Kunagalu Betta Hills","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/AD5Df8dHNACKtOesmKFcE.jpeg"],"endDate":"2024-01-28","duration":1,"outcomes":"Participating in and executing an event of this scale provided several key takeaways:\\n\\nEnvironmental Awareness: The activity reinforced the importance of \"sustainable trekking,\" highlighting how large-scale human activity can be managed responsibly to minimize environmental impact.\\n\\nOperational Management: With 750+ attendees, the event served as a lesson in large-scale logistics, from coordinating transportation and safety protocols to managing crowd flow in a rugged outdoor setting.\\n\\nTeam Collaboration: Navigating the hills while pursuing a collective goal of environmental preservation fostered high levels of teamwork and communication among the participants and the organizing committee.\\n","semester":"4","startDate":"2024-01-28","hoursSpent":7,"description":"Fast-Trek was a flagship trekking event organized by the Rotaract Club of RVCE, designed to combine outdoor adventure with environmental stewardship. The activity took place at Kunagalu Betta Hills, involving over 750 participants.\\n\\nThe event followed a structured itinerary:\\n\\nLogistics & Safety: The day began at 7:30 AM with organized transportation to the site. Prior to the trek, all participants received comprehensive safety briefings and event guidelines.\\n\\nThe Trek: Participants traversed the scenic landscapes of Kunagalu Betta, fostering a sense of community and physical engagement.\\n\\nEnvironmental Initiative: The core social objective was a cleanliness drive. Throughout the trek, efforts were dedicated to preserving the natural environment by managing waste and ensuring the trail remained pristine.","aicteMapping":"Tourism approaches through innovative approaches","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/aQdRFXaHW0tqyGpkvljSI.jpg","certificateAttached":true,"detailedReportPageNo":"5-6","signatureOfCounsellor":""},{"id":"iJ1HcV5hLg3tlz6g86LTl","name":"Female Feticide Walkathon","slNo":3,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/id1gbi1jRqrualhzBOMQ-.png"],"endDate":"2024-05-11","duration":-364,"outcomes":"Participating in this walkathon provided significant insights into social advocacy and community health:\\n\\nSocial Advocacy: I learned how organized public events can serve as powerful tools for raising awareness about sensitive issues like female foeticide and gender equality.\\n\\nCommunity Engagement: The activity demonstrated the impact of institutional partnerships—in this case, between a college club and healthcare providers—to amplify a social message.\\n\\nEmpathy and Ethics: The event emphasized the ethical necessity of protecting vulnerable groups and ensuring that the \"daughters of tomorrow\" have an equitable chance to succeed in society.\\n\\nPublic Awareness: A key outcome was the successful dissemination of a message focused on the inherent value of women, aiming to shift social perspectives within the local community.","semester":"6","startDate":"2025-05-11","hoursSpent":5,"description":"The Female Foeticide Awareness Walkathon was a community-focused event held on May 11, 2025, at the RV College of Engineering. Organized by the Rotaract Club of RVCE in collaboration with Bangalore Hospitals, the walkathon served as a public demonstration to advocate for the rights and value of the girl child. Participants gathered to promote a social environment where future generations of women are welcomed, valued, and provided the opportunity to thrive.","aicteMapping":"Setting of the information imparting club for women leading to contributing in social and economic issues","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/9_K948dTpvC3MhzbqWGpK.jpg","certificateAttached":true,"detailedReportPageNo":"7-8","signatureOfCounsellor":""},{"id":"Fsb832daBkZS49dpqI8rz","name":"Campus Cleanup - 1","slNo":4,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/CnZ0hmvw_otFzQoTGTI_d.png","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/y9yd0pOS9OmMJ2jSTSbGW.png"],"endDate":"2024-01-13","duration":1,"outcomes":"Participating in this drive provided valuable lessons in civic responsibility and environmental impact:\\n\\nWaste Management Awareness: I gained a better understanding of the sheer volume of waste generated daily and the critical importance of segregation at the source to facilitate recycling.\\n\\nAccountability: The experience reinforced the idea that maintaining a clean environment is a collective responsibility, and individual actions directly contribute to the overall health of the campus.\\n\\nCommunity Impact: A key outcome was the immediate visual and sanitary improvement of common areas, making the campus a more pleasant space for everyone.\\n\\nSustainability Mindset: The activity encouraged a shift toward more sustainable personal habits, such as reducing the use of single-use plastics to prevent littering before it starts.","semester":"4","startDate":"2024-01-13","hoursSpent":4,"description":"This activity was a focused campus cleanup initiative where volunteers systematically navigated the college grounds to collect and manage litter. The primary goal was to improve the local environment through direct action.\\n\\nWaste Collection: The team moved through various campus zones, identifying and picking up discarded materials such as plastics, paper, and non-biodegradable waste.\\n\\nProper Disposal: Rather than just gathering trash, the activity emphasized responsible waste management by ensuring all collected items were sorted and disposed of in the correct designated bins.\\n\\nEnvironmental Stewardship: The drive served as a practical effort to maintain a clean, hygienic, and aesthetically pleasing educational environment for the student body.","aicteMapping":"Developing and managing efficient garbage disposable system","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/TPHr1xo2uv6RX8h7oyvyA.jpg","certificateAttached":true,"detailedReportPageNo":"9-11","signatureOfCounsellor":""},{"id":"GPkcNhuNFrhU-h5LnrXlS","name":"UTPT - 2025","slNo":5,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/4wLrg2SxRwx5U3wzy9VPg.png"],"endDate":"2025-05-25","duration":3,"outcomes":"Participating in an event of this caliber offers several intellectual and professional growth opportunities:\\n\\nCritical Thinking and Deduction: I learned how to use \"workable\" clues within a question to derive an answer, even when the specific fact wasn''t initially known, enhancing my logical reasoning skills.\\n\\nKnowledge Breadth: The event significantly expanded my awareness of global and local affairs, history, and culture, fostering a well-rounded perspective beyond my core engineering curriculum.\\n\\nPerformance Under Pressure: Competing in a timed environment with a live audience helped improve my quick-thinking abilities and confidence in high-pressure situations.\\n","semester":"6","startDate":"2025-05-23","hoursSpent":7,"description":"Under the Peepal Tree (UTPT) is the flagship annual quiz festival organized by QuizCorp, the official quizzing society of RV College of Engineering. Known as one of India''s largest and most prestigious student-run quiz fests, it typically features a series of themed quizzes spanning several days.\\n\\nThe activity involves:\\n\\nCompetitive Quizzing: Participants engage in rigorous preliminary rounds followed by high-stakes finals, competing against top quizzing talent from across the country.\\n\\nDiverse Categories: The event covers a vast range of topics, including general knowledge, sports, entertainment, India-specific trivia, and technical themes.\\n\\nIntellectual Engagement: The quiz is designed to test not just rote memorization, but lateral thinking, logical deduction, and the ability to connect disparate facts under pressure.","aicteMapping":"Promotion of appropriate technologies","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/OrWLfPqayFvw1w6LBxLz-.png","certificateAttached":true,"detailedReportPageNo":"12-13","signatureOfCounsellor":""},{"id":"kxEq5l5Tc-JpRZZRLIfNp","name":"Police Marshal","slNo":6,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/inKL0bfq9DJnULFdFPFsL.png"],"endDate":"2024-12-18","duration":1,"outcomes":"The event provided essential knowledge regarding civic safety and personal security:\\n\\nCrisis Management Protocols: I learned the specific, step-by-step actions to take during an emergency to ensure both personal safety and the effective notification of authorities.\\n\\nLegal & Safety Awareness: The session clarified the rights of citizens and the responsibilities of the police, making the process of seeking help feel more accessible and less intimidating.\\n\\nCommunity Policing Insights: I gained a deeper understanding of how \"Marshal\" systems work to provide a faster, more localized response than traditional precinct-based models.\\n\\nEnhanced Preparedness: A key outcome was the acquisition of a \"safety toolkit\"—knowing exactly which numbers to call and which apps to use—reducing response time in potential future crises.","semester":"5","startDate":"2024-12-18","hoursSpent":4,"description":"This event was a collaborative community safety initiative led by local Police Marshals aimed at bridging the gap between law enforcement and the public. The session focused on proactive safety measures and established clear protocols for emergency response.\\n\\nAwareness Session: Officers conducted an interactive briefing on common public safety concerns, local crime prevention strategies, and the role of Police Marshals in the community.\\n\\nEmergency Resource Discussion: The marshals provided a detailed walkthrough of available help channels, including emergency helplines, mobile safety apps, and the nearest contact points for immediate assistance.\\n\\nPublic Interaction: The event allowed for a direct Q&A session where participants could discuss specific safety issues and understand the legal frameworks for seeking protection or reporting incidents.","aicteMapping":"Social Responsibility and Community Engagement","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/Tg6boCqPghyxEDAA8mOqj.jpg","certificateAttached":true,"detailedReportPageNo":"14-15","signatureOfCounsellor":""},{"id":"kMc3lc-VV5ON_bvGBvOSF","name":"Nature Camp","slNo":7,"place":"Doresanipalya Forest Camp, Bengaluru","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/7GeowqFF4YFhNh4sXN6hS.png"],"endDate":"2024-11-08","duration":1,"outcomes":"Participating in this government-backed initiative provided deep insights into ecological conservation:\\n\\nEcosystem Awareness: I gained a first-hand understanding of forest ecology and the critical role that urban green spaces play in maintaining local biodiversity and climate regulation.\\n\\nSustainable Habits: The program reinforced the \"LiFE\" (Lifestyle for Environment) framework, teaching me practical ways to reduce my carbon footprint and conserve natural resources in a city like Bangalore.\\n\\nPolicy & Management: I learned about the administrative side of environmental protection through interaction with EMPRI officials, understanding how policy research translates into field-level conservation.","semester":"5","startDate":"2024-11-08","hoursSpent":6,"description":"The Nature Camp was a specialized environmental immersion program held on November 8, 2024, at the Doresanipalya Forest Campus in Bengaluru. Organized by the Environmental Management and Policy Research Institute (EMPRI), Government of Karnataka, this initiative was part of the Environment Education Programme supported by the Ministry of Environment, Forest & Climate Change, Government of India.\\n\\nThe activity involved:\\n\\nField Exploration: Guided exploration of the forest campus to observe local flora and fauna in their natural habitat.\\n\\nConservation Workshops: Educational sessions focused on \"Lifestyle for Environment\" (LiFE) principles, teaching sustainable daily practices.\\n\\nBiodiversity Education: Detailed briefings on the importance of forest ecosystems and the specific environmental challenges facing urban forest patches like Doresanipalya.","aicteMapping":"Environmental Science and Sustainability / Social Responsibility","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/iVteclgmrCO4uY-MUdCHE.png","certificateAttached":true,"detailedReportPageNo":"16-17","signatureOfCounsellor":""},{"id":"UzQz2vh3NpQ3eXlbt6zSq","name":"Utsarga Marathon","slNo":8,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/uzSmxLFuWNjwEkEyd28Hm.jpeg"],"endDate":"2025-04-06","duration":1,"outcomes":"Participating in this marathon yielded several personal and community-oriented outcomes:\\n\\nPhysical Endurance and Discipline: The event helped in building physical stamina and the mental fortitude required to complete a long-distance run.\\n\\n\\nCivic Responsibility: By participating in an NSS-led event, I gained a deeper appreciation for community service and the role students play in driving social awareness.\\n\\nCommunity Solidarity: Running for a cause provided a platform to connect with a diverse group of individuals, strengthening the bond between the institution and the local community.","semester":"6","startDate":"2025-04-06","hoursSpent":5,"description":"The Utsarga Marathon 2025 was a community-centric athletic event organized by the National Service Scheme (NSS) unit of RV College of Engineering. This initiative was designed to promote physical fitness while fostering a sense of social responsibility among students.\\n\\nThe activity involved:\\n\\n\\nCommunity Engagement: Participating in a large-scale organized run alongside peers and community members to support social causes.\\n\\n\\nInstitutional Participation: Representing the college under the guidance of the NSS Programme Officer and the Principal.\\n\\n\\nCommitment to Service: Engaging in the event as a form of community service, emphasizing the motto of \"Not Me But You\"","aicteMapping":"Contribution to Community Development / Health and Hygiene Awareness","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/ZlPQQcE6fQ63jinkmdmC7.png","certificateAttached":true,"detailedReportPageNo":"18-19","signatureOfCounsellor":""},{"id":"NPTC6RrpKMrdMROUp-IJU","name":"Energy Literacy Training","slNo":9,"place":"Online - Remote","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/HNUPPYOuEB4XmvNvRO-BL.jpeg"],"endDate":"2023-05-05","duration":5,"outcomes":"Completing this 12-module certification led to several key learning outcomes:\\n\\n\\nCarbon Footprint Management: I learned how to quantify personal and institutional energy consumption and identify specific \"waste\" areas to reduce my overall carbon footprint.\\n\\n\\nSolar Energy Proficiency: The course provided a technical and practical understanding of how to transition to solar energy, including how to debunk common myths that prevent its adoption.\\n\\n\\nStrategic Energy Conservation: I gained actionable insights into \"Energy by Locals for Locals,\" emphasizing decentralized energy production and the importance of minimizing usage before switching to renewables.\\n\\n\\nEnvironmental Responsibility: A major outcome was developing a structured approach to achieve carbon neutrality, aligning my personal energy habits with global climate goals.","semester":"2","startDate":"2023-05-01","hoursSpent":10,"description":"The Energy Literacy Training was a comprehensive educational course comprising 12 modules, organized by the Energy Swaraj Foundation. The training was designed to provide a holistic understanding of the energy lifecycle and its broader implications for the planet.\\n\\nThe course covered several critical areas:\\n\\n\\nEnergy Dynamics: Exploration of energy generation, consumption patterns, and the common causes of energy wastage.\\n\\n\\nEnvironmental Impact: Analysis of carbon footprints and how energy usage directly affects the environment.\\n\\n\\nSustainable Solutions: Identification of alternative energy sources, specifically focusing on the adoption of solar energy solutions and clearing common misconceptions about them.\\n\\n\\nClimate Action: Practical approaches to minimizing energy usage and strategies for individuals to become carbon neutral.","aicteMapping":"Reduction in energy consumption","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/cWUD1rIMb6fAzsuoVDAsv.png","certificateAttached":true,"detailedReportPageNo":"20-21","signatureOfCounsellor":""},{"id":"3yzyLvYwkr9WxivLZbUTc","name":"FistFul 2025","slNo":10,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/ZAVt6OOYQiNXpcXmCCBgl.png"],"endDate":"2025-11-22","duration":6,"outcomes":"A. The Power of \"Micro-Giving\"\\nYou learned that you don''t need to be a wealthy philanthropist to make a difference. By saving just a \"fistful\" daily, you saw how small, consistent actions aggregate into a massive resource that can feed hundreds of people.\\n\\nB. Social Empathy & Awareness\\nParticipating in this event likely made you more aware of your own consumption. Setting aside grain every day serves as a daily reminder of food insecurity—the reality that while we have plenty, others struggle for a single meal.\\n\\nC. Resource Management & Logistics\\nYou gained insight into how a large-scale NGO operation works. From your individual collection to the club''s massive 6.5-ton distribution, you saw the importance of standardization (why they asked for specific weights) to ensure fair and organized distribution.\\n\\nD. Civic Responsibility\\nBy earning your AICTE activity points through this, you learned that your role as an engineer is not just technical, but social. You practiced \"Service Above Self,\" understanding that professional life and community service should go hand-in-hand.","semester":"7","startDate":"2025-11-17","hoursSpent":1,"description":"Massive Collection: The initiative typically gathers over 6,500 kg (6.5 tons) of rice and 800 kg of toor dal from the student body.\\n\\nWidespread Distribution: These supplies were distributed among several organizations that support the underprivileged. In the 2024 cycle, the beneficiaries included:\\n\\nNele Foundation (Home for destitute children).\\n\\nPruthvi Foundation (Blind Boys Hostel).\\n\\nAmrutavani Vridh Seva Samithi (Old age home).\\n\\nSai Ashraya Hospital and Sai Satguna Sangraha Trust School.\\n\\nRecognition: Because of the scale of this impact, the project won awards like \"Most Impactful Initiative\" and \"Best Flagship Project\" within the Rotaract District.","aicteMapping":"Food preservation/packaging","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/F1CwEnXSbDgPD_ZieDl9v.jpeg","certificateAttached":true,"detailedReportPageNo":"22-23","signatureOfCounsellor":""},{"id":"ymXCH39txFwoyFiJNxXzN","name":"Secret Santa","slNo":11,"place":"Ananda Marga Children''s home","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/i42V7lySDheBF8uCkwW6B.jpeg"],"endDate":"2025-12-25","duration":1,"outcomes":"This visit was a deeply moving experience that provided several key takeaways:\\n\\nEmpathy and Perspective: I gained a profound understanding of the challenges faced by children in institutional care and the significant impact that even small gestures of kindness can have on their morale.\\n\\nCommunication Skills: Interacting with children from diverse backgrounds improved my ability to communicate with empathy, patience, and clarity.\\n\\nSocial Awareness: The event highlighted the importance of community support systems and the role students can play in contributing to the welfare of underprivileged sections of society.\\n\\nEmotional Intelligence: Managing the logistics of the visit while remaining emotionally present for the children helped me develop better interpersonal sensitivity and self-awareness.","semester":"7","startDate":"2025-12-25","hoursSpent":7,"description":"On the occasion of Christmas, I participated in the Secret Santa outreach event, which involved a visit to the Ananda Marga Children’s Home. The goal of the activity was to share festive joy and provide emotional support to the children residing at the home.\\n\\nThe activity consisted of:\\n\\nInteractive Sessions: Engaging the children in various indoor and outdoor games designed to build rapport and encourage team spirit.\\n\\nSocial Interaction: Spending time talking with the children, listening to their stories, and fostering a sense of belonging and inclusion.\\n\\nDistribution of Goodies: Organizing and distributing festive gifts, sweets, and essential items to the children to celebrate the spirit of Christmas.","aicteMapping":"Social Responsibility and Community Engagement","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/d35c5425-15e1-4c65-b496-8c2e2f1d3e8b/bpmzG5Z7PzpZ6wJCtn2w9.jpeg","certificateAttached":true,"detailedReportPageNo":"24-25","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"Dr. Anand Jatti","designation":"Associate Professor"},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-31 03:27:37.08666+00', '2026-02-01 17:54:11.570734+00'), ('05a40199-3410-4c60-b162-215a17bb0867', '10a718a5-eaf3-4de8-8daf-31b636f7e9ba', '{"student":{"usn":"1RV22CD010","name":"Anumaneni Venkat Balachandra","period":"2022-2026","department":"Computer Science & Engineering - Data Science","totalPoints":0},"activities":[{"id":"rosyGghMeT1Rq-dbAWdb2","name":"Utsarga Marathon","slNo":1,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/SOdYgfQ-KGLC4n-2cviCZ.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/oNSd1DXBjWGvuRca5fwEV.jpeg"],"endDate":"2024-02-04","duration":1,"outcomes":"I gained improvement in physical stamina and endurance by participating in the marathon. The activity also helped me build discipline and motivation through early-morning participation and completing the run. Additionally, it increased my awareness of social contribution, since the marathon supported initiatives related to improving opportunities for children in need.","semester":"3","startDate":"2024-02-04","hoursSpent":6,"description":"The Utsarga Marathon 2024, organized by NSS RVCE, is a marathon event focused on promoting health, fitness, and social responsibility. Scheduled to be held on February 4th, 2024, from 6:00 AM to 10:30 AM at R V College of Engineering (RVCE), the event encourages students and the public to participate in either a 5 km or 10 km run through donation-based registration. With the theme “Help a Child Change the World,” the marathon aims to create awareness and support for education-related social causes, making it more than just a fitness activity and instead a meaningful initiative that connects physical well-being with community impact","aicteMapping":"Spreading public awareness under rural outreach programmes","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/PpffV0InfeeM8b1BHw1CI.jpg","certificateAttached":true,"detailedReportPageNo":"2-3","signatureOfCounsellor":""},{"id":"bTNqyG7cCSVXKtBE-1rqU","name":"Blood Donation Camp","slNo":2,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/nf02-4O5jC71w3F4jfZCP.jpeg"],"endDate":"2023-06-06","duration":1,"outcomes":"A voluntary donation of a sizable quantity of blood to the Lion''s Blood Centre, reinforced the importance of medical aid and support for those in need. It offered us an opportunity to partake in a selfless activity and provide someone with crucial help in a dire situation, driving home the importance of collective and charitable work.","semester":"2","startDate":"2023-06-06","hoursSpent":10,"description":"A team from the Lions Blood Centre, a unit of Bangalore Lions Service Trust (BLST), visited the RVCE Campus on 06/06/2023, to conduct a voluntary blood donation drive. A team of expert nurses and medical professionals used sterile, safe, and professional equipment to extract blood in a safe manner, after conducting preliminary checks to ensure the donor''s eligibility. Donors were also provided with sufficient post-donation precautionary instructions.","aicteMapping":"Promotion of Appropriate Technologies.","pointsEarned":6,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/rEzD8HL0ByAa6qjhqJNHs.jpeg","certificateAttached":true,"detailedReportPageNo":"4-5","signatureOfCounsellor":""},{"id":"qFjIq-gI9DsEt98yaBhiW","name":"Akshara","slNo":3,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/28JwtEdkbOQJC-X2KKm9u.jpeg"],"endDate":"2023-06-10","duration":1,"outcomes":"Participating in the initiative was a meaningful experience that refined my ability to communicate effectively. By conducting a session for a class of students, I learned how to adapt my presentation style to be more interactive and accessible, ensuring that concepts were easily understood. Managing the classroom dynamics, even for a single session, taught me the importance of patience and engagement in the learning process. Furthermore, this direct interaction provided personal insight into the educational disparities faced by these students, fostering a deeper sense of social responsibility and a genuine appreciation for the effort required in the teaching profession.","semester":"2","startDate":"2023-06-10","hoursSpent":12,"description":"The Rotaract Club of RVCE held skill development sessions in eight Bangalore schools, benefiting over 1000 underprivileged students. Targeting financially modest backgrounds, the sessions enhanced academic understanding and provided essential skills. Schools visited included BET Convent, Sai Sri Vidya Chethana, Vishwa Bharathi High School, Kengeri High School, Government Model Primary School, Nehru Memorial School, Priyadarshini Vidhya Kendra School, and Mount Carmel English School. The initiative used interactive methods for curriculum-based learning to ensure relevance and engagement. Volunteers gained valuable experience as teachers, fostering appreciation for the profession and addressing educational disparities. This initiative underscored the power of volunteerism and the need for quality education for all","aicteMapping":"Helping local schools to achieve good result and enhance their enrolment in Higher/ technical/ Vocational Education.","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/lBthkKyQKImWZOTUQ_CJM.jpeg","certificateAttached":true,"detailedReportPageNo":"6-7","signatureOfCounsellor":""},{"id":"racAZ1JcmzYnPUi8H3UhX","name":"ACM Build with GenAI Hackathon","slNo":4,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/KIk2WvP5T2UkH4_9Fl8qo.jpeg"],"endDate":"2024-11-29","duration":1,"outcomes":"As a volunteer for the GenAI Hackathon (powered by EDOCK) held on 29th November 2024 at RVCE, I gained valuable experience in event coordination and student management by supporting the smooth execution of the hackathon. I developed strong communication and teamwork skills by interacting with participants, guiding them when required, and coordinating with the organizing team to ensure timely flow of activities. This volunteering opportunity also improved my leadership, responsibility, and problem-solving abilities, especially while handling on-spot requirements during the event. Additionally, being part of a technology-focused hackathon enhanced my exposure to Generative AI innovations and strengthened my understanding of how collaborative events encourage creativity, innovation, and real-world solution building. Overall, the experience helped me grow professionally by building organizational skills and giving me practical experience in managing a large student-driven technical event.","semester":"5","startDate":"2024-11-29","hoursSpent":12,"description":"The GenAI Hackathon, powered by EDOCK, was successfully organized at RV College of Engineering on 29th November 2024 at the DTL Huddle. The event served as a dynamic platform for students to explore and apply advanced concepts in Generative Artificial Intelligence, focusing on innovative solutions that enable machines to generate content, simulate human-like interactions, and address complex real-world challenges. The hackathon witnessed enthusiastic participation from students who showcased their creativity and technical expertise by developing innovative prototypes within a limited timeframe. Overall, the event encouraged collaborative learning, problem-solving, teamwork, and innovation, creating an enriching experience that promoted emerging AI technologies and their transformative impact across industries","aicteMapping":"Promotion of Appropriate Technologies.","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/LJd_SF98aBm3Zy5GUWZD7.jpeg","certificateAttached":true,"detailedReportPageNo":"8-9","signatureOfCounsellor":""},{"id":"4CuCsh10nntilhLLtXAEU","name":"Data Remix hackathon","slNo":5,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/I0mvKswqN8H3dnQ0fGfzD.jpeg"],"endDate":"2024-03-06","duration":1,"outcomes":"DATA Remix: Clash of Companies proved to be an exhilarating event, where data enthusiasts and problem solvers come together to drive positive change through data-driven innovation. We had an opportunity to witness firsthand, the impact that data-driven insights and technical analytics could make in working towards a better, safer, and healthier tomorrow.","semester":"3","startDate":"2024-03-06","hoursSpent":8,"description":"In this event, teams of 4-5 members embarked on a thrilling journey of data exploration and problem-solving. Each team represented a company and was provided with unique datasets to analyse. Utilizing these datasets, teams delved deep into their company''s performance, seeking insights and opportunities for improvement aligned with the SDGs.","aicteMapping":"Promotion of Appropriate Technologies.","pointsEarned":3,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/b8o-gmLtp1Slv29e2K93L.jpeg","certificateAttached":true,"detailedReportPageNo":"10-11","signatureOfCounsellor":""},{"id":"-VFgz-ObqzSWLojuC8CWp","name":"Fast Trek","slNo":6,"place":"Huthridurga Hills","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/Zey4HJ4nHXxftmLFEZ838.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/GlhoahT2iWFlid5rrjXwV.jpeg"],"endDate":"2023-02-12","duration":1,"outcomes":"As an outcome of this activity, I gained meaningful experience in community service by actively taking part in the cleanliness drive during the trek, which strengthened my sense of environmental responsibility. I also developed better discipline and time management by reporting on time and following the event schedule starting from 7:30 AM. The trek helped improve my physical stamina and endurance while navigating the Huthridurga Hills, and it also enhanced my teamwork and coordination skills through interaction with a large group of participants. Overall, participating in this event gave me a sense of achievement, improved my fitness, and increased my awareness about maintaining cleanliness and protecting nature","semester":"1","startDate":"2023-02-12","hoursSpent":12,"description":"The social cause behind the project was a cleanliness drive during the trek, dedicated to preserving the environment. Commencing at 7:30 AM, participants eagerly boarded the bus to the trekking site, brimming with enthusiasm for the day ahead. Prior to embarking on the adventure, comprehensive safety instructions and event particulars were disseminated to all attendees. Traversing the picturesque Huthridyrga Hills, the trek unfolded as a resounding success, offering participants a memorable journey amidst breathtaking landscapes. Several individuals enthusiastically engaged in the trekking experience, contributing to the event''s vibrant atmosphere.","aicteMapping":"Tourism Promotion Innovative Approaches.","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/J0F6dZAjmjMBK-dfyiOVu.jpeg","certificateAttached":true,"detailedReportPageNo":"12-13","signatureOfCounsellor":""},{"id":"MqDGljEC8jJ2oTFU6sGsw","name":"Fast Trek 2.0","slNo":7,"place":"Kunagalu Betta Hills","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/wQpy3jbMZC0AQJXKWLbhN.jpeg"],"endDate":"2024-01-28","duration":1,"outcomes":"As an outcome of this activity, I gained meaningful experience in community service by actively taking part in the cleanliness drive during the trek, which strengthened my sense of environmental responsibility. I also developed better discipline and time management by reporting on time and following the event schedule starting from 7:30 AM. The trek helped improve my physical stamina and endurance while navigating the Kunagal Betta Hills, and it also enhanced my teamwork and coordination skills through interaction with a large group of participants. Overall, participating in this event gave me a sense of achievement, improved my fitness, and increased my awareness about maintaining cleanliness and protecting nature","semester":"3","startDate":"2024-01-28","hoursSpent":12,"description":"The social cause behind the project was a cleanliness drive during the trek, dedicated to preserving the environment. Commencing at 7:30 AM, participants eagerly boarded the bus to the trekking site, brimming with enthusiasm for the day ahead. Prior to embarking on the adventure, comprehensive safety instructions and event particulars were disseminated to all attendees. Traversing the picturesque Kunagal Betta Hills, the trek unfolded as a resounding success, offering participants a memorable journey amidst breathtaking landscapes. Over 750 individuals enthusiastically engaged in the trekking experience, contributing to the event''s vibrant atmosphere.","aicteMapping":"Tourism Promotion Innovative Approaches.","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/XsVWKIPNTnlKRv20QDaY8.jpeg","certificateAttached":true,"detailedReportPageNo":"14-15","signatureOfCounsellor":""},{"id":"Q-kmR9zTt8xP-LtLofYgj","name":"Fast Trek 3.0","slNo":8,"place":"Narayanagiri Hills","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/PxmqwcLMYklM_-fPC8ORY.jpeg"],"endDate":"2025-01-12","duration":1,"outcomes":"As an outcome of participating in Fast Trek 3.0, I gained a strong sense of environmental responsibility by actively taking part in the cleanliness drive and contributing to preserving the natural beauty of Narayangiri Hills. The trek helped me improve my physical stamina and endurance by completing the trails, while also teaching me discipline and consistency through early-morning participation. I also developed better teamwork and coordination skills by trekking along with a large group and supporting others throughout the journey. Overall, the event gave me a memorable experience of bonding, collective effort, and personal achievement, leaving me feeling accomplished, motivated, and inspired","semester":"5","startDate":"2025-01-12","hoursSpent":12,"description":"Fast Trek 3.0, the biggest flagship event of the Rotaract Club of RVCE, took place on 12th January 2025 at the scenic Narayangiri Hills, bringing together over 500 enthusiastic participants from the college. This adventure-packed event combined trekking with a meaningful cleanliness drive, reinforcing the club’s commitment to environmental responsibility. The trek began early in the morning, with participants embarking on a thrilling journey through the rugged trails of Narayangiri Hills. Amidst breathtaking views, the team actively engaged in cleaning the surroundings, collecting litter, and promoting eco-consciousness. The event not only contributed to preserving the natural beauty of the hills but also instilled a sense of responsibility among students. Beyond the cause, Fast Trek 3.0 fostered incredible team bonding, as participants supported and motivated one another throughout the trek. Laughter, shared experiences, and the collective effort to make a difference created an unforgettable experience. The event concluded on a high note, with participants feeling both accomplished and inspired","aicteMapping":"Tourism Promotion Innovative Approaches.","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/-hXt4k4PJjgpXZ2WV15l1.jpeg","certificateAttached":true,"detailedReportPageNo":"16-17","signatureOfCounsellor":""},{"id":"s6Et8ZdQ5KuaU3E-CBAem","name":"Paper Drive","slNo":9,"place":"Chandra Layout, Bengaluru","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/psq3FgZwWvEpHuBfbvEzU.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/STmgKw8h8G55d991galCv.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/tlgc92W-KTs84gM1TVgwh.jpeg"],"endDate":"2023-06-24","duration":1,"outcomes":"The initiative successfully mobilized a workforce of over 500 volunteers to reclaim more than 7 tonnes of paper waste across Bangalore within a nine-hour operational window. By aggregating and liquidating these recyclable materials—including newspapers, books, and magazines—through commercial vendors, the project generated immediate funds. The final outcome was the direct financial contribution of all proceeds to support the welfare activities of the Nele Narendra Foundation.","semester":"2","startDate":"2023-06-24","hoursSpent":10,"description":"With an overwhelming support of 500+ volunteers, the students collected more than 7 tonnes of newspapers in just over 9 hours! The volunteers, registered for the event, assembled at Kriyakalpa, RVCE at 8:00 AM. Volunteers were taken to different localities of Bangalore by buses to collect all sorts of papers. The incentive behind this was to raise funds by selling the collected old newspapers, books, magazines, waste papers etc. to paper vendors, and donating the same amount for the welfare of the Nele Narendra Foundation.","aicteMapping":"Automation of local activities.","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/CxIdsztpTAEYG5cE8dpJ8.jpeg","certificateAttached":true,"detailedReportPageNo":"18-20","signatureOfCounsellor":""},{"id":"-FczjJBkwjisw2UZTOdr_","name":"Project Pustak","slNo":10,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/sjq6QI3gowK7GCBqrCdoT.jpeg"],"endDate":"2023-05-24","duration":1,"outcomes":"By participating in Project Pustak, I gained a strong sense of social responsibility and satisfaction from contributing towards the education of underprivileged rural students. I understood the real impact that even small contributions can create when combined for a meaningful cause. This activity helped me develop empathy and awareness about the difficulties faced by students who lack basic school resources. I also gained exposure to community service initiatives and learned the importance of teamwork and collective effort in successfully carrying out a donation-based project. Overall, the experience was rewarding as it allowed me to support a noble cause and contribute directly to creating a better learning environment for deserving students.","semester":"2","startDate":"2023-05-24","hoursSpent":2,"description":"Project Pustak is a commendable and noble initiative aimed at providing essential school supplies to underprivileged students living in rural areas. Under this project, a contribution was collected from each donor, and the funds raised were used to procure and donate much-needed educational materials. The collected amount was utilized to purchase resources such as textbooks, stationery items, backpacks, and other important school supplies that help create a better and more supportive learning environment for deserving students. The Rotaract Club of RVCE, in collaboration with the Pranav Foundation, undertook the responsibility of procuring and distributing these essential supplies to ensure meaningful educational support for the beneficiaries","aicteMapping":"To Skill rural population.","pointsEarned":3,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/f3fc3gkxhJsiu_JgHrygz.jpeg","certificateAttached":true,"detailedReportPageNo":"21-22","signatureOfCounsellor":""},{"id":"h1BWU6E2plnSqnIYJp_4-","name":"Project Pustak","slNo":11,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/52-z95KuGjuVjJmiChO7E.jpeg"],"endDate":"2024-04-25","duration":1,"outcomes":"By participating in Project Pustak, I gained a strong sense of social responsibility and satisfaction from contributing towards the education of underprivileged rural students. I understood the real impact that even small contributions can create when combined for a meaningful cause. This activity helped me develop empathy and awareness about the difficulties faced by students who lack basic school resources. I also gained exposure to community service initiatives and learned the importance of teamwork and collective effort in successfully carrying out a donation-based project. Overall, the experience was rewarding as it allowed me to support a noble cause and contribute directly to creating a better learning environment for deserving students.","semester":"4","startDate":"2024-04-25","hoursSpent":2,"description":"Project Pustak is a commendable and noble initiative aimed at providing essential school supplies to underprivileged students living in rural areas. Under this project, a contribution was collected from each donor, and the funds raised were used to procure and donate much-needed educational materials. The collected amount was utilized to purchase resources such as textbooks, stationery items, backpacks, and other important school supplies that help create a better and more supportive learning environment for deserving students. The Rotaract Club of RVCE, in collaboration with the Pranav Foundation, undertook the responsibility of procuring and distributing these essential supplies to ensure meaningful educational support for the beneficiaries","aicteMapping":"RVCE Campus","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/qgDN2Eca8IshUDdqL1-RL.jpeg","certificateAttached":true,"detailedReportPageNo":"23-24","signatureOfCounsellor":""},{"id":"c51iAXRbBQdHIqD6oMMhC","name":"Through the Eyes of Youth","slNo":12,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/fhHj5i8Ohq4mSgK2XVD4q.jpeg"],"endDate":"2023-08-13","duration":7,"outcomes":"I enhanced my creativity and photography skills by capturing meaningful visuals that represent real-world issues aligned with the Sustainable Development Goals (SDGs). The competition helped me develop stronger observation and storytelling ability, as I learned to express social and environmental messages through impactful photographs. It also increased my awareness of SDG-related challenges and encouraged me to think critically about how youth can contribute to positive change. Overall, the activity gave me confidence in presenting my perspective creatively, improved my visual communication skills, and motivated me to engage more actively in socially responsible initiatives","semester":"3","startDate":"2023-08-07","hoursSpent":4,"description":"Organized by the IUCEE RVCE Student Chapter,it is an SDG-themed photography competition titled “Through the Eyes of Youth!” designed to encourage students to creatively capture and present real-world perspectives through photography. The competition provides a platform for youth to express their interpretation of the world, focusing on themes aligned with the United Nations Sustainable Development Goals (SDGs). Open to all RVCE students and students from other IUCEE Student Chapters, the event promotes creativity, awareness, and storytelling through visual media. Participants are invited to submit impactful photographs that reflect social, environmental, or developmental issues, thereby using art as a tool for communication and change. The competition also includes an exciting prize pool of ¹3500, motivating students to actively participate, showcase talent, and contribute towards SDG awareness through their unique lens.","aicteMapping":"Promotion of Appropriate Technologies.","pointsEarned":4,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/nW9YmWhNW-OyEO7QSi0j1.jpeg","certificateAttached":true,"detailedReportPageNo":"25-26","signatureOfCounsellor":""},{"id":"vuRUL80E1aSmOnrJ6ZtMa","name":"Skill Lab for 1st year ECE Students","slNo":13,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/YoiwdLZJfU0BCTkQyfpQO.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/ux_AxIjkczlqK4YwQuVlG.jpeg"],"endDate":"2024-06-14","duration":5,"outcomes":"The skill lab for the ECE department was conducted by The Coding Club in order to give the real time and updated knowledge regarding the basic core subjects of Computer Science. The structure of the event was organized in such a way to make sure the event acted as a bridge between the EC subjects and CSE subjects.\\nThe aim of the event was to help the less privileged students from non-coding backgrounds to upskill themselves and overcome the stigma of coding being hard.\\nThe event was conducted so all the students have foundation in following topics:\\n1. Basics of C++ and fundamentals of OOPs: Basic Syntax, Function, Arrays and vectors. Pointers, Structures and STL in C++. Classes OOPs and Basics of Competitive Programming.\\n2. Operating Systems : Introduction to OS, Definition and purpose of OS with brief history and evolution. Kernel and user space. System class and APIs. Process Vs Thread. Process Management\\n3. Computer Networks: Introduction to networking and networks, Network Hardware, OSI Model, TCP/IP Model and protocols, IPv4 vs IPv6, other important protocols","semester":"4","startDate":"2024-06-10","hoursSpent":6,"description":"The skill lab for the ECE department was conducted by The Coding Club in order to give the real time and updated knowledge regarding the basic core subjects of Computer Science. The structure of the event was organized in such a way to make sure the event acted as a bridge between the EC subjects and CSE subjects.\\n\\nThe aim of the event was to help the less privileged students from non-coding backgrounds to upskill themselves and overcome the stigma of coding being hard.","aicteMapping":"Promotion of Appropriate Technologies.","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/Vv7dnXPOu-ZwIemt1ZVQG.jpeg","certificateAttached":true,"detailedReportPageNo":"27-28","signatureOfCounsellor":""},{"id":"P_rTMfkxxsNUF0taYzU5o","name":"Essay Competition about Space, Science, and Technology","slNo":14,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/5oiJPyREVH_rvFVsrVztT.jpeg"],"endDate":"2023-09-01","duration":2,"outcomes":"The primary result is the demonstration of critical synthesis, where participants prove their ability to deconstruct technical subjects through evidence-based reasoning. Success in the event validates the communication proficiency necessary to bridge the gap between raw technical data and broader understanding. Furthermore, the competition generates a diverse set of analytical frameworks, contributing new intellectual perspectives to contemporary challenges in space and technology.","semester":"2","startDate":"2023-08-31","hoursSpent":4,"description":"This competition functions as a critical forum for analyzing and articulating key concepts within space exploration, scientific discovery, and technological innovation. It challenges participants to explore complex themes, requiring them to synthesize technical research into compelling, logical arguments. The event serves to highlight the intersection of these fields, promoting literacy in STEM while evaluating the ability of entrants to effectively communicate the implications of future advancements without relying on specific technical prerequisites.","aicteMapping":"Promotion of Appropriate Technologies.","pointsEarned":2,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/fYl5UyXOsi1YfGFH7tuPu.jpeg","certificateAttached":true,"detailedReportPageNo":"29-30","signatureOfCounsellor":""},{"id":"XdtFzW3u98yYwdk7BFQ7A","name":"TedXRVCE:2023 “Resonating Chords”","slNo":15,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/aogB6u1Xu1uRY4syBucIp.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/M1j8ovcNgBE4KWot_ARo3.jpeg"],"endDate":"2023-06-08","duration":1,"outcomes":"The primary result is the cultivation of a deeply engaged community aligned through shared intellectual inquiry and inspiration. Participants leave with a broadened perspective, equipped with cross-disciplinary insights that encourage further dialogue and collaboration. Additionally, the event produces a lasting digital archive of the presentations, ensuring that the ideas shared continue to influence and resonate with a wider audience long after the conclusion of the talks.","semester":"2","startDate":"2023-06-08","hoursSpent":6,"description":"This TEDx event explores the power of ideas to amplify impact and foster connection across diverse disciplines. Under the theme \"Resonating Chords,\" the gathering brings together distinct voices to share perspectives that, while unique, collectively contribute to a harmonized understanding of innovation and human experience. The session is designed to provoke deep reflection, illustrating how singular concepts can vibrate outward to create significant, lasting change within the community.","aicteMapping":"Promotion of Appropriate Technologies.","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/-G1bBykS9cVAFkv0DLrd8.jpeg","certificateAttached":true,"detailedReportPageNo":"31-32","signatureOfCounsellor":""},{"id":"ZQLedF0G6vGrsnPsJHsf-","name":"IndiGenius: The India Quiz at UTPT, 2023","slNo":16,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/12350ridN-JQY-1qkU4Yn.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/81JJMEofPYcBj64DhJbug.jpeg"],"endDate":"2023-07-16","duration":3,"outcomes":"As an outcome of participating in the Indi-Genius Quiz, I enhanced my knowledge of Indian culture, history, and traditions through a competitive and interactive learning experience. The event helped improve my critical thinking, recall ability, and time-based decision-making skills while working collaboratively in a team. Participation also strengthened my confidence in expressing ideas and responding under pressure during quiz rounds. Overall, the quiz served as an enriching academic and cultural experience that combined learning, teamwork, and co-curricular development.","semester":"2","startDate":"2023-07-14","hoursSpent":4,"description":"The Indi-Genius Quiz, organized by RV Quiz Corp, was conducted as part of UTPT 2023 on 14th July, 2023 at the IEM Auditorium, RV College of Engineering. The quiz was designed to celebrate India’s rich cultural, historical, and traditional heritage through an engaging and competitive format. The event covered a wide range of topics including Indian history, Mughal architecture, epics such as the Mahabharata and Ramayana, festivals, regional cuisines, and cultural traditions. Conducted in teams of up to three members, the quiz provided participants with an interactive platform to test their knowledge, analytical thinking, and teamwork skills while experiencing the diverse essence of India in an intellectually stimulating environment.","aicteMapping":"Promotion of Appropriate Technologies.","pointsEarned":3,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/cdKxOkUinsYGTzQy3TiWL.jpeg","certificateAttached":true,"detailedReportPageNo":"33-34","signatureOfCounsellor":""},{"id":"w_42apVTfy_sNYmK2hAR6","name":"IndiGenius: The India Quiz at UTPT, 2024","slNo":17,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/ULRcD4eHebsRDjHpGmCrC.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/QgDUTi8AgGkk-5Ub-Mxs4.jpeg"],"endDate":"2024-06-09","duration":3,"outcomes":"As an outcome of participating in the Indi-Genius Quiz, I enhanced my knowledge of Indian culture, history, and traditions through a competitive and interactive learning experience. The event helped improve my critical thinking, recall ability, and time-based decision-making skills while working collaboratively in a team. Participation also strengthened my confidence in expressing ideas and responding under pressure during quiz rounds. Overall, the quiz served as an enriching academic and cultural experience that combined learning, teamwork, and co-curricular development.","semester":"4","startDate":"2024-06-07","hoursSpent":4,"description":"The Indi-Genius Quiz, organized by RV Quiz Corp, was conducted as part of UTPT 2024 on 7th June 2024 at the IEM Auditorium, RV College of Engineering. The quiz was designed to celebrate India’s rich cultural, historical, and traditional heritage through an engaging and competitive format. The event covered a wide range of topics including Indian history, Mughal architecture, epics such as the Mahabharata and Ramayana, festivals, regional cuisines, and cultural traditions. Conducted in teams of up to three members, the quiz provided participants with an interactive platform to test their knowledge, analytical thinking, and teamwork skills while experiencing the diverse essence of India in an intellectually stimulating environment.","aicteMapping":"Promotion of Appropriate Technologies.","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/RHXqxrKiuiKLzq735B7Wg.jpeg","certificateAttached":true,"detailedReportPageNo":"35-36","signatureOfCounsellor":""},{"id":"oHQ8hRDM2juOtovjb5o87","name":"Sustainability Symposium","slNo":18,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/ViWgUVWGi1nFybVx2ZLk_.jpeg"],"endDate":"2023-06-05","duration":1,"outcomes":"The process yields a verified demonstration of analytical writing and subject matter literacy regarding global sustainability issues. It results in the production of reasoned arguments that contribute to the broader discourse on ecological balance and ethical development. Furthermore, the competition identifies and elevates articulate voices capable of translating technical environmental concepts into accessible, persuasive narratives suitable for advocacy and implementation.","semester":"2","startDate":"2023-06-05","hoursSpent":4,"description":"This competition serves as a formal platform for the rigorous examination of environmental stewardship and sustainable development principles. Participants are tasked with analyzing complex ecological challenges and articulating coherent, evidence-based strategies for long-term viability. The event prioritizes the synthesis of research and critical reasoning, requiring entrants to explore the intersection of resource management, policy, and social responsibility within a structured written format.","aicteMapping":"Developing Sustainable Water Management system","pointsEarned":3,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/10a718a5-eaf3-4de8-8daf-31b636f7e9ba/SzzRi27LLt-d4uh7iJi9s.jpeg","certificateAttached":true,"detailedReportPageNo":"37-38","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"Prof. Rajatha Bhat","designation":"Assistant Professor, Dept. of CSE, RVCE"},"evaluator1":{"name":"Evaluator 1","designation":" "},"evaluator2":{"name":"Evaluator 2","designation":" "}}}', '2026-01-30 15:47:39.694415+00', '2026-01-30 17:32:58.898588+00'), ('07acd5de-87a1-48a8-8880-27b6b215edc4', '50c0edf5-41da-49e7-9468-f03450f9690f', '{"student":{"usn":"","name":"","period":"2022-2026","department":"Electronics & Communication Engineering","totalPoints":0},"activities":[{"id":"NCTpeR9kEk5jY-C1dOm4i","name":"","slNo":1,"place":"","photos":[],"endDate":"","duration":0,"outcomes":"","semester":"","startDate":"","hoursSpent":0,"description":"","aicteMapping":"","pointsEarned":100,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-29 13:26:42.17777+00', '2026-01-29 13:26:43.236517+00'), ('08b9f801-3476-46d8-bee8-fa29444ace8e', '0ae856b3-0344-4daf-997f-b56088c398ea', '{"student":{"usn":"1RV22IS071","name":"SURAJ GORAI","period":"2022-2026","department":"Information Science & Engineering","totalPoints":0},"activities":[{"id":"hv46FK8FuUzlbtIL9DU2i","name":"Fist Full 2024","slNo":1,"place":"RVCE  CAMPUS","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/0ae856b3-0344-4daf-997f-b56088c398ea/ZaC9P6NCnywrT-2E-YctF.png"],"endDate":"2024-11-29","duration":15,"outcomes":"Participation in the Fist Full initiative enhanced my understanding of social responsibility and the seriousness of food insecurity faced by many communities. The activity demonstrated how small, consistent individual contributions can collectively lead to a large-scale impact. It helped me develop empathy toward underprivileged sections of society and strengthened my commitment to community welfare. The initiative also improved organizational and coordination skills through structured collection and teamwork, reinforcing the importance of solidarity, compassion, and service-oriented leadership.","semester":"4","startDate":"2024-11-15","hoursSpent":0,"description":"Fist Full was a humanitarian initiative organized by the Rotaract Club of RV College of Engineering (RVCE) in collaboration with Rotary Bangalore Spandana, conducted from 15th to 29th November. The primary objective of the project was to address hunger and food insecurity by encouraging students to contribute essential food grains for the underprivileged.\\n\\nAs part of the initiative, students were motivated to donate 5 kg of rice or 2 kg of toor dal, symbolizing how small individual contributions can collectively create a significant social impact. Daily collections were systematically carried out at the Civil Department, RVCE campus, ensuring smooth coordination and participation.\\n\\nThe project witnessed an overwhelming response from the student community, with over 1,750 students actively participating. In total, 6,700+ kg of rice and 800+ kg of toor dal were collected during the drive. The initiative not only provided substantial support toward combating hunger but also reinforced values of compassion, social responsibility, and community service among students. Fist Full stood as a strong example of collective effort driving meaningful societal change.","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":10,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"2","signatureOfCounsellor":""},{"id":"w08xJ9MijJ6yRUmAcbI_7","name":"Utsarga Marathon","slNo":2,"place":"RVCE CAMPUS","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/0ae856b3-0344-4daf-997f-b56088c398ea/5MJKGn42WlZWyK06y4kXN.jpg"],"endDate":"2024-02-04","duration":1,"outcomes":"The Utsarga Marathon, an annual event organized by the NSS of RVCE, successfully blended fitness, community engagement, and philanthropy, creating a platform for individuals to contribute to a meaningful cause while promoting a healthy lifestyle. With enthusiastic participation from students, faculty, and fitness enthusiasts, the marathon served as a powerful reminder of the importance of collective action in addressing societal challenges. Runners contributed through their registration fees, which were directed toward a noble cause, such as supporting underprivileged communities, funding healthcare initiatives, or contributing to educational and environmental projects.\\n\\nThe overwhelming response from participants highlighted the deep-rooted commitment of RVCE towards community service and social responsibility. Beyond the physical endurance required to complete the marathon, the event fostered a sense of camaraderie and unity among participants, reinforcing the spirit of teamwork and determination. The well-organized event featured structured routes, hydration stations, and medical assistance, ensuring a smooth and safe experience for all runners.\\n\\nAdditionally, the marathon acted as an awareness campaign, encouraging individuals to embrace an active lifestyle while giving back to society. The initiative not only strengthened the bond between students and the community but also showcased how small contributions, when combined, can drive impactful social change.","semester":"4","startDate":"2024-02-04","hoursSpent":0,"description":"Utsarga Marathon is an annual event organized by the National Service Scheme (NSS) of RV College of Engineering, aiming to promote fitness, community engagement, and social responsibility. The event brings together students, faculty, and fitness enthusiasts who participate in the marathon by paying a registration fee. This fee serves a greater purpose, as all the proceeds collected are directed toward a noble cause, such as supporting underprivileged communities, funding healthcare initiatives, or contributing to environmental sustainability projects. The marathon not only encourages physical well-being but also fosters a sense of unity and collective action among participants.\\n\\nBeyond just a race, Utsarga Marathon symbolizes the spirit of giving and service. The event provides a platform for individuals to contribute to meaningful social initiatives while experiencing the thrill and satisfaction of completing a marathon. Participants take pride in knowing that their efforts go beyond personal achievement, as their involvement directly aids those in need. Organized with meticulous planning, the marathon includes well marked routes, hydration stations, and medical assistance to ensure a smooth and safe experience for all runners. Over the years, this initiative has gained widespread support, strengthening the values of empathy and community service within RVCE and beyond.","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":10,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"3-4","signatureOfCounsellor":""},{"id":"c3fHC8YaG-T0mkGfJyoWZ","name":"Female Foeticide Awareness Walkathon","slNo":3,"place":"RVCE CAMPUS","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/0ae856b3-0344-4daf-997f-b56088c398ea/o8taE8rkvC6QSGjIFdS0h.png"],"endDate":"2025-05-11","duration":1,"outcomes":"Through participation in the Female Foeticide Awareness Walkathon, I gained a comprehensive understanding of the social, ethical, and legal implications associated with female foeticide and its far-reaching consequences on society. The activity helped me recognize how deeply rooted gender bias and discrimination can begin even before birth, and how such practices disturb social balance and hinder societal progress. It reinforced the importance of gender equality, respect for human rights, and the urgent need to safeguard the dignity and life of the girl child.\\n\\nThe walkathon also highlighted the power of collective action and community participation in addressing sensitive social issues. By engaging with a large and diverse group of participants, I learned how awareness initiatives can effectively influence public mindset, encourage dialogue, and inspire behavioral change. Carrying placards and slogans strengthened my ability to communicate social messages and advocate for justice and equality.","semester":"5","startDate":"2025-05-11","hoursSpent":4,"description":"On the occasion of Mother’s Day, 11th May 2025, the Rotaract Club of RV College of Engineering (RVCE) successfully organized a Female Foeticide Awareness Walkathon to highlight the serious social issue of female foeticide and to promote awareness about the importance and value of the girl child in society. The primary objective of this activity was to educate people and encourage collective responsibility in preventing gender-based discrimination even before birth.\\n\\nThe walkathon commenced in the early morning hours from the RVCE campus and witnessed enthusiastic participation from over 350 individuals, including students, faculty members, and parents. Participants carried impactful placards and raised powerful slogans advocating gender equality and the right to life for every girl child. The atmosphere throughout the event reflected unity, awareness, and a strong commitment toward social change.\\n\\nThe activity served as an effective platform to sensitize participants and the public about the consequences of female foeticide and the need for ethical and moral responsibility in society. Through this walkathon, the Rotaract Club of RVCE successfully conveyed the message of respect, equality, and dignity for women and girl children.\\n\\nThe event concluded with a sense of accomplishment and gratitude, and the organizing team expressed sincere appreciation to all participants for their active involvement and support in making the walkathon impactful and meaningful.","aicteMapping":"Setting of the information imparting club for women leading to contributing in social and economic issues","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/0ae856b3-0344-4daf-997f-b56088c398ea/w7cD_SJCLZyhmR5kKEMYx.jpg","certificateAttached":true,"detailedReportPageNo":"5-6","signatureOfCounsellor":""},{"id":"E0lPYI4PybFAI7nx_ay8Q","name":"Fast Trek 3.0","slNo":4,"place":"RVCE CAMPUS","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/0ae856b3-0344-4daf-997f-b56088c398ea/W5IcKgNNb7wJLr6a39zGT.png"],"endDate":"2025-01-12","duration":1,"outcomes":"Participation in Fast Trek 3.0 significantly enhanced my awareness of environmental responsibility and the importance of preserving cleanliness in natural spaces. Through active involvement in the cleanliness drive, I gained a practical understanding of how small, collective efforts can create a meaningful impact on environmental conservation. The experience made me more conscious of eco-friendly practices and responsible tourism, reinforcing the idea that protecting nature is a shared responsibility. Engaging directly in cleaning the trekking trails helped me appreciate the need for sustained efforts to maintain ecological balance and protect natural landscapes for future generations.\\nIn addition to environmental learning, the trek contributed greatly to my personal growth by improving my physical endurance, teamwork, and leadership skills. Navigating challenging terrain alongside fellow participants required cooperation, encouragement, and mutual support, which strengthened peer bonding and fostered a strong sense of unity. The adventure-based nature of the event made the learning experience more impactful and memorable. Overall, Fast Trek 3.0 deepened my appreciation for nature, promoted camaraderie, and reinforced the value of combining adventure with purposeful community service for holistic development.","semester":"5","startDate":"2025-01-12","hoursSpent":9,"description":"Fast Trek 3.0, the flagship event of the Rotaract Club of RV College of Engineering (RVCE), was successfully conducted on 12th January 2025 at the scenic Narayangiri Hills. The event witnessed enthusiastic participation from over 500 students, making it one of the largest and most impactful initiatives organized by the club. Designed as a perfect blend of adventure and social responsibility, Fast Trek 3.0 combined an early-morning trekking experience with a meaningful cleanliness drive.\\n\\nParticipants embarked on a challenging trek through the rugged trails of Narayangiri Hills, enjoying the natural beauty while actively contributing to environmental conservation. During the trek, students engaged in cleaning activities by collecting litter from the trails and surrounding areas, thereby promoting awareness about eco-friendly practices and responsible tourism. The event emphasized the importance of preserving natural ecosystems while encouraging students to take accountability for their environment.\\n\\nIn addition to its environmental focus, Fast Trek 3.0 fostered strong teamwork and camaraderie among participants. Mutual encouragement, shared challenges, and collective efforts strengthened interpersonal bonds and created a memorable experience. The event concluded successfully with participants feeling accomplished, energized, and inspired, setting a benchmark for future Rotaract initiatives.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":10,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"7-8","signatureOfCounsellor":""},{"id":"3MMldmZ2lu2D5V8ww9aU1","name":"FIst Full 2025","slNo":5,"place":"RVCE CAMPUS","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/0ae856b3-0344-4daf-997f-b56088c398ea/G9lxepna2bfogRW1C0Y4F.png"],"endDate":"2025-11-22","duration":6,"outcomes":"Through participation in FISTFUL, I gained a deeper understanding of the issue of food insecurity and the crucial role that nutritional support plays in improving public health and overall well-being. The activity highlighted the power of collective action by demonstrating how small, consistent individual contributions can come together to create a significant and meaningful societal impact. It helped me recognize the importance of addressing basic human needs such as food as a foundation for health, dignity, and social stability.The initiative also strengthened my sense of social responsibility and empathy toward underprivileged communities, motivating me to actively engage in community service. Working alongside fellow students enhanced my teamwork, coordination, and leadership skills, as effective organization and cooperation were essential for the success of the initiative.","semester":"6","startDate":"2025-11-17","hoursSpent":0,"description":"FISTFUL was a standalone community service initiative organized by the Rotaract Club of R.V. College of Engineering (RVCE) with the support of Rotary Bangalore Spandana, conducted from 17th to 22nd November 2025 at the Civil Engineering Department. The primary objective of the initiative was to combat food insecurity and address basic nutritional needs through collective student participation. By encouraging each student to contribute either 5 kg of rice or 2 kg of dal, the project emphasized how small, individual acts of generosity can come together to create a meaningful and large-scale social impact.\\n\\nThe initiative witnessed enthusiastic participation from 2,146 students, resulting in the successful collection of 4,370 kg of rice and 2,516 kg of dal. These essential food grains were systematically distributed to a wide range of beneficiary institutions, including hospitals, hostels, elderly care homes, schools, and nearby anganwadis. The distribution ensured that the collected resources reached vulnerable sections of society such as children, the elderly, and patients, thereby supporting daily meal programs and contributing to improved health and well-being.\\n\\nBeyond the material contribution, FISTFUL served as a powerful platform for nurturing values of empathy, compassion, and social responsibility among students. The initiative helped create awareness about food scarcity and the importance of community-driven solutions to social challenges. It strengthened the spirit of volunteerism and reinforced the role of students as responsible citizens committed to sustainable community service. Overall, the project demonstrated how organized collective action can effectively address societal needs and create a lasting positive impact.","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":10,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"9-10","signatureOfCounsellor":""},{"id":"seFg7nInk9PzzLDgC2Ma4","name":"Project Pustak 2025","slNo":6,"place":"RVCE CAMPUS","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/0ae856b3-0344-4daf-997f-b56088c398ea/DiZzuG1mNq1XHG0A25Txz.jpg"],"endDate":"2025-10-14","duration":1,"outcomes":"Through participation in Project Pustak 2025, I gained a deeper understanding of the importance of educational support in empowering underprivileged children and shaping their future. The activity helped me realize how even a single contribution, when combined with community-driven initiatives, can collectively create a large and meaningful impact. It highlighted the role of education in promoting equality and providing children with the opportunity to learn, grow, and aspire for a better future.\\n\\nThe experience also strengthened my sense of empathy and social responsibility, reinforcing my commitment toward inclusive education. It encouraged service-oriented thinking and made me more aware of the challenges faced by students from marginalized backgrounds.","semester":"6","startDate":"2025-10-14","hoursSpent":0,"description":"Project Pustak 2025 was a community service initiative organized by the Rotaract Club of RV College of Engineering (RVCE) in association with the Pranav Foundation, with the objective of supporting the education of underprivileged children. The initiative focused on addressing educational inequality by ensuring that students from government schools had access to essential stationery materials required for effective learning. By targeting basic educational needs, the project emphasized the role of education as a powerful tool for social empowerment and long-term development.\\n\\nAs part of this initiative, students actively contributed toward sponsoring stationery kits for government school children. Through my participation, I contributed to the donation that enabled a student to receive a complete stationery kit, thereby supporting uninterrupted learning and academic participation. This hands-on involvement highlighted how individual contributions, when combined, can make a substantial difference in the lives of children who lack access to basic educational resources.\\n\\nThe project successfully reached over 5,500 underprivileged children, reinforcing the values of education, equal opportunity, and social responsibility. Participation in Project Pustak 2025 strengthened my awareness of the challenges faced by marginalized students and the importance of community-driven initiatives in bridging educational gaps","aicteMapping":"Helping local schools to achieve good result and enhance their enrolment in Higher technical/vocational education","pointsEarned":10,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"11","signatureOfCounsellor":""},{"id":"2W0DB6vG3GFIm50v-AVxS","name":"Buy a Shirt,Plant a Tree","slNo":7,"place":"RVCE CAMPUS","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/0ae856b3-0344-4daf-997f-b56088c398ea/7J9_ecMe3fD5k3LEqTMFR.png"],"endDate":"2025-07-07","duration":1,"outcomes":"Participation in the “Buy a T-Shirt, Plant a Tree” initiative enhanced my understanding of the importance of environmental conservation and sustainable living. The activity reinforced the idea that environmental protection begins with individual responsibility and consistent action. It encouraged me to actively participate in green initiatives and adopt eco-friendly practices in daily life. The experience also helped me appreciate the impact of tree plantation in improving air quality, conserving biodiversity, and combating climate change. Overall, the activity strengthened my sense of civic duty and motivated me to contribute toward building a greener and more sustainable future.","semester":"6","startDate":"2025-07-07","hoursSpent":0,"description":"The “Buy a T-Shirt, Plant a Tree” initiative was a community-oriented environmental awareness program organized by the Kannada Sangha of RV College of Engineering. The primary objective of the event was to encourage sustainable practices and instill a sense of environmental responsibility among students through active participation. As part of the initiative, students who purchased a T-shirt were provided with a tree sapling along with basic guidelines on plantation and maintenance. The distribution of T-shirts and saplings was carried out within the RVCE campus, ensuring easy access and wide participation.\\n\\nThe event emphasized the idea that individual actions, when collectively undertaken, can significantly contribute to environmental conservation. By linking a simple purchase with an environmental action, the initiative successfully motivated students to take personal responsibility for planting and nurturing trees. This approach not only raised awareness about climate change, deforestation, and ecological balance but also encouraged long-term commitment toward sustainability.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":15,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"12","signatureOfCounsellor":""},{"id":"DJxzMegvQp0N9_WzGJwaF","name":"Blood Donation Camp","slNo":8,"place":"RVCE CAMPUS","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/0ae856b3-0344-4daf-997f-b56088c398ea/gs_QbHdJrVLxwVlnoJbQt.jpg"],"endDate":"2025-10-30","duration":1,"outcomes":"Through participation in the blood donation activity, I gained a deeper understanding of the critical importance of voluntary blood donation in saving lives and strengthening public health infrastructure. The experience helped me overcome initial hesitation and significantly boosted my confidence in contributing to medical and humanitarian causes. It made me more aware of how timely availability of blood can make a life-saving difference for accident victims, surgical patients, and individuals suffering from chronic illnesses.\\n\\nI also developed a stronger sense of empathy and social responsibility toward patients and their families who depend on regular blood donations. The activity increased my awareness about health standards, blood group compatibility, donor eligibility, and the importance of organizing regular blood donation drives to maintain adequate blood reserves.","semester":"7","startDate":"2025-10-30","hoursSpent":0,"description":"The Blood Donation activity was a humanitarian initiative carried out in association with the Indian Red Cross Society, Karnataka State Branch, aimed at supporting healthcare services and saving lives through voluntary blood donation. As part of this activity, I voluntarily donated blood, contributing directly to emergency medical care and treatment for patients in need. Blood donation plays a critical role in supporting hospitals, accident victims, patients undergoing surgeries, and individuals suffering from chronic illnesses.\\n\\nThis activity emphasized the importance of social responsibility, compassion, and civic duty. By participating, I became part of a larger effort to strengthen the healthcare system and ensure the availability of safe blood for critical situations. The initiative reflected the principle that a single act of kindness can have a life-saving impact and highlighted the role of youth participation in addressing public health challenges.","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":10,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"13","signatureOfCounsellor":""},{"id":"RyyVj_Clt0Q-YbhWHQHFt","name":"Blood Donation Camp","slNo":9,"place":"RVCE CAMPUS","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/0ae856b3-0344-4daf-997f-b56088c398ea/v4WdPhM3pwLLtqI7AZcG4.jpeg"],"endDate":"2025-03-20","duration":1,"outcomes":"Through participation in the blood donation activity, I gained a deeper understanding of the critical importance of voluntary blood donation in saving lives and strengthening public health infrastructure. The experience helped me overcome initial hesitation and significantly boosted my confidence in contributing to medical and humanitarian causes. It made me more aware of how timely availability of blood can make a life-saving difference for accident victims, surgical patients, and individuals suffering from chronic illnesses.\\n\\nI also developed a stronger sense of empathy and social responsibility toward patients and their families who depend on regular blood donations. The activity increased my awareness about health standards, blood group compatibility, donor eligibility, and the importance of organizing regular blood donation drives to maintain adequate blood reserves.","semester":"6","startDate":"2025-03-20","hoursSpent":0,"description":"The Voluntary Blood Donation activity was a humanitarian initiative conducted in association with the Lions Blood Centre, a unit of the Bangalore Lions Service Trust (BLST), at RV College of Engineering on 20th March 2025. The primary objective of this activity was to support healthcare services by ensuring the availability of safe and adequate blood for patients in need. By voluntarily donating blood, participants directly contributed to saving lives and strengthening the medical support system for hospitals and emergency care units.\\n\\nBlood donation is a critical component of public health, as it plays a vital role in treating accident victims, patients undergoing surgeries, individuals with chronic illnesses, and those requiring regular transfusions. This initiative emphasized the importance of selfless service, social responsibility, and compassion toward humanity. The activity also encouraged awareness about the importance of regular voluntary blood donation and its impact on community health and well-being.","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":15,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"14","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-30 04:43:58.160526+00', '2026-01-30 14:40:46.533326+00'), ('0911ddcd-e131-4de9-aaf3-95a9f643a473', '67509d1f-c31f-4f47-9240-71833c50a415', '{"student":{"usn":"1RV22CV057","name":"Mohammed Haris","period":"2022-2026","department":"Civil Engineering","totalPoints":0},"activities":[{"id":"4XSca9kq9QzoN8mxWh8eq","name":"FISTFULL","slNo":1,"place":"","photos":[],"endDate":"2026-01-08","duration":2,"outcomes":"","semester":"7","startDate":"2026-01-07","hoursSpent":1,"description":"","aicteMapping":"Food preservation/packaging","pointsEarned":10,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-29 10:32:20.107846+00', '2026-01-29 10:34:01.365473+00'), ('09db1c25-0199-449c-be8c-53a7a12b2444', '2e2da893-f12b-4c81-af84-5ff2bf21fdf1', '{"student":{"usn":"1RV22CY051","name":"SARTHAK GUPTA","period":"2022-2026","department":"Computer Science & Engineering - Cybersecurity","totalPoints":0},"activities":[{"id":"O-E0U-X_VKel8pFN3NpuR","name":"Campus Cleanup - II","slNo":1,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/5n5oqYrlLtKxRuUJTgaPW.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/1vyLzyeIlEWq_J00ZZRgp.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/OJgpMGL85RL0GJz5c99px.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/n7u7__ANMzxtBnerAFTxW.jpeg"],"endDate":"2024-01-27","duration":1,"outcomes":"The campus cleanup drive resulted in a visibly cleaner and more organized environment at RVCE, improving overall campus aesthetics and hygiene. Participants developed a stronger sense of environmental responsibility and understood the importance of cleanliness in daily life. The activity also fostered community spirit, teamwork, and leadership among students, while inspiring them to adopt eco-friendly habits and contribute actively to a sustainable campus culture.","semester":"3","startDate":"2024-01-27","hoursSpent":6,"description":"A campus cleanup activity was organized by NSS RVCE at the RVCE Campus with the aim of promoting environmental awareness and maintaining a clean, healthy learning space. Students and volunteers actively participated in cleaning roads, gardens, open areas, and common spaces within the campus. The activity included collecting litter, segregating waste, and spreading awareness about proper waste disposal and sustainable practices. The initiative encouraged teamwork, responsibility, and a sense of ownership toward preserving the beauty and hygiene of the campus. ","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/Pfi3H8umPrmaydRDscRHq.jpeg","certificateAttached":true,"detailedReportPageNo":"1","signatureOfCounsellor":""},{"id":"zljDNpMi2MNvLXu2BQBs_","name":" HACK4SOC 2.0","slNo":2,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/_c-sLGlzSztPIWibZRixp.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/9DY66HErwxm_QXFP11Ux7.jpeg"],"endDate":"2024-02-04","duration":2,"outcomes":"The 24-hour hackathon successfully enhanced participants’ technical expertise and practical understanding of Generative AI, Fintech, and Blockchain through hands-on problem solving. Strengthened the teamwork, critical thinking, and innovation skills while working under time constraints. The event encouraged cross-domain learning and collaboration, leading to the development of impactful, real-world solutions. Recognition of the top three teams motivated participants to strive for excellence and boosted their confidence, while the hackathon overall cultivated an innovative mindset and a strong interest in building technology-driven solutions for societal benefit.","semester":"3","startDate":"2024-02-03","hoursSpent":24,"description":"This 24-hour hackathon focused on leveraging technology for societal benefit, encompassing three key verticals: Generative Al, Fintech, and Blockchain. Throughout the hackathon, students showcased their creativity and problem-solving skills, developing innovative solutions. The top three teams emerged victorious, each presenting innovative ideas. This flagship event not only provided a platform for learning and collaboration but also fostered a culture of innovation among the participants","aicteMapping":"Promotion of appropriate technologies","pointsEarned":12,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/dPQ8_aYP6iPKBG2i6CzO1.png","certificateAttached":true,"detailedReportPageNo":"2","signatureOfCounsellor":""},{"id":"gTx9wSrnN2W0roWFwOaXZ","name":"EduAIthon","slNo":3,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/tc0KLr7eQod1dFTICDN5D.jpeg"],"endDate":"2025-05-18","duration":3,"outcomes":"The successful completion of EduAIthon highlighted the dedication and collaborative efforts of the student organizers and volunteers. The event provided a platform for participants from various colleges to ideate and build impactful prototypes addressing educational challenges using AI. Through effective planning, coordination, and round-the-clock management, the organizing team ensured seamless execution and a productive experience for all attendees. EduAIthon promoted innovation, interdisciplinary learning, and a strong culture of entrepreneurship and social impact. The post-event wrap-up on 19th May further ensured proper documentation, feedback collection, and closure activities, making the hackathon a meaningful and well-organized initiative","semester":"6","startDate":"2025-05-16","hoursSpent":48,"description":"EduAIthon was a 48-hour intercollegiate hackathon organized by SPARK – The IUCEE-RVCE Student Chapter, conducted from 16th to 18th May 2025. The event aimed to encourage students to develop innovative AI-driven solutions in the field of education, fostering creativity, teamwork, and technical problem-solving. The organizing team actively contributed during the preparation phase from 8th to 15th May through overnight planning, logistics arrangements, technical setup, participant coordination, and resource management. Volunteers also ensured smooth operations during the event days through continuous support, hospitality, media handling, and overall event execution.","aicteMapping":"Promotion of appropriate technologies","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/VTEtWNfIBSOEHOUBWh-vi.jpeg","certificateAttached":true,"detailedReportPageNo":"3","signatureOfCounsellor":""},{"id":"i8RRdllZ0Ww64oDdLo0oz","name":"EY Catalyst Program - Codeathon","slNo":4,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/VXfAx-cpCL5xCeT0OXN7b.jpeg"],"endDate":"2025-02-13","duration":1,"outcomes":"The hackathon successfully provided students with hands-on exposure to industry-oriented problem statements and strengthened their technical and collaborative skills. Teams presented functional solutions which were evaluated by EY professionals and faculty members based on feasibility, creativity, scalability, and user experience. The event fostered a competitive learning environment and encouraged innovation through practical application of concepts. Top performers were offered opportunities to advance in EY’s recruitment process, making the hackathon not only a valuable learning experience but also a direct gateway to career opportunities and industry engagement.","semester":"5","startDate":"2025-02-13","hoursSpent":8,"description":"The Coding Club of RV College of Engineering (RVCE), in collaboration with Ernst & Young (EY), organized an 8-hour hackathon designed as a strategic talent-hunt event. This hackathon served as a preliminary technical assessment round to shortlist candidates for EY’s recruitment process. Participants were challenged to develop innovative software solutions aligned with real-world business requirements relevant to EY’s operational domains such as finance, data analytics, and automation. Students worked in teams under strict time constraints, simulating a professional work environment that tested their coding proficiency, teamwork, and problem-solving abilities","aicteMapping":"Promotion of appropriate technologies","pointsEarned":8,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/6X1i5vmzMfGNgokJjYVbQ.jpeg","certificateAttached":true,"detailedReportPageNo":"4","signatureOfCounsellor":""},{"id":"bXIdqsSdTJeZ3yrlB2OIj","name":"GenAI Hackathon","slNo":5,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/M2DeiDKGBHtGI9lslhtqa.jpeg"],"endDate":"2024-11-29","duration":1,"outcomes":"The GenAI Hackathon concluded successfully with enthusiastic participation from students who demonstrated strong technical skills and innovative thinking. As volunteers, our coordinated efforts ensured seamless event flow, enabling participants to focus on problem-solving and teamwork. The hackathon promoted practical exposure to emerging AI technologies and encouraged students to develop impactful solutions within a limited timeframe. The event strengthened the culture of innovation and collaborative learning within the campus community. Overall, volunteering for this initiative was a valuable experience, contributing to the success of a highly engaging technical event and motivating students to participate in similar productive endeavors.","semester":"5","startDate":"2024-11-29","hoursSpent":12,"description":"As a volunteer for the GenAI Hackathon, powered by EDOCK and conducted on 29th November 2024 at the DTL Huddle, I actively contributed to the successful organization and execution of the event. The hackathon provided students with an opportunity to explore and apply cutting-edge advancements in Generative AI, including content generation, human-like interaction simulation, and solving complex real-world problems. My role as a volunteer involved supporting participant coordination, managing event logistics, assisting with technical arrangements, and ensuring smooth communication throughout the sessions. The event fostered an engaging environment of creativity, collaboration, and innovation","aicteMapping":"Promotion of appropriate technologies","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/MV_qUkqTXIXPImpKTfxhd.jpeg","certificateAttached":true,"detailedReportPageNo":"5","signatureOfCounsellor":""},{"id":"fMVPyjf72j278MaqY2q_V","name":"Mera Phale Vote Desh  Keliye ","slNo":6,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/JdTeKtDthPyI1eFTjehQQ.png"],"endDate":"2023-03-06","duration":1,"outcomes":"The initiative successfully instilled a sense of civic duty and national responsibility among participants, especially first-time voters. Students gained a clearer understanding of the voting process and the significance of making informed electoral choices. The program helped build confidence and enthusiasm to participate in elections, fostering a long-term commitment to democratic values. Overall, the initiative strengthened awareness, patriotism, and active citizenship among the youth.","semester":"3","startDate":"2023-03-06","hoursSpent":2,"description":"Participation in the Government of India’s initiative “Mera Pehla Vote, Desh Ke Liye” aimed to create awareness among young citizens about the importance of voting in a democratic nation. The program encouraged first-time voters to understand their rights and responsibilities, the electoral process, and the role of informed voting in nation-building. Through awareness sessions, discussions, and pledge activities, participants were motivated to actively engage in the democratic process and contribute responsibly to the future of the country.","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":4,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/86SZs6IlVF75a98aqPl6z.png","certificateAttached":true,"detailedReportPageNo":"6","signatureOfCounsellor":""},{"id":"6fa360SOlGAhS7Ej-hJ30","name":"Skill Lab","slNo":7,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/vxlVBjc5tqxFTM9BOMpt1.png"],"endDate":"2025-04-26","duration":371,"outcomes":"The activity improved the students’ understanding of cybersecurity concepts and enhanced their awareness of safe online behavior. They gained practical knowledge on identifying potential cyber threats and adopting preventive measures in their daily digital interactions. The session also boosted their confidence in using technology responsibly, while fostering curiosity and interest in cybersecurity as a potential area of learning. Additionally, the activity helped develop the instructor’s communication, leadership, and mentoring skills.","semester":"6","startDate":"2024-04-21","hoursSpent":8,"description":"The Skill Lab activity was conducted with the objective of introducing students to the fundamentals of cybersecurity. The session focused on creating awareness about online safety, common cyber threats, and best practices for protecting personal and digital information. Through interactive explanations, real-life examples, and basic demonstrations, the students were guided on topics such as strong passwords, phishing attacks, safe browsing, and responsible use of digital platforms.","aicteMapping":"Promotion of appropriate technologies","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/NYH0u8xggL-VZgDnkBF5o.png","certificateAttached":true,"detailedReportPageNo":"7","signatureOfCounsellor":""},{"id":"rsjbGZzpmVsRACO3lBaqX","name":"Design-A-Thon","slNo":8,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/S_3Uy2LKoUNl8rYfrpkTG.png"],"endDate":"2025-04-25","duration":8,"outcomes":"The Design-A-Thon concluded successfully, providing participants with a meaningful and impactful learning experience. The dedicated efforts of the volunteers ensured seamless coordination throughout both phases of the event, contributing significantly to its overall success. Participants benefited from hands-on exposure to real-world design and technical challenges, strengthening their problem-solving and collaborative skills. The Honeywell team highly appreciated the enthusiasm and outstanding performance of the student volunteers. Overall, the event fostered strong industry-academia engagement, promoted experiential learning, and highlighted the importance of volunteer contribution in organizing large-scale technical initiatives.","semester":"5","startDate":"2025-04-18","hoursSpent":12,"description":"The Accelerate Technical Club, Department of Computer Science and Engineering, successfully organized a Design-A-Thon in collaboration with Honeywell India Pvt. Ltd., conducted in two phases from 18th to 25th April 2025. The event was designed to enhance students’ technical and practical knowledge through an industry-oriented problem-solving platform. Volunteers from the club played a crucial role in planning, coordinating, and ensuring the smooth execution of the Design-A-Thon. Their responsibilities included managing logistics, assisting participants, supporting technical arrangements, and facilitating communication between organizers and industry representatives.","aicteMapping":"Promotion of appropriate technologies","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/nS35QIqt85iFYjEcIb8rx.png","certificateAttached":true,"detailedReportPageNo":"8","signatureOfCounsellor":""},{"id":"LNpYLBrIrsxQSPam94jb-","name":" SDG PHOTO COMPETITION","slNo":9,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/oisjVQYfSUxZlxed30p8V.png"],"endDate":"2026-01-28","duration":906,"outcomes":"The event successfully increased awareness and understanding of sustainable development issues among students while fostering creativity and social responsibility. A structured evaluation conducted by SPARK prefects and RVCE faculty ensured fair and comprehensive assessment of submissions. Outstanding entries were recognized during SDG Honour Day on 18th December 2024, with prizes awarded from a 3500 prize pool and certificates issued to all participants. The event strengthened inter-chapter collaboration, encouraged meaningful engagement with societal challenges, and motivated students to reflect on environmental and social concerns, making the initiative both impactful and educational","semester":"2","startDate":"2023-08-07","hoursSpent":2,"description":"The SDG Photography Event titled “Through the Eyes of (You)th” was conducted from 11th November to 18th November 2024 with the aim of promoting awareness of the United Nations Sustainable Development Goals through visual storytelling. Open to students from RVCE and IUCEE student chapters, the event received an overwhelming response with approximately 550 registrations. Participants showcased creativity by capturing social, environmental, and sustainability-focused themes through photography. The event encouraged inclusivity, collaboration, and critical thinking, providing a platform for students to express perspectives on global and local issues while enhancing their artistic and communication skills.","aicteMapping":"","pointsEarned":4,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/noxSvQSw8DSQEhc00feT_.jpeg","certificateAttached":true,"detailedReportPageNo":"9","signatureOfCounsellor":""},{"id":"EKk-PO3Bv5bzmRjljVKF3","name":"ENVIRONMENTAL DAY QUIZ","slNo":10,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/UTnREw-CY0cKZDmM1_0T7.png"],"endDate":"2023-06-05","duration":1,"outcomes":"The quiz enhanced participants’ understanding of key environmental concepts and increased awareness of the importance of protecting natural resources. It motivated students to think critically about environmental challenges and their role in addressing them. The activity also fostered enthusiasm for sustainable practices, teamwork, and healthy competition, contributing to a stronger sense of environmental responsibility among participants.","semester":"2","startDate":"2023-06-05","hoursSpent":3,"description":"The Environment Day Quiz was organized to raise awareness about environmental issues and promote knowledge related to sustainability, conservation, and eco-friendly practices. The quiz engaged participants through thought-provoking questions on topics such as climate change, biodiversity, pollution, and environmental protection initiatives. The activity encouraged active participation while making learning about the environment interactive and enjoyable.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":4,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/wwbJDkNMpTuy-cqYan_C_.png","certificateAttached":true,"detailedReportPageNo":"10","signatureOfCounsellor":""},{"id":"tB4FbrdysgmGplKKexoCF","name":"INFOSYS VISIT","slNo":11,"place":"Infosys Campus, Mysuru","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/i8XRjU1o07vrNMHGhE7Q5.jpeg"],"endDate":"2023-08-31","duration":1,"outcomes":"The industrial visit was successfully conducted and served as a valuable bridge between academic learning and real-world industry expectations. Students gained practical insights into IT operations, corporate standards, and emerging technologies through direct observation and interaction with professionals. The visit strengthened industry-academia collaboration and motivated students to align their academic knowledge with professional skill requirements. Overall, the event contributed significantly to students’ holistic development and preparedness for future careers in the technology domain.","semester":"2","startDate":"2023-08-31","hoursSpent":15,"description":"As a member of SPARK, the IUCEE-RVCE Student Chapter, I was part of the industrial visit to Infosys, Mysore campus, held on 31st August 2023. The visit was planned to provide students with meaningful exposure to the corporate environment of one of India’s leading IT companies. Theobjective was to help participants understand industry practices, workplace culture, and the latest technological advancements in the IT sector. The event involved organizing logistics, ensuring student participation, and facilitating interactions with professionals to create a structured and insightful learning experience beyond the classroom.","aicteMapping":"","pointsEarned":4,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/MEepzLBOiaGrWjRXZLhCP.png","certificateAttached":true,"detailedReportPageNo":"11","signatureOfCounsellor":""},{"id":"hmIWyRfh_6JBJ6gxEpEVF","name":"Web Development Bootcamp","slNo":12,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/EZ5Dndr9_bESL6H9k43pZ.png"],"endDate":"2025-04-28","duration":57,"outcomes":"The 8-week Web Development Bootcamp significantly strengthened participants’ understanding of web technologies, enabling first-year students to progress from basic concepts to developing complete end-to-end applications. Through hands-on practice, weekly assignments, and 1:1 mentorship, students gained practical problem-solving skills and confidence to tackle real-world development challenges. The program also fostered peer learning, collaboration, and a strong foundation in coding best practices, while empowering participants to continue building and contributing to technical projects independently.","semester":"6","startDate":"2025-03-03","hoursSpent":14,"description":"Coding Club of RVCE organized an 8-week Web Development Bootcamp led by second-year members for first-year students, taking participants from fundamentals to building end-to-end applications. The hybrid program combined structured teaching with hands-on practice. 1:1 mentorship, and weekly assignments to ensure participants were ready for real-world development challenges","aicteMapping":"Promotion of appropriate technologies","pointsEarned":12,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/m31hzQQJYwcx84tSM4iDD.png","certificateAttached":true,"detailedReportPageNo":"12","signatureOfCounsellor":""},{"id":"0YwT4tZPoUPbbM_DPPIVb","name":"Blood Donatiopn Camp","slNo":14,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/hGsix4aqjAP-cghYkCjU9.jpeg"],"endDate":"2024-06-28","duration":1,"outcomes":"The blood donation activity contributed directly to saving lives by supporting hospitals and patients requiring blood transfusions. I experienced a strong sense of social responsibility and empathy, understanding the impact of their contribution to the community. The initiative also helped dispel myths around blood donation, encouraged healthy individuals to donate in the future, and fostered a culture of compassion, service, and civic engagement.","semester":"4","startDate":"2024-06-28","hoursSpent":2,"description":"Participation in the blood donation activity aimed to support healthcare needs and promote the spirit of social responsibility among individuals. The initiative encouraged volunteers to donate blood to help patients in need and raise awareness about the importance of regular blood donation. The activity was conducted in a safe and organized manner, with medical professionals ensuring proper procedures and donor well-being throughout the process.","aicteMapping":"","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/yh8OuMsEhBRl4otmxGrzm.jpeg","certificateAttached":true,"detailedReportPageNo":"14","signatureOfCounsellor":""},{"id":"ZwLDlh7PMhUtCpf_6OmX6","name":"Blood Donatiopn Camp","slNo":15,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/56YaenstiUZYZKRF0qGO2.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/IlYL1AZjvMjQI9bkUW--m.jpeg"],"endDate":"2025-10-30","duration":1,"outcomes":"The blood donation activity contributed directly to saving lives by supporting hospitals and patients requiring blood transfusions. I experienced a strong sense of social responsibility and empathy, understanding the impact of their contribution to the community. The initiative also helped dispel myths around blood donation, encouraged healthy individuals to donate in the future, and fostered a culture of compassion, service, and civic engagement.","semester":"7","startDate":"2025-10-30","hoursSpent":2,"description":"Participation in the blood donation activity aimed to support healthcare needs and promote the spirit of social responsibility among individuals. The initiative encouraged volunteers to donate blood to help patients in need and raise awareness about the importance of regular blood donation. The activity was conducted in a safe and organized manner, with medical professionals ensuring proper procedures and donor well-being throughout the process.","aicteMapping":"","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2e2da893-f12b-4c81-af84-5ff2bf21fdf1/qz6-msfkd6qTKCDHEfnj4.jpeg","certificateAttached":true,"detailedReportPageNo":"14","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"Dr. Minal Moharir","designation":"Professor and Program Coordinator for the Cyber Security Program"},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-29 13:32:17.041946+00', '2026-01-29 15:28:50.353605+00'), ('0a8f3dbf-ab6b-4e90-9003-ce0a27e3d696', 'f070774b-af1c-4dea-9452-48879ccc22ce', '{"student":{"usn":"1RV22EC025","name":"Ashwija","period":"2022-2026","department":"Electronics & Communication Engineering","totalPoints":0},"activities":[{"id":"ClpxPXI4MJI6DDbmkNJ62","name":"Energy Literacy Training Program","slNo":1,"place":"Online","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/f070774b-af1c-4dea-9452-48879ccc22ce/1KQI5RIkbO6DNspTdNFE7.png"],"endDate":"2023-04-17","duration":9,"outcomes":"The program improved students’ awareness of energy usage, climate change, and sustainable practices. Participants developed a clearer understanding of the impact of individual and collective energy choices on the environment. The activity encouraged responsible energy behavior, critical thinking on sustainability challenges, and motivated students to act as energy-literate individuals within their communities.","semester":"2","startDate":"2023-04-09","hoursSpent":24,"description":"The Energy Literacy Training Program was organized by the Urja Energy Swaraj Club at RV College of Engineering as part of the Energy Swaraj Foundation initiative. The program aimed to educate students on energy awareness, sustainability, and climate action. It included a structured training comprising online modules that covered topics such as energy consumption, renewable energy, and individual responsibility toward sustainable living.","aicteMapping":"Reduction in energy consumption","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/f070774b-af1c-4dea-9452-48879ccc22ce/lOtyqCCUHfzROj5nfoZhY.png","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"6UVu4dwRaXxH3J3rUP1Gz","name":"Under The Peepal Tree (UTPT) 2023","slNo":2,"place":"RVCE Campus","photos":[],"endDate":"2023-07-16","duration":3,"outcomes":"Participation in the quiz enhanced the student’s awareness and understanding of Indian knowledge systems and cultural heritage. It strengthened analytical thinking, recall ability, and interdisciplinary learning. The activity promoted appreciation of indigenous knowledge while improving competitive skills and intellectual curiosity at a national level.","semester":"2","startDate":"2023-07-14","hoursSpent":3,"description":"The student participated in Indi-Genius: The India Quiz conducted under Under The Peepal Tree (UTPT) 2023, a national-level quiz fest held from 14th to 16th July 2023. The event focused on Indian knowledge systems, culture, history, and indigenous wisdom, encouraging participants to engage with India’s intellectual and cultural heritage through a competitive quiz format.","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":3,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/f070774b-af1c-4dea-9452-48879ccc22ce/k0ddA5knf9DcsUJpG40N1.png","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"HJWQflQJfRWQJ0Y0-5KOe","name":"BIOFUEL DAY ESSAY COMPETITION AND MODEL MAKING","slNo":3,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/f070774b-af1c-4dea-9452-48879ccc22ce/1vU7Xlh--v4bTJIrdHn59.png","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/f070774b-af1c-4dea-9452-48879ccc22ce/yqowxwJJmtjpMrhEMKjqd.png"],"endDate":"2023-08-08","duration":1,"outcomes":"The competition enhanced participants’ understanding of renewable energy sources, particularly biofuels and their role in sustainable development. It encouraged critical thinking, creativity, and practical application of theoretical concepts. Students also improved their research, presentation, and technical communication skills while gaining interdisciplinary exposure to energy and environmental engineering concepts.","semester":"2","startDate":"2023-08-08","hoursSpent":2.5,"description":"The International Biofuel Day Essay Writing and Model Making Competition was conducted by the Civil Engineering Department in CE-205 on 08 August 2023 from 2:00 PM to 4:30 PM. The activity aimed to create awareness about biofuels as a sustainable alternative to conventional fossil fuels. Participants presented their understanding through analytical essays and working or conceptual models highlighting biofuel production, applications, and environmental impact.","aicteMapping":"Reduction in energy consumption","pointsEarned":3,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"0yzQs2Nb62QHzkjaU20NW","name":"","slNo":4,"place":"Mangalore","photos":[],"endDate":"2023-05-07","duration":7,"outcomes":"The activity strengthened environmental awareness and instilled a sense of responsibility toward nature and sustainability. It encouraged eco-friendly behavior, long-term commitment to environmental conservation, and understanding of individual roles in combating climate change. The initiative also promoted values of stewardship, accountability, and sustainable lifestyle choices.","semester":"2","startDate":"2023-05-01","hoursSpent":7,"description":"The One Student One Tree 2023 initiative was conducted under the MeriLiFE program as a massive tree plantation drive promoted by AICTE. As part of this activity, the student took the Pro Planet Pledge, committing to plant a tree and actively participate in its care and nourishment, thereby contributing to environmental conservation and sustainable living practices.","aicteMapping":"Environmental Conservation","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/f070774b-af1c-4dea-9452-48879ccc22ce/TZ7tV9ESkzuQes63ZOZRb.png","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"fhvZwabpXCr-I-evHXO1N","name":"Tanuja screening ","slNo":5,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/f070774b-af1c-4dea-9452-48879ccc22ce/bh5qZJOx1FS3RNVrvXQYC.png","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/f070774b-af1c-4dea-9452-48879ccc22ce/pdc1tyLTp-9I5V5yyiOdv.png"],"endDate":"2023-07-14","duration":1,"outcomes":"The screening created awareness about educational inequalities and the socio-economic barriers faced by rural students. It encouraged empathy, social sensitivity, and appreciation for perseverance in adverse conditions. Participants gained insight into the importance of equal educational opportunities and the role of support systems in enabling academic success.","semester":"2","startDate":"2023-07-14","hoursSpent":3,"description":"The Tanuja movie screening was conducted as part of an awareness drive to highlight the challenges faced by students from rural backgrounds in accessing education. The film portrayed the journey of a rural girl who studies diligently for an examination and the obstacles she encounters while trying to reach the examination hall on time, emphasizing issues related to access, resilience, and determination.","aicteMapping":"Awareness Drive","pointsEarned":2,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"SdObaswtQoyeJ97tKdhun","name":"Project Pustak","slNo":6,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/f070774b-af1c-4dea-9452-48879ccc22ce/c6UvokTeyVLBWXKUaMr8a.png","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/f070774b-af1c-4dea-9452-48879ccc22ce/iZsU63VCZXWTsIonMM8j9.png"],"endDate":"2024-05-24","duration":1,"outcomes":"The project contributed to improving access to basic educational resources for underprivileged school students, thereby supporting their learning environment. It fostered social responsibility, teamwork, and community engagement among participants. Students gained practical experience in planning, fund collection, and execution of a social welfare initiative while developing awareness of educational inequality and grassroots-level social impact.","semester":"4","startDate":"2024-05-24","hoursSpent":1,"description":"Project Pustak was a social outreach initiative conducted on 24th May 2024 with the objective of supporting underprivileged students from rural areas by providing essential school supplies. Funds were collected through individual contributions, ranging from ₹100 to ₹350, and were utilized to procure educational materials such as textbooks, stationery items, backpacks, and other basic learning resources. The initiative was organized by the Rotaract Club of RVCE in collaboration with Pranav Foundation.","aicteMapping":"Helping local schools to achieve good result and enhance their enrolment in Higher technical/vocational education","pointsEarned":10,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-30 04:36:39.973596+00', '2026-02-02 06:38:46.817792+00'), ('0a992994-5c65-467d-aff4-68f51908c3b2', 'c6b73eb6-1927-401f-892e-66e8e11968f2', '{"student":{"usn":"","name":"","period":"2022-2026","department":"","totalPoints":0},"activities":[],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-29 15:19:07.01194+00', '2026-01-29 15:20:55.032397+00'), ('0de46070-9404-4078-bd80-fd8b4783c567', '19ba3b6a-4197-439a-b563-87157b160f82', '{"student":{"usn":"1RV22CD018","name":"E Lokeshvar","period":"2022-2026","department":"Computer Science & Engineering - Data Science","totalPoints":0},"activities":[{"id":"h9srnG_6Qk_Zdn_D_9l59","name":"Blood Donation","slNo":1,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/NDBy-F1FRzNUvZOen6bFM.jpg"],"endDate":"2023-06-06","duration":1,"outcomes":"A voluntary donation of a sizable quantity of blood to the Lion''s Blood Centre, reinforced the \\nimportance of medical aid and support for those in need. It offered us an opportunity to partake \\nin a selfless activity and provide someone with crucial help in a dire situation, driving home the \\nimportance of collective and charitable work.","semester":"2","startDate":"2023-06-06","hoursSpent":24,"description":"A team from the Lions Blood Centre, a unit of Bangalore Lions Service Trust (BLST), visited \\nthe RVCE Campus on 06/06/2023, to conduct a voluntary blood donation drive. A team of expert \\nnurses and medical professionals used sterile, safe, and professional equipment to extract blood \\nin a safe manner, after conducting preliminary checks to ensure the donor''s eligibility. Donors \\nwere also provided with sufficient post-donation precautionary instructions.","aicteMapping":"Promotion of appropriate technologies","pointsEarned":6,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/eKFoJEqzjb-UKRR_sE8Bs.jpg","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"64DoMMohe4tl-B7G8DId-","name":"Resonating Chords","slNo":2,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/P2yTV8WYZdqSKoZLcopiQ.png"],"endDate":"2023-06-08","duration":1,"outcomes":"The primary result is the cultivation of a deeply engaged community aligned through shared \\nintellectual inquiry and inspiration. Participants leave with a broadened perspective, equipped \\nwith cross-disciplinary insights that encourage further dialogue and collaboration. Additionally, \\nthe event produces a lasting digital archive of the presentations, ensuring that the ideas shared \\ncontinue to influence and resonate with a wider audience long after the conclusion of the talks.","semester":"2","startDate":"2023-06-08","hoursSpent":12,"description":"This TEDx event explores the power of ideas to amplify impact and foster connection across \\ndiverse disciplines. Under the theme \"Resonating Chords,\" the gathering brings together \\ndistinct voices to share perspectives that, while unique, collectively contribute to a harmonized \\nunderstanding of innovation and human experience. The session is designed to provoke deep \\nreflection, illustrating how singular concepts can vibrate outward to create significant, lasting \\nchange within the community","aicteMapping":"Promotion of appropriate technologies","pointsEarned":3,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/GhJVvku03X1DZ-lblRSCp.png","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"ypRQjs9k6FYCODRfsvla5","name":"Utsarga Marathon","slNo":3,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/QPnmroY7CDTIwXjHXvh2U.jpg"],"endDate":"2024-02-04","duration":1,"outcomes":" I gained improvement in physical stamina and endurance by participating in the marathon. The \\nactivity also helped me build discipline and motivation through early-morning participation and completing the run. Additionally, it increased my awareness of social contribution, since the \\nmarathon supported initiatives related to improving opportunities for children in need.","semester":"3","startDate":"2024-02-04","hoursSpent":40,"description":"The Utsarga Marathon 2024, organized by NSS RVCE, is a marathon event focused on \\npromoting health, fitness, and social responsibility. Scheduled to be held on February 4th, 2024, \\nfrom 6:00 AM to 10:30 AM at R V College of Engineering (RVCE), the event encourages \\nstudents and the public to participate in either a 5 km or 10 km run through donation-based \\nregistration. With the theme “Help a Child Change the World,” the marathon aims to create \\nawareness and support for education-related social causes, making it more than just a fitness \\nactivity and instead a meaningful initiative that connects physical well-being with community \\nimpact.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/oSGb5jq4K5vAXUQH_-phk.jpg","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"RYTYQxMzSEhDkY450_71a","name":"Data Remix - Clash of Companies","slNo":4,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/AWhklHKv6SBSrPsMXSELX.png"],"endDate":"2024-03-06","duration":1,"outcomes":"DATA Remix: Clash of Companies proved to be an exhilarating event, where data enthusiasts \\nand problem solvers come together to drive positive change through data-driven innovation. \\nWe had an opportunity to witness firsthand, the impact that data-driven insights and technical \\nanalytics could make in working towards a better, safer, and healthier tomorrow","semester":"3","startDate":"2024-03-06","hoursSpent":12,"description":"In this event, teams of 4-5 members embarked on a thrilling journey of data exploration and \\nproblem-solving. Each team represented a company and was provided with unique datasets to \\nanalyse. Utilizing these datasets, teams delved deep into their company''s performance, seeking \\ninsights and opportunities for improvement aligned with the SDGs.","aicteMapping":"Promotion of appropriate technologies","pointsEarned":3,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/KVoSHG5cy0XDdifBTJnbm.png","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"rCuEISLFRwSOVIhdCMYZW","name":"Project Pustakh","slNo":5,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/8Wl9_s2p3Rkcn_W7jdCPj.png"],"endDate":"2024-05-24","duration":1,"outcomes":"By participating in Project Pustak, I gained a strong sense of social responsibility and \\nsatisfaction from contributing towards the education of underprivileged rural students. I \\nunderstood the real impact that even small contributions can create when combined for a \\nmeaningful cause. This activity helped me develop empathy and awareness about the difficulties \\nfaced by students who lack basic school resources. I also gained exposure to community service \\ninitiatives and learned the importance of teamwork and collective effort in successfully carrying \\nout a donation-based project. Overall, the experience was rewarding as it allowed me to support \\na noble cause and contribute directly to creating a better learning environment for deserving \\nstudents.","semester":"4","startDate":"2024-05-24","hoursSpent":40,"description":"Project Pustak is a commendable and noble initiative aimed at providing essential school \\nsupplies to underprivileged students living in rural areas. Under this project, a contribution \\nwas collected from each donor, and the funds raised were used to procure and donate \\nmuch-needed educational materials. The collected amount was utilized to purchase resources \\nsuch as textbooks, stationery items, backpacks, and other important school supplies that help \\ncreate a better and more supportive learning environment for deserving students. The Rotaract \\nClub of RVCE, in collaboration with the Pranav Foundation, undertook the responsibility of \\nprocuring and distributing these essential supplies to ensure meaningful educational support for \\nthe beneficiaries.","aicteMapping":"To skill rural population","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/Yx9sFH7myUrk5-hOOKumU.png","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"yHyzDA6rXsg0ypOj7krCW","name":"Blood Donation ","slNo":6,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/awxwjA3j8tan0Tq3hLAWL.jpg"],"endDate":"2024-06-28","duration":1,"outcomes":"A voluntary donation of a sizable quantity of blood to the Lion''s Blood Centre, reinforced the \\nimportance of medical aid and support for those in need. It offered us an opportunity to partake \\nin a selfless activity and provide someone with crucial help in a dire situation, driving home the \\nimportance of collective and charitable work.","semester":"4","startDate":"2024-06-28","hoursSpent":40,"description":"A team from the Indira Gandhi Institute of Child Health, visited \\nthe RVCE Campus on 28/06/2024, to conduct a voluntary blood donation drive. A team of expert \\nnurses and medical professionals used sterile, safe, and professional equipment to extract blood \\nin a safe manner, after conducting preliminary checks to ensure the donor''s eligibility. Donors \\nwere also provided with sufficient post-donation precautionary instructions.","aicteMapping":"Promotion of appropriate technologies","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/0llOZvoxX_i-8d-OgGA4y.jpg","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"Czq2X69mQoCBfqsVOTo4n","name":"Inkspire","slNo":7,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/em81vZghkKkMwvJwG2hvu.png"],"endDate":"2024-10-28","duration":4,"outcomes":"The event witnessed active participation from 132 students and successfully enhanced their creative thinking, communication skills, and awareness of social issues. Participants gained confidence in expressing their perspectives and learned how storytelling can influence positive change in society. Selected entries were showcased through the club’s digital platforms, giving participants recognition and motivation. Overall, Inkspire fostered creativity, inclusivity, and social responsibility among students, making it a meaningful and impactful learning experience.","semester":"5","startDate":"2024-10-25","hoursSpent":8,"description":"Inkspire was a creative writing and storytelling initiative conducted from 25th to 28th October 2024 with the aim of encouraging students to use words as a tool for social change. The event invited participants to submit original works such as prose, poetry, articles, creative non-fiction, and flash fiction based on impactful themes including sustainability, health, equality, and education. Submissions were accepted in English, Hindi, and Kannada, ensuring inclusivity and diverse representation. The activity provided a structured platform for students to express their ideas creatively while engaging with socially relevant topics.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":2,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/8PqLdxSVes3gTK7Vx7Wnc.png","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"UmT0ndQRUP_Y9CwNs17yG","name":"Fist Full","slNo":8,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/77TPOnW0-cvxA1xmgabC3.jpg"],"endDate":"2024-11-29","duration":1,"outcomes":"The initiative received an overwhelming response from students, resulting in the collection of approximately 6,700 kg of rice and 800 kg of toor dal. These contributions were distributed to beneficiaries through Rotary Bangalore Spandana, significantly supporting food relief efforts. The activity successfully instilled a sense of social consciousness among participants and demonstrated how small individual contributions can create a large and meaningful impact on society.","semester":"5","startDate":"2024-11-29","hoursSpent":40,"description":"FISTFULL was a social welfare initiative organized by the Rotaract Club of RVCE in collaboration with Rotary Bangalore Spandana, conducted from 15th to 29th November 2024. The activity aimed to address food insecurity by encouraging students to contribute essential food grains by donating either 5 kg of rice or 2 kg of toor dal. The initiative focused on promoting empathy, social responsibility, and community participation among students while supporting the underprivileged through collective action.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/FnRNhAFwS8xynOWNSRfZy.png","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"f7ecSN3sewL2Zv90eYQDb","name":"Viksit Bharath Quiz","slNo":9,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/ooswGvDpzSC_KrdQbbuOC.png"],"endDate":"2024-12-01","duration":1,"outcomes":"Participation in the quiz enhanced the participant’s understanding of national development programs and government initiatives while strengthening general awareness and analytical thinking skills. The activity fostered a sense of civic engagement and national consciousness. Successful completion of the quiz demonstrated active participation in a government-led educational initiative and contributed to knowledge enrichment beyond the academic curriculum.","semester":"5","startDate":"2024-12-01","hoursSpent":8,"description":"The Viksit Bharat Quiz Challenge was an online national-level quiz initiative conducted through the MyGov platform under the Government of India. The activity aimed to increase awareness among participants about India’s development vision, governance initiatives, national policies, and the concept of Viksit Bharat. The quiz encouraged students to engage with topics related to India’s progress, civic responsibility, and future goals, promoting informed citizenship through an interactive learning format.","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":2,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/inyOTTOFgte2O_4KiB-k7.png","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"H2q2YZb9qB5TG4ZeBnmRY","name":"Through the Eyes of Youth","slNo":10,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/yPFaylKLLY2yVokgT7y3D.png"],"endDate":"2024-12-18","duration":1,"outcomes":"","semester":"5","startDate":"2024-12-18","hoursSpent":20,"description":"","aicteMapping":"Promotion of appropriate technologies","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/3oUi4ClPpMbmdDfLFdQ8P.png","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"dSbfkOKPgmfZ3VMf_NPJC","name":"Utsarga Marathon","slNo":11,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/EHSRREJaqteUgLrA2pucw.jpg"],"endDate":"2025-04-06","duration":1,"outcomes":"I gained improvement in physical stamina and endurance by participating in the marathon. The \\nactivity also helped me build discipline and motivation through early-morning participation and completing the run. Additionally, it increased my awareness of social contribution, since the \\nmarathon supported initiatives related to improving opportunities for children in need","semester":"6","startDate":"2025-04-06","hoursSpent":45,"description":"The Utsarga Marathon 2025, organized by NSS RVCE, is a marathon event focused on \\npromoting health, fitness, and social responsibility. Scheduled to be held on April 6th, 2025, \\nfrom 6:00 AM to 10:30 AM at R V College of Engineering (RVCE), the event encourages \\nstudents and the public to participate in either a 5 km or 10 km run through donation-based \\nregistration. With the theme “Help a Child Change the World,” the marathon aims to create \\nawareness and support for education-related social causes, making it more than just a fitness \\nactivity and instead a meaningful initiative that connects physical well-being with community \\nimpact.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/8rAfoBXjl9Gb4ogq9Anlj.jpg","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"xY9ca-jpQ3cJJKAKz2u2M","name":"Project Pustakh","slNo":12,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/11ZVll-pMmigxWec_tHEp.jpg"],"endDate":"2025-04-30","duration":8,"outcomes":"By participating in Project Pustak, I gained a strong sense of social responsibility and \\nsatisfaction from contributing towards the education of underprivileged rural students. I \\nunderstood the real impact that even small contributions can create when combined for a \\nmeaningful cause. This activity helped me develop empathy and awareness about the difficulties \\nfaced by students who lack basic school resources. I also gained exposure to community service \\ninitiatives and learned the importance of teamwork and collective effort in successfully carrying \\nout a donation-based project. Overall, the experience was rewarding as it allowed me to support \\na noble cause and contribute directly to creating a better learning environment for deserving \\nstudents.","semester":"6","startDate":"2025-04-23","hoursSpent":40,"description":"Project Pustak is a commendable and noble initiative aimed at providing essential school \\nsupplies to underprivileged students living in rural areas. Under this project, a contribution \\nwas collected from each donor, and the funds raised were used to procure and donate \\nmuch-needed educational materials. The collected amount was utilized to purchase resources \\nsuch as textbooks, stationery items, backpacks, and other important school supplies that help \\ncreate a better and more supportive learning environment for deserving students. The Rotaract \\nClub of RVCE, in collaboration with the Pranav Foundation, undertook the responsibility of \\nprocuring and distributing these essential supplies to ensure meaningful educational support for \\nthe beneficiaries.","aicteMapping":"To skill rural population","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/gBRk8dAFOGQrSzrehA6q8.png","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"hW8EpwxOBpfEX-18sVp0K","name":"Buy a T-Shirt, Plant a Tree","slNo":13,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/IRVpCDTdV27R1b8lk2SRV.jpg"],"endDate":"2025-07-07","duration":1,"outcomes":"The initiative saw active participation from students and successfully promoted environmental consciousness and sustainable practices on campus. Participants gained awareness about the importance of tree plantation and long-term ecological impact while directly contributing to a green initiative. The activity fostered a sense of social and environmental responsibility among students and reinforced the role of collective action in addressing environmental challenges.","semester":"6","startDate":"2025-07-07","hoursSpent":60,"description":"“Buy a T-shirt, Plant a Tree” was an environmental awareness and sustainability initiative organized by Kannada Sangha, RV College of Engineering. The activity encouraged students to contribute towards environmental conservation by purchasing a T-shirt, with the proceeds used to plant saplings. Each participant received a sapling along with the T-shirt, promoting awareness about afforestation, ecological balance, and individual responsibility towards protecting the environment.","aicteMapping":"Promotion of appropriate technologies","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/19ba3b6a-4197-439a-b563-87157b160f82/JtOt6JSjJ3lUTXGLYCCZB.png","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"Prof. Rajatha Bhat","designation":"Assistant Professor, Dept. of CSE, RVCE"},"evaluator1":{"name":"Evaluator 1","designation":""},"evaluator2":{"name":"Evaluator 2","designation":""}}}', '2026-01-30 17:37:25.969364+00', '2026-01-30 19:03:06.825248+00'), ('0fa89c8d-d143-4ee2-8573-06b595d05846', '6ce2d0a4-ba54-4662-bf5d-61ebcbdb7520', '{"student":{"usn":"","name":"","period":"2022-2026","department":"","totalPoints":0},"activities":[],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-30 16:39:23.502891+00', '2026-01-30 16:39:25.634379+00'), ('124dbe2f-4d14-41a7-9b78-6ed04bd85ad1', '74628168-f12b-47c9-9eb2-dfe8f03b91a8', '{"student":{"usn":"1RV22CS048","name":"Divyansh Agarwal","period":"2022-2026","department":"Computer Science & Engineering","totalPoints":0},"activities":[{"id":"cX9p1Ot1vC29T2u0XuEO0","name":"Energy Swaraj Foundation","slNo":1,"place":"Energy Swaraj Portal [Online]","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/74628168-f12b-47c9-9eb2-dfe8f03b91a8/3Ck2p9L_8nqDfY3VlWvkM.jpeg"],"endDate":"2023-10-18","duration":3,"outcomes":"Developed a strong conceptual foundation in sustainable energy systems and environmental\\nresponsibility.\\nAcquired the ability to evaluate energy usage patterns and propose efficiency improvements.\\nBuilt awareness to support informed decision-making toward clean and renewable energy\\nadoption.","semester":"2","startDate":"2023-10-16","hoursSpent":10,"description":"Completed a structured Energy Literacy Training covering energy generation, consumption,\\nand wastage.Studied carbon footprint analysis and the environmental impact of conventional\\nenergy sources.Learned strategies to minimize energy usage and adopt sustainable consumption\\npractices.Gained insights into alternative and renewable energy solutions, including\\nsolar energy.Understood pathways to achieve carbon neutrality and addressed common\\nmisconceptions about solar adoption.","aicteMapping":"Reduction in energy consumption","pointsEarned":10,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"1","signatureOfCounsellor":""},{"id":"zO5mIaEdd8jS14p_BndKe","name":"Through The Eyes Of Youth- SDG Photography Competition","slNo":2,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/74628168-f12b-47c9-9eb2-dfe8f03b91a8/DIN8378wSGcSNv7L4o8q9.jpeg"],"endDate":"2023-08-29","duration":1,"outcomes":"Through this event, I gained a deeper understanding of the Sustainable Development Goals and their relevance to everyday life. The activity enhanced my creative thinking, visual storytelling, and communication skills. It also helped me develop a broader perspective on social and environmental issues. Participating alongside students from different institutions fostered inclusivity, collaboration, and idea exchange.","semester":"2","startDate":"2023-08-29","hoursSpent":8,"description":"I participated in the SDG Photography Event titled “Through the Eyes of (You)th”, conducted from 11th to 18th November 2024. As a participant, I captured photographs highlighting themes related to the United Nations Sustainable Development Goals, focusing on social, environmental, and sustainability issues. The event provided an opportunity to visually narrate real-world challenges and positive actions through creative photography. It encouraged thoughtful observation and meaningful storytelling.","aicteMapping":"Through The Eyes Of Youth- SDG Photography Competition","pointsEarned":4,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"2","signatureOfCounsellor":""},{"id":"GdvlElwxVjmxTYDbio8MZ","name":"School Visit ","slNo":3,"place":"Local School","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/74628168-f12b-47c9-9eb2-dfe8f03b91a8/P5RmhZ3vVFAgwY_voNaec.jpeg"],"endDate":"2024-01-26","duration":9,"outcomes":"The volunteering activity had a deep and positive impact on the students as well as the volunteers. The children gained confidence in expressing themselves artistically, learned new skills in craft-making, and experienced a sense of achievement through their creations. The session also fostered teamwork, communication, and curiosity among the students. For the volunteers, the event strengthened their commitment to community service and highlighted the importance of nurturing creativity in young minds. Overall, the initiative successfully brought smiles, learning, and inspiration to the students, reinforcing the Sattva Club’s mission of making meaningful contributions to society.","semester":"3","startDate":"2024-01-18","hoursSpent":16,"description":"The Sattva Club organized a meaningful volunteering activity at a nearby government school, where volunteers spent the day engaging with young students through creative, hands-on learning. The session focused on teaching children how to make simple yet beautiful origami crafts and guiding them through fun painting activities. Volunteers worked closely with the students, helping them explore colors, shapes, and patterns while encouraging their imagination and artistic expression. The event created a lively, joyful atmosphere where children felt seen, supported, and inspired to learn through creativity.\\n","aicteMapping":"Helping local schools to achieve good result and enhance their enrolment in Higher technical/vocational education","pointsEarned":40,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"3","signatureOfCounsellor":""},{"id":"JRRt73FZ91awmarcyVfpn","name":"Enviromental and Climate change activity","slNo":4,"place":"Maiti Labs,Bangalore","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/74628168-f12b-47c9-9eb2-dfe8f03b91a8/W5aTxmuzt2aMqyCN3a08Z.jpeg"],"endDate":"2023-11-18","duration":110,"outcomes":"I learned the importance of environmental responsibility and how individual efforts contribute\\nto larger climate action goals. The internship helped me develop consistency, accountability, and\\na strong sense of social commitment. I also gained experience in teamwork, communication,\\nand working toward impact-driven objectives. Overall, it strengthened my awareness of\\nsustainability challenges and the role youth can play in addressing them.","semester":"3","startDate":"2023-08-01","hoursSpent":80,"description":"I completed an internship at Maiti Labs, a youth-led non-profit organization working toward\\nclimate action and sustainability. During the internship, I contributed to environmental\\nawareness initiatives, community-focused projects, and impact-driven activities. The role\\ninvolved consistent participation, coordination, and responsibility over more than 80 hours. This\\nexperience allowed me to actively engage in meaningful social work while supporting initiatives\\naimed at long-term environmental impact.","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":20,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"4","signatureOfCounsellor":""},{"id":"DGlIynxVZuz9d_W9SUIwq","name":"Swachh Bharat Abhiyan","slNo":5,"place":"JCI Hosur, Sipcot","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/74628168-f12b-47c9-9eb2-dfe8f03b91a8/m-VU7QutpaS8_vH7hdKZx.jpeg"],"endDate":"2023-04-20","duration":16,"outcomes":"I learned the importance of social responsibility and the impact that consistent community\\nservice can create. The experience strengthened my sense of discipline, teamwork, and time\\nmanagement while working toward a common social cause. It also deepened my understanding\\nof cleanliness, public health awareness, and the role individuals play in contributing to societal\\ndevelopment.","semester":"3","startDate":"2023-04-05","hoursSpent":80,"description":"I participated in a social service initiative organized by Junior Chamber International Hosur\\nSIPCOT, where I contributed 80 hours toward the Swachh Bharat Abhiyan. During this period,\\nI actively took part in cleanliness drives and community-focused activities aimed at improving\\npublic spaces. The initiative emphasized discipline, teamwork, and civic responsibility. My\\nefforts were formally recognized with a certificate of appreciation, acknowledging the time and\\ncommitment invested toward societal upliftment.","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":20,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"5","signatureOfCounsellor":""},{"id":"corzHguG_zEUh0zsh4rg1","name":"Science Projects with Special Children","slNo":6,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/74628168-f12b-47c9-9eb2-dfe8f03b91a8/uC4sVuh4hD-s1aNRBrGqV.jpeg"],"endDate":"2023-12-30","duration":1,"outcomes":"The activity helped improve concept clarity and engagement among the children through visual and hands-on learning. Students showed better interest and understanding of basic science topics. Teachers appreciated the inclusive and child-friendly approach used in the materials. Overall, the initiative contributed to a more accessible and enjoyable learning environment for special children.","semester":"3","startDate":"2023-12-30","hoursSpent":8,"description":"As part of the organizing committee, we planned and conducted a science education activity for special children studying in classes 1–5. We designed and created colorful, easy-to-understand charts covering basic science concepts to support visual learning. The activity focused on simplifying topics through pictures, symbols, and minimal text to suit different learning needs. The charts were explained interactively to encourage participation and curiosity.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":5,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"6","signatureOfCounsellor":""},{"id":"kbPAGrhWkV40DvgDyv5mc","name":"Utsarga Marathon - 2024","slNo":7,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/74628168-f12b-47c9-9eb2-dfe8f03b91a8/Terfa-rBvHLKWqcXe0wzk.jpeg"],"endDate":"2024-04-02","duration":1,"outcomes":"The Utsarga Marathon successfully fostered awareness about physical fitness and social\\nresponsibility among participants.\\nIt contributed directly to supporting educational opportunities for children in need through\\ncollective donations.\\nThe event strengthened community bonding by uniting students, faculty, and the public under\\na shared cause of compassion and change.","semester":"3","startDate":"2024-04-02","hoursSpent":5,"description":"Utsarga Marathon, a spirited initiative that brings together fitness, compassion, and social\\nresponsibility. Scheduled for February 4th, 2024, at R V College of Engineering, this marathon is\\nmore than just a run—it is a collective movement towards meaningful change. With the inspiring\\ntheme “Help a Child Change the World”, the event aims to promote health and well-being while\\ncontributing towards the education of underprivileged children. Participants can choose between\\n5 km and 10 km runs, making it accessible to all age groups and fitness levels. By taking part,\\nevery runner becomes a catalyst for hope, proving that small steps taken together can create a\\nlasting impact on society.","aicteMapping":"Community Service ","pointsEarned":10,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"7","signatureOfCounsellor":""},{"id":"o4Nc-jg3G3ple-yfOwc-y","name":"Blood Donation Camp","slNo":8,"place":"RVCE Campuw","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/74628168-f12b-47c9-9eb2-dfe8f03b91a8/XGL5aGsaYzn0JRY3pOZYS.jpeg"],"endDate":"2024-06-28","duration":1,"outcomes":"I learned the importance of social responsibility and how a small voluntary act can make a\\nsignificant impact on saving lives. The experience increased my awareness about the blood\\ndonation process, safety measures, and healthcare ethics. It also reinforced values of empathy,\\ncommunity service, and civic responsibility.","semester":"4","startDate":"2024-06-28","hoursSpent":1,"description":"I attended a blood donation camp organized to promote awareness about the importance of\\nvoluntary blood donation. The camp was conducted in a well-organized and hygienic manner,\\nensuring the safety and comfort of all participants. Medical professionals guided donors\\nthrough the process and carried out necessary health checks. The event highlighted the role of\\ncommunity participation in supporting healthcare needs and saving lives.","aicteMapping":"Blood Donation Camp","pointsEarned":10,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"8","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"Dr. Sandhya S","designation":"Associate Professor"},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-30 05:54:21.523251+00', '2026-02-02 05:20:39.303732+00'), ('12a9c095-defd-4013-b384-dc4814ccd3a3', '02579ef3-9aa4-4e53-9d24-a58384f69d14', '{"student":{"usn":"1RV22CS194","name":"Shriniwas Maheshwari","period":"2022-2026","department":"Computer Science & Engineering","totalPoints":0},"activities":[{"id":"1fMhdi6-lxwGgiVWW4UJS","name":"Walkathon 2025 (Female Foeticide Awareness Walkathon)","slNo":1,"place":"","photos":[],"endDate":"","duration":0,"outcomes":"The event witnessed participation from over 350 individuals, including students, faculty members, and parents, creating a strong atmosphere of solidarity and purpose. Through impactful slogans, placards, and collective action, the walkathon effectively educated and inspired the community to take a stand against gender-based violence and discrimination. It served as a powerful platform to amplify the message of social equality and reinforced the Rotaract Club of RVCE’s commitment to driving meaningful social change.","semester":"4","startDate":"","hoursSpent":0,"description":"The Female Foeticide Awareness Walkathon was organized by the Rotaract Club of RVCE on 11th May 2025, coinciding with Mother’s Day, with the objective of raising awareness about the issue of female foeticide and promoting the value of the girl child in society. The walkathon began early in the morning from the RVCE campus and involved participants marching together with placards and slogans advocating gender equality and social justice.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":15,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-30 14:10:45.262162+00', '2026-01-30 17:34:03.205044+00'), ('1503e3ef-e3d8-4782-9df8-09590bd36e96', 'a18719d8-e17d-4b79-aef1-182d85cab904', '{"student":{"usn":"1RV22EI017","name":"Chirag V","period":"2022-2026","department":"Electronics & Instrumentation Engineering","totalPoints":0},"activities":[{"id":"452erYV_6g5QIgQ5UuaB8","name":"NSS Blood Donation Camp","slNo":1,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/a18719d8-e17d-4b79-aef1-182d85cab904/HVl3zG1Nqs93USDUPvi94.png"],"endDate":"","duration":0,"outcomes":"The marathon successfully raised funds for social welfare activities while promoting a culture \\nof fitness and community participation among students. The event strengthened the values of \\nteamwork, leadership, and volunteerism as NSS members efficiently managed registration, \\nlogistics, crowd management, and awareness campaigns. Participants gained a sense of \\nfulfillment by contributing to meaningful social causes, and the initiative helped build a \\nstronger connection between the institution and the community. The successful execution of \\nthe marathon showcased the commitment of students toward social development and motivated \\nmore volunteers to engage in future NSS activities.","semester":"1","startDate":"2023-06-06","hoursSpent":0,"description":"NSS Utsarga Marathon was organized as a fundraising initiative to support various social \\ncauses and welfare activities. The event aimed to create awareness about health, fitness, and \\ncommunity service while encouraging students and citizens to contribute toward societal \\ndevelopment. Participants from different departments and local community members \\nenthusiastically joined the marathon, showcasing unity, discipline, and social responsibility. \\nThe funds collected through registrations and sponsorships were allocated to support future \\nNSS outreach activities and charitable initiatives, reinforcing the spirit of service among \\nyouth. ","aicteMapping":"","pointsEarned":6,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/a18719d8-e17d-4b79-aef1-182d85cab904/I8vM2p7IO347aK1wj_ZWM.png","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"5SVnCLpIemNFWhF3XGrA5","name":"Energy Literacy Training  ","slNo":2,"place":"Online Certification","photos":[],"endDate":"","duration":0,"outcomes":"Outcome\\tThe outcome of the Energy Literacy Certification was a heightened awareness of environmental responsibility and a solid foundation in sustainable energy concepts. The training equipped the participant with the knowledge and motivation to advocate for renewable energy solutions, reduce carbon emissions, and promote energy-conscious practices. Overall, the certification contributed to personal growth, environmental awareness, and the development of a sustainability-oriented mindset aligned with global efforts toward energy conservation and climate resilience.","semester":"2","startDate":"2023-08-30","hoursSpent":0,"description":"The Energy Literacy Certification was successfully completed as part of the Energy Literacy Training program conducted by the Energy Swaraj Foundation. The program was structured to educate participants on the fundamental concepts of energy and to promote awareness about the critical role energy plays in sustainable development. The training aimed to sensitize individuals to the challenges associated with conventional energy usage and the urgent need for adopting cleaner and more sustainable energy practices.\\nThe certification program provided a comprehensive understanding of energy generation, consumption, and wastage, along with their direct and indirect impacts on the environment. Key topics included carbon footprint analysis, climate change implications, and the long-term effects of fossil fuel dependency. The training also addressed prevalent misconceptions related to renewable energy, particularly solar energy, and emphasized practical approaches to adopting decentralized energy solutions. Participants were introduced to alternative energy technologies and were encouraged to evaluate energy usage patterns in their personal and professional environments.\\nThe program further highlighted the importance of energy efficiency, responsible consumption, and sustainable lifestyle choices. Through structured modules and real-world examples, the training helped participants understand how small changes in daily energy usage can collectively contribute to significant environmental benefits. The course fostered critical thinking regarding energy policies, conservation strategies, and the role of individuals and communities in driving the transition towards clean energy. \\n","aicteMapping":"","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/a18719d8-e17d-4b79-aef1-182d85cab904/jmK_uQPioDZ4pYsstHor6.png","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"zWdbL-XL0fqj0wj2dhi4h","name":"Project PUSTAK","slNo":3,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/a18719d8-e17d-4b79-aef1-182d85cab904/I_pUByJSDfd3QL5L3CkxO.jpg"],"endDate":"","duration":0,"outcomes":"In 2024, the PUSTHAKA - A Stationery Kit Distribution Program aims to \\nbuild on its 2023 success by expanding its reach to over 10,000 \\nunderprivileged children across rural schools. By providing essential \\nsupplies like notebooks and geometry boxes, the initiative seeks to reduce \\nabsenteeism further, empower communities, and promote education as a \\npriority for economically disadvantaged families. This ambitious goal \\nunderscores the program''s commitment to transforming lives and \\nfostering equal educational opportunities. ","semester":"3","startDate":"2024-04-25","hoursSpent":0,"description":"Pusthaka- A Stationery Kit Distribution Program, a joint initiative by RV \\nCollege of Engineering and Pranav Foundation, has made a substantial impact \\nin 2023. Our observation revealed that children in rural government schools \\nfrom underprivileged communities face challenges in obtaining basic \\nstationery, leading to some missing classes. Parents, often from economically \\ndisadvantaged backgrounds, struggle to provide timely notebooks and \\ngeometry boxes for their children. In response to this critical issue, we initiated \\nthe PUSTHAKA project in 2023, reaching out to over 1500 children. The \\npositive effects and impact of the 2023 project have fueled our motivation to \\nextend our reach to more than 10,000 children in 2024. To make this ambitious \\ngoal a reality, we earnestly seek support from each one of you. Let''s unite to \\nuplift underprivileged children by encouraging donations, connecting with \\npotential donors, and sharing this impactful initiative with your friends. Your \\nsupport can make a meaningful difference in the lives of these children.","aicteMapping":"","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/a18719d8-e17d-4b79-aef1-182d85cab904/QkQ2ClWa-UHDzW_KO_UOr.jpeg","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"3ozE3ox4--IjsW7RNDCQY","name":"UTPT","slNo":4,"place":"RVCE Campus","photos":[],"endDate":"","duration":0,"outcomes":"Highlighted India’s heritage by focusing on topics related to its culture, history, \\nand contributions to the world. Engaged participants and the audience in learning \\nabout India’s achievements in fields like architecture, mythology, and ancient \\nsciences. Provided a platform for quizzing enthusiasts to test their knowledge \\nwhile gaining new insights into India’s legacy. Helped create a lively yet \\neducational atmosphere, making the quiz both enjoyable and meaningful. \\nReinforced the importance of celebrating and spreading awareness about \\nIndia’s cultural identity through innovative events like quizzes. ","semester":"4","startDate":"2024-09-07","hoursSpent":0,"description":"UTPT 2024 was an exciting quiz competition that brought together quizzing \\nenthusiasts from various backgrounds to test their knowledge and teamwork. \\nKnown for its engaging format and challenging questions, this year’s edition had \\na special focus on promoting information about India and its rich heritage. From \\nancient achievements in mathematics and science to cultural and historical \\nmilestones, the quiz offered participants a chance to explore and appreciate \\nIndia’s vast legacy in a fun and competitive environment.Being part of UTPT \\n2024 was a fulfilling experience. It was not just about answering questions but \\nalso about learning more about India’s contributions to the world. Questions on \\ndiverse topics like Indian mythology, ancient scripts, architectural marvels, and \\nhistorical events helped participants and the audience gain a deeper \\nunderstanding of the country’s heritage. The atmosphere was lively yet thought\\nprovoking, making it a great mix of competition and learning. UTPT 2024 stood \\nout as a platform to celebrate and spread awareness about India’s cultural identity \\nwhile keeping the spirit of quizzing alive.","aicteMapping":"","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/a18719d8-e17d-4b79-aef1-182d85cab904/G9aibVCs8u9lUYXyxmCZ_.jpeg","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"nq-Nu9owjcyU6gtFPApeS","name":"CSITSS 2024","slNo":5,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/a18719d8-e17d-4b79-aef1-182d85cab904/JDlKHmOgRYjV2YQRdndQu.png"],"endDate":"","duration":0,"outcomes":"Outcome\\tThe conference significantly enhanced participants’ understanding of sustainable and advanced computing technologies and encouraged research-oriented and interdisciplinary thinking. It provided valuable opportunities for networking with international researchers and industry professionals, fostering academic collaboration and knowledge exchange. Students and participants gained insights into current industry practices, research challenges, and future directions in technology for sustainable development. Overall, CSITSS–2024 contributed to the professional growth of participants by strengthening technical knowledge, research aptitude, and global awareness in the field of computational systems and information technology.","semester":"4","startDate":"2024-11-07","hoursSpent":0,"description":"The 8th IEEE International Conference on “Computational Systems and Information Technology for Sustainable Solutions (CSITSS – 2024)” was organized at RV College of Engineering, Bengaluru, in association with Florida International University (FIU), USA, and Fachhochschule Dortmund, Germany, with technical co-sponsorship from the IEEE Bangalore Section. The conference aimed to provide an international platform for researchers, academicians, industry professionals, and students to share knowledge, research findings, and innovative ideas focused on sustainable technological solutions. The conference focused on a wide range of contemporary and future-oriented themes including Green Electronics, Renewable Energy, Artificial Intelligence, Robotics, Quantum Mechanics, and Digital Transformation. It featured keynote and invited talks delivered by distinguished international and industry experts who shared insights on recent advancements, real-world applications, and future research directions","aicteMapping":"","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/a18719d8-e17d-4b79-aef1-182d85cab904/zOnioYMtbXJrk8J9fhCS0.png","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"cvAx1YvnIZ7NruV4KZBis","name":"GENESIS Outreach Program ","slNo":6,"place":"Bengaluru","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/a18719d8-e17d-4b79-aef1-182d85cab904/fu3lWTSxzHrqYHQ3yFhqq.png"],"endDate":"","duration":0,"outcomes":"Outcome\\tThe Genesis Outreach Program successfully bridged the gap between theoretical classroom learning and real-world engineering applications, fostering early interest in STEM fields among school students. Participants gained hands-on exposure to robotics and engineering principles, which enhanced their curiosity, engagement, and conceptual understanding. The initiative reached a large and diverse group of students across multiple schools, creating a meaningful educational impact. Beyond the workshops themselves, the project demonstrated the dedication, teamwork, and organizational skills of Team Astra Robotics, with significant effort invested in planning, kit preparation, and execution. Overall, the outreach program strengthened the culture of STEM education and contributed positively to community engagement and technical awareness.","semester":"5","startDate":"2025-02-24","hoursSpent":0,"description":"The Genesis Outreach Program was conducted by Team Astra Robotics, a student-led robotics research club, with the objective of inspiring school students to explore engineering and robotics through hands-on learning. As part of the initiative, interactive workshops were organized across five institutions in Bangalore, including VVS Bangalore, MES Kishore Kendra (Malleshwaram), Vidya Mandir Independent PU College (Malleshwaram), St. Claret (Jalahalli), and Base PU College. Each workshop was carefully structured to introduce core engineering concepts such as electronics, embedded systems, automation, and control systems. The sessions emphasized practical demonstrations, guided experiments, and problem-solving activities, and were conducted for approximately 7 hours per day over two days at each school, following extensive planning, outreach, and preparation by the team.","aicteMapping":"","pointsEarned":15,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"oIsh2wwpXywTWPEIN2dvZ","name":"Project PUSTAK","slNo":7,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/a18719d8-e17d-4b79-aef1-182d85cab904/1lJf4SxRguKdsR5wKVKuq.png"],"endDate":"","duration":0,"outcomes":"OutcomeThe Rotaract Project Pustak drive successfully gathered and distributed essential \\neducational materials to deserving students, enabling them to pursue their studies with \\nconfidence and dignity. The activity helped bridge the learning resource gap for many \\nchildren while spreading awareness about the importance of education and youth contribution \\ntoward social development. Through this initiative, I gained valuable exposure to community \\nservice and developed qualities such as empathy, responsibility, and social awareness. The \\nproject strengthened collaboration between volunteers and Rotaract members and encouraged \\ncontinued involvement in educational support programs. Overall, the initiative created a positive \\nimpact by promoting equal learning opportunities and inspiring young minds to value and \\nsupport education for all. ","semester":"6","startDate":"2025-04-30","hoursSpent":0,"description":"Rotaract Project Pustak was an educational support initiative aimed at empowering \\nunderprivileged school children by providing them with academic materials and learning \\nresources. As part of this campaign, students and volunteers contributed funds and books to help \\nensure that children from economically weaker backgrounds could continue their education \\nwithout facing a shortage of basic study necessities. I actively took part in this initiative \\nby donating educational supplies/monetary support, thereby contributing to the mission of \\npromoting literacy and learning. The project was executed in collaboration with the Rotaract \\nClub, which coordinated the collection and distribution process across various schools and \\ncommunity centers. This initiative served as a reminder of the power of collective effort in \\nshaping a brighter and more educated future for children in need.","aicteMapping":"","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/a18719d8-e17d-4b79-aef1-182d85cab904/yMqWyFGRDJ0IJV-b1A3-h.jpeg","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"ncyBTL-SKZBRAceuDyVEH","name":"GENESIS Outreach Program","slNo":8,"place":"Bengaluru","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/a18719d8-e17d-4b79-aef1-182d85cab904/rhzyBVlvNtP6inc8YjyQF.png"],"endDate":"","duration":0,"outcomes":"The workshop successfully bridged the gap between theoretical knowledge and practical \\napplication, fostering early interest in engineering and robotics among students. Participants \\ngained hands-on exposure to fundamental engineering concepts, enhancing their understanding \\nand engagement with STEM fields. The initiative demonstrated the dedication and teamwork \\nof Team Astra Robotics, with more than 15 hours of collective effort contributing to a \\nwell-organized and impactful outreach program. Overall, the workshop created meaningful \\neducational impact and strengthened the institution’s outreach efforts in promoting engineering \\nawareness at the school level. ","semester":"7","startDate":"2025-11-17","hoursSpent":0,"description":"As part of the School Genesis Outreach Program, Team Astra Robotics conducted a hands-on \\nengineering and robotics workshop at St. Claret’s on 25th October. The workshop was held \\nfrom 9:00 AM to 5:30 PM and was designed to introduce school students to core engineering \\nconcepts such as electronics, embedded systems, automation, and control systems. The sessions \\nfocused on interactive learning through practical demonstrations, guided experiments, and \\nproblem-solving activities. In addition to the workshop hours, the team invested significant \\ntime in planning, kit preparation, and logistics to ensure smooth and effective execution of the \\nprogram. ","aicteMapping":"","pointsEarned":10,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"rho57UzD41sx67FqqQFKT","name":"Rotaract FIST FULL ","slNo":9,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/a18719d8-e17d-4b79-aef1-182d85cab904/XWH2YoT1bcrKTozmDDe10.png"],"endDate":"","duration":0,"outcomes":"The initiative witnessed an enthusiastic response from the student community, with active \\nparticipation from over 1,750 students. The collective effort resulted in the collection of more \\nthan 6,700 kg of rice and over 800 kg of toor dal, which were directed toward supporting hunger \\nrelief efforts. The successful execution of the project demonstrated the power of collective action \\nand showcased how small individual contributions can lead to substantial social impact. Overall, \\n“Fist Full” strengthened the culture of volunteering at RVCE and reaffirmed the institution’s \\ncommitment to societal development and humanitarian values. ","semester":"7","startDate":"2025-11-18","hoursSpent":0,"description":"“Fist Full” was a social outreach initiative undertaken by the Rotaract Club of RVCE in \\ncollaboration with Rotary Bangalore Spandana, conducted from November 15 to 29. The \\nprimary objective of the project was to address hunger and food insecurity by motivating \\nstudents to donate essential food grain, either 5 kg of rice or 2 kg of toor dal. To ensure smooth \\nparticipation, daily collection drives were organized in the Civil Department, making the process \\nconvenient and well-coordinated. Through this initiative, students were sensitized to social \\nresponsibility and encouraged to contribute meaningfully to community welfare through simple \\nyet impactful actions. ","aicteMapping":"","pointsEarned":10,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""},{"id":"CGA7NiXveAdB-LLGJSoTK","name":"CSITSS 2025","slNo":10,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/a18719d8-e17d-4b79-aef1-182d85cab904/T9TUKRcKl7ka1ikS1ZEEv.png"],"endDate":"","duration":0,"outcomes":"Participation as a student volunteer in CSITSS–2025 provided extensive exposure to international academic conference organization and professional research environments. Volunteers developed essential skills such as coordination, communication, leadership, teamwork, and problem-solving while managing large-scale academic operations. The experience enhanced understanding of research dissemination processes, peer-reviewed paper presentations, and global collaboration in sustainable technology domains. The conference also enabled meaningful interaction with international researchers and professionals, broadening academic perspectives and professional confidence. Overall, the activity significantly contributed to the holistic development of student volunteers by strengthening their organizational competence, professional ethics, and appreciation for sustainable and interdisciplinary research initiatives.","semester":"7","startDate":"2025-11-20","hoursSpent":0,"description":"The 9th IEEE International Conference on Computational Systems and Information Technology for Sustainable Solutions (CSITSS–2025) was held at RV College of Engineering, Bengaluru, from 20th to 22nd November 2025, and was jointly organized in association with international academic partners and technically co-sponsored by IEEE. The conference served as a global academic platform, bringing together researchers, academicians, industry professionals, and students to discuss advancements in sustainable computing technologies. Student volunteers played a crucial role in the successful execution of the conference, contributing across multiple phases including pre-conference planning, conference execution, and post-conference activities. Their responsibilities included assisting in paper submission systems, coordinating with speakers and delegates, managing technical sessions, supporting registration and hospitality, handling audiovisual systems, and ensuring smooth conduct of keynote addresses, tutorials, and parallel technical sessions conducted in both online and offline modes.","aicteMapping":"","pointsEarned":15,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-30 12:39:28.119103+00', '2026-02-01 06:11:32.119557+00'), ('1620528c-9694-42e3-bb06-636082771d94', 'caec5a22-fb06-4a44-91ed-bab4358989df', '{"student":{"usn":"1RV22EC096","name":"Mrigaannkaa Singh","period":"2022-2026","department":"Electronics & Communication Engineering","totalPoints":0},"activities":[{"id":"Kxy-8UBlUXsGS78JESo9R","name":"TEDxRVCE 2025","slNo":1,"place":"","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/caec5a22-fb06-4a44-91ed-bab4358989df/rRXRthEGMJDrqCN8miAyR.png"],"endDate":"2024-08-04","duration":1,"outcomes":"It fostered learning beyond classrooms, encouraged responsibility toward society, and set a benchmark for environmentally conscious events at the institutional level. Being associated with this event was both a privilege and a valuable learning journey that will remain impactful well beyond the day it was held.","semester":"5","startDate":"2024-08-04","hoursSpent":0,"description":"The talks delivered during the event left a lasting impact. Mr. Nikhil Isaac provided valuable insights into sustainable architecture and the future of green urban design, reinforcing the importance of responsible development aligned with Sustainable Development Goal (SDG) 11. Mr. Gopikrishna Warrier’s session highlighted the power of storytelling in environmental journalism, emphasizing its role in climate action and institutional accountability, aligning with SDGs 13 and 16. These sessions encouraged critical thinking and inspired the audience to view sustainability as an active responsibility rather than a passive concept.\\nA unique and thoughtful aspect of the event was the distribution of eco-conscious goodie bags containing seed pencils and seed balls. This initiative symbolized the core values of TEDxRVCE 2025—sustainability, environmental awareness, and individual contribution toward a greener future. It served as a reminder that small actions, when multiplied, can lead to meaningful change.\\n","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":10,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-30 05:05:47.365637+00', '2026-01-30 05:23:39.419027+00'), ('184c72d4-43c2-4736-9456-179ec50bc90d', 'db9f13fd-81fc-42c4-9776-c2a0491b82b1', '{"student":{"usn":"1RV22CY015","name":"Ashutosh Joshi","period":"2022-2026","department":"Computer Science & Engineering - Cybersecurity","totalPoints":0},"activities":[{"id":"vdpSUJSrfAaEMra-MDqhM","name":"Blood Donation Camp","slNo":1,"place":"RVCE","photos":[],"endDate":"2024-06-28","duration":1,"outcomes":"The initiative aimed to promote the spirit of humanitarian service and raise awareness about the importance of voluntary blood donation. Prior to donating, all participants underwent a medical screening to ensure safety and eligibility. The camp maintained high standards of hygiene and medical supervision, ensuring a smooth and secure donation process for everyone involved.\\nThe tremendous participation reflected the compassion and\\nsense of social responsibility within the RVCE community. Each\\nunit of blood collected represented a potential life saved helping accident victims, surgery patients, and those suffering from chronic illnesses. The event not only achieved its target but also inspired many first-time donors to make blood donation a\\nregular act of kindness, reinforcing the Rotaract Club’s commitment to service and humanity.\\n","semester":"4","startDate":"2024-06-28","hoursSpent":2,"description":"Rotaract Club of RVCE organized a\\nlarge-scale Blood Donation Camp in collaboration with leading hospitals and blood banks. The event witnessed an overwhelming response from students, faculty, and staff, resulting in the successful collection of around 600 units of blood\\n","aicteMapping":"Social Service / Community Development Activities","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/db9f13fd-81fc-42c4-9776-c2a0491b82b1/sHhCsstC3P3xhj32NyVJX.jpeg","certificateAttached":true,"detailedReportPageNo":"1","signatureOfCounsellor":""},{"id":"nj150J--hmJRj7F_HhgAa","name":"Spark Volunteer Graduation day","slNo":2,"place":"Poornima Palace","photos":[],"endDate":"2024-08-04","duration":2,"outcomes":"Developed teamwork, leadership, and event-management skills while gaining experience in handling large-scale academic events with responsibility and professionalism.","semester":"4","startDate":"2024-08-03","hoursSpent":15,"description":"Actively volunteered as a Spark team member during the Graduation Day ceremony, assisting in event coordination, guest management, student guidance, and ensuring smooth execution of the program.\\n\\n","aicteMapping":"Event Organization / Institutional Activities","pointsEarned":8,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/db9f13fd-81fc-42c4-9776-c2a0491b82b1/KS47ZAzbvzgjeFyssttSW.jpeg","certificateAttached":true,"detailedReportPageNo":"3","signatureOfCounsellor":""},{"id":"bHog86LMUqRN3jVnJqC25","name":"Skill lab","slNo":3,"place":"RVCE ","photos":[],"endDate":"2025-04-26","duration":6,"outcomes":"Enhanced technical knowledge, communication skills, and mentoring abilities while gaining experience in practical teaching and laboratory management.","semester":"5","startDate":"2025-04-21","hoursSpent":20,"description":"Participated in conducting Skill Lab sessions by assisting in organizing practical activities, guiding students during hands-on tasks, and supporting the smooth functioning of lab sessions.","aicteMapping":"Skill Development Activities","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/db9f13fd-81fc-42c4-9776-c2a0491b82b1/CYeHfjnnLcy9nb4-mIuA2.jpeg","certificateAttached":true,"detailedReportPageNo":"5","signatureOfCounsellor":""},{"id":"ibqLXk6WSrcqT78D3Xnbc","name":"EduAlthon ","slNo":4,"place":"RVCE","photos":[],"endDate":"2025-05-15","duration":8,"outcomes":"Developed organizational, leadership, and communication skills while gaining experience in managing educational events and working effectively in a team environment.","semester":"5","startDate":"2025-05-08","hoursSpent":25,"description":"Volunteered in the Eduathon event by assisting in event coordination, participant management, logistics support, and ensuring smooth conduct of academic and innovation-based activities.","aicteMapping":"Technical / Innovation / Hackathon Activities","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/db9f13fd-81fc-42c4-9776-c2a0491b82b1/4QLUibF4pyziS2jXhFtiL.jpeg","certificateAttached":true,"detailedReportPageNo":"7","signatureOfCounsellor":""},{"id":"LtKsrKDgzcF8ChjGg_Dna","name":"NSS mera phala vote desh keliye","slNo":5,"place":"RVCE","photos":[],"endDate":"2023-03-06","duration":1,"outcomes":"Gained a better understanding of civic responsibility, the significance of voting, and the role of young citizens in strengthening democracy.","semester":"2","startDate":"2023-03-06","hoursSpent":4,"description":"Actively participated in the NSS campaign “Mera Pehla Vote, Desh Ke Liye,” aimed at creating awareness among youth about the importance of voting and promoting democratic values.","aicteMapping":"Social Awareness / Civic Responsibility Activities","pointsEarned":4,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/db9f13fd-81fc-42c4-9776-c2a0491b82b1/pPbjQauN3DZdIK2Yf3zMr.jpeg","certificateAttached":true,"detailedReportPageNo":"9","signatureOfCounsellor":""},{"id":"6C8ixmEGT7SvWJPD7KbcQ","name":"Fist Full","slNo":6,"place":"RVCE","photos":[],"endDate":"2025-10-28","duration":8,"outcomes":"With the support of Rotary Bangalore Spandana and under the Community Service avenue focusing on Fighting Disease, the project transformed individual contributions into large-scale nutritional support for vulnerable communities.\\nEvent Description\\nThe Fistful initiative witnessed enthusiastic participation from 2146 students, each contributing essential food grains in the form of either 5 kg of rice or 2 kg of dal. This collective effort resulted in the successful collection and distribution of food grains to multiple beneficiary institutions that serve daily meals to children, the elderly, patients\\n","semester":"6","startDate":"2025-10-21","hoursSpent":2,"description":"Fistful was a standalone community service project designed to combat food insecurity and support health and care institutions through collective student participation. The initiative was built on a simple yet impactful principle - every participating student donated either 5 kilograms of rice or 2 kilograms of dal.","aicteMapping":"Health, Wellness","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/db9f13fd-81fc-42c4-9776-c2a0491b82b1/Msj_0ojWVBGAr0raUVJM5.jpeg","certificateAttached":true,"detailedReportPageNo":"11","signatureOfCounsellor":""},{"id":"BuxYdntciw9p2EWNodkuz","name":"Paper Drive","slNo":7,"place":"IndraNagar","photos":[],"endDate":"2024-06-23","duration":1,"outcomes":"The students started early in the morning, going door-to-door and visiting businesses to gather donations. Their efforts resulted in a significant collection of materials which aims to help charities and NGOs in order to support their initiatives and assist people in need.\\nThe Paper Drive not only aimed to provide resources for charitable organizations but also raised awareness about community involvement.\\nThe event was a resounding success, showcasing the power of student engagement in addressing social issues and fostering a sense of responsibility among the participants and the residents of Bangalore.\\n","semester":"4","startDate":"2024-06-23","hoursSpent":8,"description":"On 23rd June 2024, the Rotaract Club of RVCE organized the \"Paper Drive,\" engaging over 400 student volunteers to collect books, papers, and waste materials across various areas of Bangalore","aicteMapping":"Environmental Protection / Sustainability Activities","pointsEarned":8,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/db9f13fd-81fc-42c4-9776-c2a0491b82b1/3sOK0Awf1u1wuxlpQvD9R.jpeg","certificateAttached":true,"detailedReportPageNo":"13","signatureOfCounsellor":""},{"id":"uJ4NhOG2qLuJ_CLGkjOdH","name":"Utsarga Marathon","slNo":8,"place":"RVCE","photos":[],"endDate":"2025-04-06","duration":1,"outcomes":"Improved physical fitness, discipline, and team spirit while developing awareness about the importance of health, endurance, and social responsibility.","semester":"7","startDate":"2025-04-06","hoursSpent":3,"description":"Actively participated in the Utsarga Marathon event, contributing to the promotion of fitness, social awareness, and community engagement through organized physical activity.","aicteMapping":"Health, Fitness & Social Awareness Activities","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/db9f13fd-81fc-42c4-9776-c2a0491b82b1/tEz9S8I2dKiIwj9qhn3Vg.jpeg","certificateAttached":true,"detailedReportPageNo":"13","signatureOfCounsellor":""},{"id":"D0ojVDvGcjK57brKPL-YH","name":"Swachhata Hi seva","slNo":9,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/db9f13fd-81fc-42c4-9776-c2a0491b82b1/fmIGhmMSth-OfbQD9bhwc.jpeg"],"endDate":"2024-10-02","duration":1,"outcomes":"Developed awareness about cleanliness, public hygiene, and environmental responsibility while contributing positively to community welfare.","semester":"4","startDate":"2024-10-02","hoursSpent":4,"description":"Actively participated in the NSS initiative “Swachhata Hi Seva” by taking part in cleanliness drives and awareness activities aimed at promoting hygiene, sanitation, and a clean environment","aicteMapping":"Cleanliness & Environmental Awareness Activities","pointsEarned":5,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"15","signatureOfCounsellor":""},{"id":"sayLJa1aHs0E4OTz9Ou9R","name":"Jeevan Rakshak Program","slNo":10,"place":"RVCE ","photos":[],"endDate":"2024-03-05","duration":1,"outcomes":"Gained essential knowledge of first aid, emergency handling, and the importance of timely response in saving lives, along with a sense of social responsibility.","semester":"3","startDate":"2024-03-05","hoursSpent":5,"description":"Participated in the NSS “Jeevan Rakshak Program,” which focused on creating awareness and providing basic training related to first aid, emergency response, and life-saving techniques.","aicteMapping":"Social Service / Disaster Management & First Aid Training","pointsEarned":2,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/db9f13fd-81fc-42c4-9776-c2a0491b82b1/wTw4Cobz3hZZvZrWKEIgN.jpg","certificateAttached":true,"detailedReportPageNo":"15","signatureOfCounsellor":""},{"id":"1-_y67q4DA7pvK_LHB0Ow","name":"Through the Eyes Of YOUth","slNo":11,"place":"RVCE","photos":[],"endDate":"2023-08-19","duration":8,"outcomes":"Enhanced creative thinking, observation skills, and awareness of global sustainability challenges while developing the ability to express social issues effectively through visual storytelling and written communication.","semester":"2","startDate":"2023-08-12","hoursSpent":10,"description":"Participated in the “Through the Eyes of YOUth” activity by capturing photographs aligned with the United Nations Sustainable Development Goals (SDGs) and submitting a reflective essay highlighting social, environmental, or developmental issues.","aicteMapping":"Creativity / Social Awareness / SDG-related Activities","pointsEarned":4,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/db9f13fd-81fc-42c4-9776-c2a0491b82b1/YZ8FgcnKWDLXVZ006encb.png","certificateAttached":true,"detailedReportPageNo":"17","signatureOfCounsellor":""},{"id":"DtBJowX_fbxZDfx-92OFh","name":"Blood Donation Camp","slNo":12,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/db9f13fd-81fc-42c4-9776-c2a0491b82b1/SgDi5qkHztiObLo-cpbLz.jpeg"],"endDate":"2025-10-30","duration":1,"outcomes":"The Blood Donation Camp organized by the Rotaract Club of RVCE was a tremendous success, collecting around 800 units of blood and significantly contributing to local hospitals and blood banks. The initiative fostered a strong sense of social responsibility and compassion among participants while promoting awareness about the importance of regular blood donation. The event not only helped save numerous lives but also strengthened the spirit of community service within the RVCE fraternity","semester":"7","startDate":"2025-10-30","hoursSpent":2,"description":"Rotaract Club of RVCE organized a\\nlarge-scale Blood Donation Camp in collaboration with leading hospitals and blood banks. The event witnessed an overwhelming response from students, faculty, and staff, resulting in the successful collection of 1000+ units of blood.\\n","aicteMapping":"Social Service / Community Development Activities","pointsEarned":15,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"19","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-30 05:42:47.775384+00', '2026-01-31 06:18:14.020394+00'), ('18f3aaca-9dd9-4c29-b93b-f89e2866c393', 'bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c', '{"student":{"usn":"1RV22CY009","name":"Amogh A Joshi","period":"2022-2026","department":"Computer Science & Engineering - Cybersecurity","totalPoints":0},"activities":[{"id":"bzsjLxIjItYeSJgBQhCbF","name":"Blood Donation Camp","slNo":1,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/e88SpXsg9MzvWI6EGvDKv.jpg"],"endDate":"2023-06-06","duration":1,"outcomes":"The blood donation camp successfully collected a substantial quantity of blood units, which\\nwere added to the local blood bank’s inventory and will support patients in need of transfusions\\nduring emergencies and medical treatments. The event raised awareness among participants\\nand the wider community about the importance of voluntary blood donation, helping dispel\\nmyths and encourage future donor participation. It also fostered a strong sense of community\\nengagement, social responsibility, and solidarity among students and volunteers involved in the\\ninitiative.","semester":"2","startDate":"2023-06-06","hoursSpent":6,"description":"I participated in a blood donation activity as part of the AICTE Social Service initiative.\\nBy voluntarily donating blood, I contributed to supporting patients in need and promoting\\nawareness about the importance of blood donation in society. This activity helped me develop a\\nsense of social responsibility, empathy, and commitment toward community welfare and public\\nhealth.","aicteMapping":"Social Service Initiative to contribute to the society","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/pEGdzClUUfQ5KRZ-w6WNU.png","certificateAttached":true,"detailedReportPageNo":"2-3","signatureOfCounsellor":""},{"id":"Y9YzrG7F-sErPZkeCygyK","name":"National Farmathon","slNo":3,"place":"Art of Living premises, Kanakpura Main Road, Bangalore","photos":[],"endDate":"2023-12-23","duration":1,"outcomes":"Enhanced awareness about the importance of agriculture and the role of farmers in national development.\\n\\nImproved understanding of sustainable and eco-friendly farming practices.\\n\\nStrengthened sense of social responsibility and respect towards farmers.\\n\\nEncouraged youth participation in agricultural and rural development initiatives.\\n\\nDeveloped teamwork, leadership, and community engagement skills among participants.","semester":"3","startDate":"2023-12-23","hoursSpent":12,"description":"I participated in the NSS National Farmathon organized in celebration of National Farmers’ Day. The event aimed to promote awareness about agriculture, sustainable farming practices, and the invaluable contribution of farmers to the nation. Through various activities and interactions, the Farmathon encouraged youth participation in strengthening the agricultural sector and supporting rural development.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/y6c6MUjEG7cHGOTexlWxG.jpeg","certificateAttached":true,"detailedReportPageNo":"6-7","signatureOfCounsellor":""},{"id":"ixjpC0ifllT2iHQokuU7L","name":"Utsarga Marathon 2024","slNo":4,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/XDwr27givX7mj0RwigWUe.jpg"],"endDate":"2024-02-04","duration":1,"outcomes":"Increased awareness about the importance of regular exercise, fitness, and a healthy lifestyle.\\n\\nEncouraged active participation from students and community members, strengthening social\\nconnections.\\n\\nHelped participants develop resilience, discipline, and goal-setting skills.\\n\\nPromoted teamwork, motivation, and sportsmanship.","semester":"3","startDate":"2024-02-04","hoursSpent":8,"description":"The marathon, organized by the National Service Scheme (NSS), was designed to promote\\nphysical fitness, healthy living, and active community participation. The event attracted\\nstudents, faculty, and local residents who came together to participate in long-distance running\\nacross a carefully planned route within the city. The marathon emphasized endurance, stamina,\\nand perseverance, while also encouraging participants to push their personal limits and set\\nachievable goals.\\nIn addition to its focus on fitness, the marathon served as a platform for social engagement,\\nallowing participants to connect with fellow community members and promote a sense of unity.\\nNSS volunteers played a key role in organizing the event, managing logistics, ensuring safety,\\nand motivating participants. The marathon also highlighted NSS’s broader mission of fostering\\nleadership, teamwork, and social responsibility among students, demonstrating how physical\\nactivity can be effectively combined with community service initiatives.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/N1HGLeIv4pXckc3aVMQDU.png","certificateAttached":true,"detailedReportPageNo":"8-9","signatureOfCounsellor":""},{"id":"IxLOb50-MMv_prGAWNvoZ","name":"Project Pustak","slNo":6,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/FjLF6X3hQpblVxZz9Lyud.jpg"],"endDate":"2024-05-24","duration":1,"outcomes":"A significant number of books and study materials were\\ncollected and redistributed to students in need.\\nUnderprivileged children received access to learning resources,\\nsupporting their academic growth.\\nStudents developed empathy, social awareness, and a sense of\\nresponsibility toward educational equity.\\nThe activity promoted the values of sharing, sustainability\\n(reuse of books), and community service.","semester":"3","startDate":"2024-05-24","hoursSpent":5,"description":"Project Pustak 2024 was a social initiative organized to promote\\neducation access and literacy among underprivileged children.\\nThe project focused on collecting and distributing educational\\nmaterials such as textbooks, notebooks, storybooks, and stationery to students from economically weaker sections of society. Students actively participated by donating books and study materials that were in good condition. Volunteers sorted, categorized, and packed the collected materials based on age group and academic level to ensure effective distribution. The resources were then provided to government schools, community learning centers, and children from low-income families who lacked access to adequate learning materials.","aicteMapping":"To skill rural population","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/pUqLK-Og1LW4nb6C4ebok.png","certificateAttached":true,"detailedReportPageNo":"12-13","signatureOfCounsellor":""},{"id":"0Oc6-RIvQZsdHVUr8GTDE","name":"Blood Donation Camp","slNo":7,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/C1lNXW3HfV8ZxjWthKoed.jpg"],"endDate":"2024-06-28","duration":1,"outcomes":"Collected blood units to support hospitals and patients in need, directly contributing to life-saving efforts.\\n\\nRaised awareness among participants about the importance and impact of voluntary blood donation.\\n\\nEncouraged social responsibility, empathy, and community service among students and local residents.\\n\\nProvided Rotaract members with organizational and leadership experience in managing public health initiatives.\\n\\nPromoted a culture of voluntary giving, health consciousness, and civic engagement in the community","semester":"4","startDate":"2024-06-28","hoursSpent":6,"description":"The blood donation camp, organized by Rotaract, aimed to promote social responsibility, health\\nawareness, and community service among students and local residents. The event brought\\ntogether volunteers and donors at a designated venue, following all medical safety protocols to\\nensure a smooth and secure process. Participants were educated about the importance of blood\\ndonation, its life-saving impact, and the role it plays in supporting hospitals and patients in\\nneed.\\nThe camp also served as an opportunity to instill a sense of civic duty and empathy among\\nyoung individuals. Rotaract members coordinated logistics, registration, health checks, and\\npost-donation care, ensuring a safe and efficient experience for all donors. Beyond collecting\\nblood, the initiative sought to raise awareness about voluntary blood donation as a regular social\\npractice, highlighting how small individual contributions can have a profound impact on the\\ncommunity.","aicteMapping":"Social Service Initiative to contribute to the society","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/wnK1ayWcCtOzC7vCjrD6X.png","certificateAttached":true,"detailedReportPageNo":"14-15","signatureOfCounsellor":""},{"id":"2pzcf1gnfUseu33ko4e_O","name":"Fistful 2024","slNo":8,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/_sUSdcfO8tFm6Fc69Fgu_.jpg"],"endDate":"2024-11-17","duration":1,"outcomes":"A substantial quantity of rice and dal was collected,\\nhelping address food insecurity among vulnerable\\ncommunities.\\n\\nThe donated food grains supported nutrition programs in\\nold age homes, hospitals, schools, anganwadis, and\\ninstitutions for visually challenged children.","semester":"5","startDate":"2024-11-17","hoursSpent":6,"description":"The FistFull Initiative, organized by the Rotaract Club of RVCE in association with Rotary Bangalore Spandana (RI District 3191), was a large-scale community outreach program focused on reducing food insecurity and supporting underprivileged sections of society.\\n\\nThe initiative followed a simple yet powerful concept, where each participating student donated either 5 kg of rice or 2 kg of dal, turning small individual contributions into a collective effort with significant impact. The drive received overwhelming support, with participation from over 2,100 students, leading to the collection of a large quantity of essential food grains.\\n\\nAs part of this initiative, I personally contributed 2 kg of toor dal, which was added to the overall collection. The donated food grains were then distributed to various beneficiary organizations, including mass feeding programs, hostels for visually challenged children, old age homes, hospitals, trust-run schools, and nearby anganwadis.\\n\\nThese supplies helped strengthen existing nutrition programs benefiting children, senior citizens, patients, and economically disadvantaged communities. The distribution was carried out in a systematic and well-coordinated manner, with beneficiary institutions collecting the food supplies directly from the campus under the supervision of Rotaract and Rotary representatives.","aicteMapping":"Food preservation/packaging","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/Sn5txSRnNFUcH0TxmF6lr.jpeg","certificateAttached":true,"detailedReportPageNo":"16-17","signatureOfCounsellor":""},{"id":"bMP4t1Ixk4RaL4YRMGmFV","name":"Utsarga Marathon 2025","slNo":9,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/fYhwURNkef65FRT9XOGPz.jpg"],"endDate":"2025-04-06","duration":1,"outcomes":"Promoted physical fitness, mental resilience, and overall well-being among participants.\\n\\nStrengthened community engagement and student participation in socially responsible initiatives.\\n\\nEncouraged perseverance, discipline, and personal challenge through long-distance running.\\n\\nEnhanced teamwork, leadership, and organizational skills among NSS volunteers.\\n\\nReinforced NSS’s vision of combining individual development with service to society.","semester":"5","startDate":"2025-04-06","hoursSpent":8,"description":"The second marathon, conducted under the NSS, aimed to promote fitness while also raising awareness about societal and community issues. The event saw enthusiastic participation from students, faculty, and local residents, all coming together to engage in a long-distance run along a pre-determined route, supported by volunteers at checkpoints and hydration stations.\\n\\nThe marathon not only tested the endurance and perseverance of participants but also encouraged them to adopt a disciplined lifestyle, highlighting the connection between personal health and overall well-being.\\n\\nThrough this event, NSS volunteers emphasized teamwork, leadership, and social responsibility by coordinating logistics, ensuring safety, and motivating participants throughout the run. Additionally, the marathon served as a platform to foster unity, collective effort, and active civic engagement, reflecting NSS’s mission of integrating personal development with community service and social awareness.","aicteMapping":"To assist the marketing of rural produce","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/rr_9tnCSZWEwgnKlZ5x81.jpeg","certificateAttached":true,"detailedReportPageNo":"18-19","signatureOfCounsellor":""},{"id":"Sn07xd3v-gD_6SPppiW1R","name":"Project Pustak","slNo":10,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/nSi4Kskv3mLiH3uX2EAMi.jpg"],"endDate":"2025-04-30","duration":1,"outcomes":"A substantial number of books and study materials were collected and redistributed to children\\nin need.\\n\\nUnderprivileged students gained access to essential educational resources, supporting their academic progress.\\n\\nParticipating students developed empathy, social awareness, and a sense of responsibility toward educational equity.\\n\\nThe initiative reinforced values of sharing, sustainability through the reuse of books, and active community service.","semester":"6","startDate":"2025-04-30","hoursSpent":5,"description":"Project Pustak 2025 was a social initiative aimed at enhancing access to education and promoting literacy among underprivileged children. The project centered on collecting and distributing educational resources, including textbooks, notebooks, storybooks, and stationery, to students from economically disadvantaged backgrounds.\\n\\nStudents actively contributed by donating books and study materials in good condition, while volunteers organized, categorized, and packed the items according to age group and academic level to ensure effective distribution.\\n\\nThe collected resources were then provided to government schools, community learning centers, and children from low-income families who otherwise lacked access to essential learning materials.","aicteMapping":"To skill rural population","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/--BCBgk8jF0yo9IjKXHMJ.png","certificateAttached":true,"detailedReportPageNo":"20-21","signatureOfCounsellor":""},{"id":"GWDcFnITZoh7FDwOsVeHe","name":"Blood Donation Camp","slNo":11,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/WZ0dhbRLgLI_5AWdgU76I.jpg"],"endDate":"2025-10-30","duration":1,"outcomes":"Successfully collected blood units to aid hospitals and patients, directly contributing to life-saving efforts.\\n\\nEnhanced awareness among participants about the significance of voluntary blood donation.\\n\\nFostered a culture of social responsibility, empathy, and community participation.\\n\\nProvided Rotaract members with hands-on experience in organizing and managing health-related community initiatives.\\n\\nMotivated participants to adopt voluntary blood donation as a regular practice, promoting long-term community health benefits.","semester":"6","startDate":"2025-10-30","hoursSpent":6,"description":"The blood donation camp, conducted by Rotaract, was organized to promote health awareness,\\ncommunity service, and the spirit of volunteerism. The event provided a safe and well-structured\\nenvironment where students, faculty, and local residents could donate blood under professional\\nmedical supervision. Detailed briefings were given to all participants about the donation process,\\neligibility criteria, and the critical need for regular blood supply in hospitals.\\n\\nThe initiative aimed to instill a sense of social responsibility and empathy among participants\\nwhile fostering active community involvement. Rotaract members played a key role in managing\\nregistrations, health screenings, and post-donation care, ensuring a smooth and efficient process.\\nThe camp also served as an educational platform to encourage long-term voluntary blood\\ndonation habits, emphasizing how individual contributions collectively save lives and strengthen\\ncommunity health resilience.","aicteMapping":"Social Service Initiative to contribute to the society.","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/tDancDS42v3FVcpKQZsFd.png","certificateAttached":true,"detailedReportPageNo":"22-23","signatureOfCounsellor":""},{"id":"1M8LNQK6vh1c3L6kXLeQn","name":"Fistful 2025","slNo":12,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/ciik7cEr-zfUGMXhWVXpD.jpg"],"endDate":"2025-11-24","duration":8,"outcomes":"A substantial quantity of rice and dal was collected, addressing food insecurity among vulnerable populations.\\n\\nDonations supported nutrition programs in schools, anganwadis, hospitals, old age homes, and hostels for visually challenged children.\\n\\nEncouraged mass participation, with over 2,100 students contributing to the collective effort.\\n\\nFostered social responsibility, empathy, and community engagement among participants.\\n\\nHighlighted the impact of small individual contributions when combined for a larger social cause.","semester":"7","startDate":"2025-11-17","hoursSpent":5,"description":"The FistFull Initiative, organized by the Rotaract Club of RVCE in collaboration with Rotary Bangalore Spandana (RI District 3191), was a large-scale community outreach program aimed at reducing food insecurity and supporting underprivileged communities.\\n\\nThe initiative was based on a simple yet impactful concept: each participating student contributed either 5 kg of rice or 2 kg of dal. These small individual contributions combined to create a substantial collective impact.\\n\\nThe campaign received overwhelming support, with over 2,100 students participating and helping to collect a significant quantity of essential food grains. As part of this effort, I personally donated 2 kg of toor dal, which became part of the overall collection.\\n\\nVolunteers organized the collection, after which the food supplies were systematically distributed to various beneficiary organizations, including mass feeding programs, hostels for visually challenged children, old age homes, hospitals, trust-run schools, and local anganwadis.\\n\\nThe donated rice and dal strengthened ongoing nutrition programs, benefiting children, senior citizens, patients, and economically disadvantaged communities. The distribution process was well-coordinated, with beneficiary institutions collecting the supplies directly from the campus under the supervision of Rotaract and Rotary representatives.","aicteMapping":"Food preservation/packaging","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/bd9b3d9b-d2c9-4bcf-8d5f-e1d22ece9a5c/oKFA6bf79-F2TlhpE8Eb6.jpeg","certificateAttached":true,"detailedReportPageNo":"24-25","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-31 05:00:38.751252+00', '2026-01-31 07:19:56.753293+00'), ('1a49e335-960f-4079-a9ed-5234cbf31ab0', '8ac6fa32-2e14-4591-b960-307120f8d084', '{"student":{"usn":"1RV22CD052","name":"Sarvagya Kumar","period":"2022-2026","department":"Computer Science & Engineering - Data Science","totalPoints":0},"activities":[{"id":"GVuzBxhUBVEwukinHZiAr","name":"Project Pustak 2025","slNo":1,"place":"RVCE, RV Vidyanikethan Post, Mysuru Road, Bengaluru - 560059","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/xJO4CBuygUHnIQilY0-ws.jpg"],"endDate":"2025-04-07","duration":1,"outcomes":"As a result of my contribution, I supported the provision of a stationery kit to one of the 5,500+ children reached through the project this year. I also received a certificate of appreciation from the club, recognizing my involvement and the role my support played in empowering young students through education.","semester":"6","startDate":"2025-04-07","hoursSpent":0,"description":"I contributed to Project Pustak 2025, an initiative led by the Rotaract Club of RVCE focused on supporting underprivileged children with essential educational resources. Through this effort, stationery kits were distributed to children in need, helping reduce basic barriers to learning and improving access to school supplies.","aicteMapping":"Donation","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/VuEWD64caQlS1BFOz8SRO.jpg","certificateAttached":true,"detailedReportPageNo":"2","signatureOfCounsellor":""},{"id":"jmB7zu9s6QAJbSis0pgrw","name":"Contribution to Digital India","slNo":2,"place":"Institute of Wood Science and Technology (IWST), 18th Cross, Malleshwaram, Bangalore (Karnataka) - 560003","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/lPPyiJV5tBhWsSSmUgiMe.jpg"],"endDate":"2023-11-29","duration":15,"outcomes":"Through this contribution, I supported the digital infrastructure of a Government of India research body by applying software development skills in a real research environment. I dedicated approximately 4 weeks (around 200 hours) to the project, exceeding the minimum duration requirement, and my work was formally recognized for technical competence and dedication. This experience reflects my role in contributing to a national-level government research initiative through technology-driven solutions.","semester":"3","startDate":"2023-11-15","hoursSpent":100,"description":"I contributed to a technical project at the Institute of Wood Science & Technology (IWST), Bengaluru, an institute under the Indian Council of Forestry Research & Education (ICFRE), Ministry of Environment, Forest & Climate Change, Government of India. During this period, I worked on the development of a web application related to Indian timber data within the Wood Properties & Processing (WPP) Division. The work focused on building a digital platform to support structured information access and technological enablement in forestry research, aligning with broader national efforts toward digitization in government research systems.","aicteMapping":"Contribution to Digital India","pointsEarned":20,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/IEpVp1zzh8GW2fdHTQqHu.jpg","certificateAttached":true,"detailedReportPageNo":"4","signatureOfCounsellor":""},{"id":"1X-v6kW1GNPIALJwoOv3c","name":"Community Kitchen (Art of Living – YES+ Initiative)","slNo":3,"place":"Art of Living International Center, Ved Vignan Maha Vidya Peeth, 21st Km, Kanakapura Road, Udayapura, Bangalore South, Karnataka - 560082.","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/NVPxdAkc1xFzdG6V8CWxI.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/J-N7zbJy1iWu3aHMpOu2a.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/tL29exSOA-ObCPUd9r6SD.jpeg"],"endDate":"2025-11-25","duration":3,"outcomes":"I learned the importance of community service, teamwork, and responsibility while working in a real service environment. The activity improved my coordination, time management, and ability to work efficiently in a group. It also helped me develop empathy, discipline, and respect for the effort involved in large-scale food preparation and service.","semester":"7","startDate":"2025-11-23","hoursSpent":null,"description":"Volunteered in a Community Kitchen activity conducted under the Art of Living YES+ (Youth Empowerment Seminar) initiative. Responsibilities included serving food, cutting vegetables, assisting in kitchen setup, and cleaning the community kitchen area. The activity focused on service, teamwork, and supporting community welfare.","aicteMapping":"Volunteering","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/M4C0Sao8hTSONCSIj2f4z.png","certificateAttached":true,"detailedReportPageNo":"6","signatureOfCounsellor":""},{"id":"zXgt7OabbwluAgBr9TGX9","name":"Gaushala Volunteer Service (Art of Living – YES+ Initiative)","slNo":4,"place":"Art of Living International Center, Ved Vignan Maha Vidya Peeth, 21st Km, Kanakapura Road, Udayapura, Bangalore South, Karnataka - 560082.","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/61vhT8x3yUSU9U7eGcAeU.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/N_WMpPSCjdlAV1oeYdAP5.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/pikkjLdpDw9n8FyIJCOtw.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/nDaDORnPJXKynrpgL6g08.jpeg"],"endDate":"2025-12-22","duration":3,"outcomes":"I learned the value of compassion, responsibility, and service through direct involvement in animal care. The activity helped me understand the importance of preserving indigenous breeds and maintaining hygiene and discipline in a service environment. It also improved my teamwork, patience, and sense of social responsibility.","semester":"7","startDate":"2025-12-20","hoursSpent":null,"description":"Volunteered in a Gaushala (cow shelter) service activity under the Art of Living YES+ initiative. The work involved supporting the conservation and care of indigenous Indian cows, assisting in maintenance activities, and contributing to the overall upkeep of the shelter. The activity focused on animal welfare, responsibility, and service to the community.","aicteMapping":"Volunteering","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/bKWFltNFo7tx3EsQPRSie.png","certificateAttached":true,"detailedReportPageNo":"9","signatureOfCounsellor":""},{"id":"nXyKqZqI5y87ueY4kCCaO","name":"YES!+ Course – Mental Health Awareness (Har Ghar Dhyan Initiative)","slNo":5,"place":"RVCE Bangalore, RV Vidyanikethan Post, Mysuru Road, Bengaluru - 560059","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/N7hZx05y-5iTmhypg9eE5.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/6T5-bazrWlUXTt_pQUJk1.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/ZKlBp7AFW68cNTCZZHIkB.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/jflwmSlnSSYmacZ9Jgx7y.jpeg"],"endDate":"2025-11-16","duration":4,"outcomes":"I learned techniques for stress management, emotional regulation, and maintaining mental well-being through meditation and mindfulness practices. The course improved my self-awareness, focus, and ability to handle pressure in academic and personal situations. It also increased my understanding of the importance of mental health and holistic development.","semester":"7","startDate":"2025-11-13","hoursSpent":0,"description":"Participated in the Art of Living YES!+ Course conducted under the Har Ghar Dhyan initiative, focusing on mental health awareness and personal well-being. The program included sessions on stress management, meditation practices, emotional balance, and the importance of mental wellness. The course aimed to build self-awareness and promote a healthy lifestyle among youth.","aicteMapping":"Mental Health & Wellness","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/jcacjt5iJizWFzZDhUR0L.png","certificateAttached":true,"detailedReportPageNo":"12","signatureOfCounsellor":""},{"id":"K-VoARAwE46fAi1i9dveK","name":"Horticulture & Plantation Volunteer Service (Art of Living – YES+ Initiative)","slNo":6,"place":"Art of Living International Center, Ved Vignan Maha Vidya Peeth, 21st Km, Kanakapura Road, Udayapura, Bangalore South, Karnataka - 560082.","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/IwY2Qf7xjOuh-E95O-CHg.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/o8-iRaMZLRUHHYAwErSpv.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/JUiQmkArUrGUfFTKBJc5R.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/3DrNkQovI4hhxQlQAl9Qn.jpg"],"endDate":"2025-12-01","duration":3,"outcomes":"I learned the importance of environmental conservation and sustainable practices through hands-on plantation work. The activity improved my sense of responsibility towards nature, patience, and teamwork. It also increased my awareness about the role of greenery in ecological balance and climate well-being.","semester":"7","startDate":"2025-11-29","hoursSpent":null,"description":"Volunteered in a horticulture and plantation activity under the Art of Living YES+ initiative. The work involved nurturing plants and trees, watering, sowing seeds, and supporting plantation efforts. The activity aimed at promoting environmental sustainability and contributing to green campus initiatives.","aicteMapping":"Environment & Sustainability","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/Fp2Qr0H0dDfvWicMU8i9m.png","certificateAttached":true,"detailedReportPageNo":"15","signatureOfCounsellor":""},{"id":"gVy0_YsWJnM2wQX8Vd_fK","name":"Permaculture & Soil Sustainability Awareness (Art of Living – YES+ Initiative)","slNo":7,"place":"Art of Living International Center, Ved Vignan Maha Vidya Peeth, 21st Km, Kanakapura Road, Udayapura, Bangalore South, Karnataka - 560082.","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/Fg1OtAnhIV6z5n3WiMpoi.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/EyhSP-JxAFzdPBYA8fX92.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/PSOuQW_StbELi68trh0h8.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/sCzMLeEF9MWTg7LBg0yhu.jpg"],"endDate":"2025-12-22","duration":3,"outcomes":"I learned about the principles of permaculture, soil conservation, and sustainable farming practices. The activity increased my awareness of the relationship between soil health, food production, and environmental sustainability. It also developed my sense of responsibility towards ecological preservation and long-term resource management.","semester":"7","startDate":"2025-12-20","hoursSpent":0,"description":"Participated in a permaculture-based awareness activity under the Art of Living YES+ initiative. The program focused on understanding soil health, sustainable agricultural practices, and the importance of improving soil quality to enhance agricultural productivity. The activity aimed to promote environmental responsibility and ecological balance through sustainable methods.","aicteMapping":"Environment & Sustainability","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/WoF98n116za1olvHRq-Cy.png","certificateAttached":true,"detailedReportPageNo":"18","signatureOfCounsellor":""},{"id":"HUcwdSvQ_CWhor8M6m1Ks","name":"Cheela Mela – NSS Plastic Awareness Drive","slNo":8,"place":"RVCE Bangalore, RV Vidyanikethan Post, Mysuru Road, Bengaluru - 560059","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/zTv1w_-LZI7TknEei3UNX.png","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/NIOzzuhbmr7-7lxUOPq0x.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/6agWagXl6bwcjDwSy2zs8.jpeg"],"endDate":"2025-11-20","duration":8,"outcomes":"I learned about the environmental impact of plastic waste and the importance of sustainable alternatives. The activity improved my creativity, patience, and sense of responsibility towards environmental conservation. It also enhanced my awareness about practical ways individuals can contribute to reducing pollution and promoting eco-friendly practices.","semester":"7","startDate":"2025-11-13","hoursSpent":0,"description":"Participated in a Paper Bag Making Workshop organized by NSS RVCE in collaboration with EMPRI as part of a plastic waste awareness drive at the Kadale Kayi Parishe. I prepared 250 eco-friendly paper bags using newspapers to promote reduction of single-use plastic. The activity aimed at encouraging sustainable alternatives and spreading awareness about environmental protection.","aicteMapping":"Environment & Sustainability","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/Q4qlH80C4AFkAsaNymcKe.jpg","certificateAttached":true,"detailedReportPageNo":"21","signatureOfCounsellor":""},{"id":"maXWBTpq_NJcz2aKp46c5","name":"FISTFUL Food Grain Donation Drive – Community Service Initiative","slNo":9,"place":"RVCE Bangalore, RV Vidyanikethan Post, Mysuru Road, Bengaluru - 560059","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/ZIbsUvYtwrs1XJfTy9DbF.jpg"],"endDate":"2025-11-21","duration":5,"outcomes":"I learned how small individual contributions can collectively create a large social impact. The activity increased my awareness about food insecurity and the importance of supporting community health and care institutions. It strengthened my sense of social responsibility and encouraged me to participate in meaningful service initiatives.","semester":"7","startDate":"2025-11-17","hoursSpent":0,"description":"Participated in the FISTFUL community service initiative supported by Rotary Bangalore Spandana to address food insecurity. As part of the drive, I personally donated 3 kg of toor dal. The collected food grains were distributed to institutions providing daily meals to children, elderly people, patients, and other vulnerable groups.","aicteMapping":"Social Outreach","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/8ac6fa32-2e14-4591-b960-307120f8d084/t0-opdyyV6fHi5Dw4pKNj.jpg","certificateAttached":true,"detailedReportPageNo":"24","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-02-01 06:57:28.980578+00', '2026-02-01 06:57:29.989221+00'), ('1af7abc3-fee1-4127-88bc-33ccba2db5d4', '65d73c17-34fc-4e70-a182-5d44b46b5974', '{"student":{"usn":"1RV22CS209","name":"Suhas Raj HR","period":"2022-2026","department":"Computer Science & Engineering","totalPoints":0},"activities":[{"id":"_p6BdlSHVFLi5iXdHroQ0","name":"Project Pustak","slNo":1,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/E8yzem5UHFEdchnaUPAAB.jpeg"],"endDate":"2023-05-13","duration":2,"outcomes":"Education is the key to unlocking opportunities and building a better future. Unfortunately,\\nmany\\nchildren in rural areas lack access to basic school supplies, making it difficult for them to learn\\nand grow. Project Pustak aims to bridge this gap and help these children realize their potential.","semester":"1","startDate":"2023-05-12","hoursSpent":1,"description":"Project Pustak is a noble initiative that aims to provide essential school supplies to\\nunderprivileged students in rural areas. With the generous donations, notebooks and geometry\\nboxes will be brought, which will be donated to government schools. ","aicteMapping":"Social Service","pointsEarned":3,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/p4IvVHChdMkxGHMAutaNx.jpeg","certificateAttached":true,"detailedReportPageNo":"1-2","signatureOfCounsellor":""},{"id":"FE_nEjhb40fv9wim6Faee","name":"Utsarga Marathon","slNo":2,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/w6pYdG1OBMi23D20-cg3h.jpeg"],"endDate":"2023-06-04","duration":1,"outcomes":"Don''t Just Run; Be the Change!\\nThis is more than a marathon; it''s a MOVEMENT! Let''s spread the word, rally your squad, and\\nrun for a cause! Together, we light up the path to a brighter tomorrow. #NOTMEBUTYOU","semester":"2","startDate":"2023-06-04","hoursSpent":6,"description":"This isn''t your average run—it''s a celebration of vitality, wellness, and, most importantly, an\\nopportunity to make a real impact. Your run isn''t just a jog; it''s a promise to reshape a child''s\\ndestiny. The theme, ''Help a Child Change the World,'' is our social heartbeat, and every stride\\nyou take directly fuels for those in need.\\n","aicteMapping":"Community Development","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/3DkL1XPToImNXAm99Hw-l.jpeg","certificateAttached":true,"detailedReportPageNo":"3-4","signatureOfCounsellor":""},{"id":"ZvesyTK5gOdC8WCRSsdS1","name":"Blood Donation Camp","slNo":3,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/xBoUg0KLQIgXWDkPxp1Dc.jpeg"],"endDate":"2023-06-06","duration":1,"outcomes":"My blood group is AB+ and it has:\\nAbility to receive blood from A, B, AB, and O blood types (specifically for AB+).\\n\\nPresence of both A and B antigens.\\n\\nAbsence of anti-A and anti-B antibodies.","semester":"2","startDate":"2023-06-06","hoursSpent":3,"description":"Donated my blood to the blood bank for a social cause. Every drop counts — one pint of blood\\ncan save up to three lives. This was our chance to give someone a second chance at life, right\\nhere on campus.","aicteMapping":"Social Service","pointsEarned":6,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/vFPxhq8HAwL1JnhbrXkVg.jpeg","certificateAttached":true,"detailedReportPageNo":"5-6","signatureOfCounsellor":""},{"id":"sqg_SBUM2ltKWwjc2P95e","name":"Akshara","slNo":4,"place":"Kengeri Vidyalaya","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/OVboVCdvpPjFI27LiHyz1.jpeg"],"endDate":"2023-06-10","duration":1,"outcomes":"It helps the rural students to upskill and learn well for their betterment and future and also helps us interacting with various students and understanding about their curious minds.","semester":"2","startDate":"2023-06-10","hoursSpent":8,"description":"Akshara is dedicated to sparking the curiosity of young minds in Mathematics, Literature and Science  . The participants will be taken to schools where they will impart knowledge and wisdom to the children. ","aicteMapping":"Skilling Rural Population","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/kQS7mZLUgIi9QAygyx3yL.jpeg","certificateAttached":true,"detailedReportPageNo":"7-8","signatureOfCounsellor":""},{"id":"VsAh1CsxokhZz5ZwgTRQz","name":"Plantation Drive","slNo":5,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/dKhGKoP_CxPlq03oovT6p.jpeg"],"endDate":"2023-07-12","duration":2,"outcomes":"Let''s foster a greener environment together, one student and one plant at a time!","semester":"2","startDate":"2023-07-11","hoursSpent":3,"description":"1. Get yourself a plant! Choose any indoor plant that resonates with you. It could be a small\\nsucculent, a leafy houseplant, or even a herb for your windowsill garden. Find a plant that\\nmatches your space and personal preferences.\\n2. Take a picture with your plant! Once you have your plant, snap a photo of yourself with it.\\nShow off your green companion and let your creativity shine.\\n3. Submit your entry\\n","aicteMapping":"Social Service","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/vAXhgCZlkRbJaa553TiqK.jpeg","certificateAttached":true,"detailedReportPageNo":"9-10","signatureOfCounsellor":""},{"id":"QTJGJsS00Q_EEcUq0h5O4","name":"Utsarga Marathon","slNo":6,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/XBB_wUGJix0bzxk1qR0RJ.jpeg"],"endDate":"2024-02-04","duration":1,"outcomes":"Don''t Just Run; Be the Change!\\nThis is more than a marathon; it''s a MOVEMENT! Let''s spread the word, rally your squad, and\\nrun for a cause! Together, we light up the path to a brighter tomorrow. #NOTMEBUTYOU","semester":"3","startDate":"2024-02-04","hoursSpent":6,"description":"This isn''t your average run—it''s a celebration of vitality, wellness, and, most importantly, an\\nopportunity to make a real impact. Your run isn''t just a jog; it''s a promise to reshape a child''s\\ndestiny. The theme, ''Help a Child Change the World,'' is our social heartbeat, and every stride\\nyou take directly fuels for those in need.\\n","aicteMapping":"Community Development","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/texJnT5_3lb6MkBju3GVZ.jpeg","certificateAttached":true,"detailedReportPageNo":"11-12","signatureOfCounsellor":""},{"id":"I2YCDLktvGNQ_xSMqvBsI","name":"Blood Donation Camp","slNo":7,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/bTovPVZ7SO5r-dkDA87w6.jpeg"],"endDate":"2024-06-28","duration":1,"outcomes":"My blood group is AB+ and it has:\\nAbility to receive blood from A, B, AB, and O blood types (specifically for AB+).\\n\\nPresence of both A and B antigens.\\n\\nAbsence of anti-A and anti-B antibodies.","semester":"4","startDate":"2024-06-28","hoursSpent":3,"description":"Donated my blood to the blood bank for a social cause. Every drop counts — one pint of blood\\ncan save up to three lives. This was our chance to give someone a second chance at life, right\\nhere on campus.\\n","aicteMapping":"Social Service","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/2DKCjyV2STS037YUxQrsd.jpeg","certificateAttached":true,"detailedReportPageNo":"13-14","signatureOfCounsellor":""},{"id":"6QZ--YsRDWhwuvIY4fTCo","name":"Cheela Mela Paper Bag Workshop","slNo":8,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/DRYaakQ72c72hWkRmHOIB.jpeg"],"endDate":"2025-11-22","duration":377,"outcomes":"Go green by creating newspaper bags and contribute towards a sustainable environment!","semester":"5","startDate":"2024-11-11","hoursSpent":24,"description":"NSS RVCE, in collaboration with Youth For Seva, is organizing a paper bag workshop for the\\nKadale Kayi Parishe.","aicteMapping":"Social Service","pointsEarned":20,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/MiWhUuqS18wqcM7z8GwtX.jpeg","certificateAttached":true,"detailedReportPageNo":"15-16","signatureOfCounsellor":""},{"id":"GXtzzj_3DHmvg1GwFaP-0","name":"Fistfull","slNo":9,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/CqZTiXesRMBNhqMONmXd_.jpeg"],"endDate":"2024-11-29","duration":15,"outcomes":"In this initiative by the Rotaract Club of RVCE in collaboration with Rotary Bangalore\\nSpandana, students were encouraged to donate 5 kg of rice or 2 kg of toor daal, with daily\\ncollections in the Civil Department. The drive garnered an overwhelming response with the total\\namount of 6,700+ kg of rice and 800+ kg of toor dal donated by 1750+ students. This initiative\\nhighlighted the power of small efforts to drive significant societal change, reinforcing RVCE''s\\ndedication to community welfare and solidarity","semester":"5","startDate":"2024-11-15","hoursSpent":5,"description":"A fistful of kindness can fill a heart and feed a soul. For every meal we prepare from November\\n15th to November 29th, set aside a fistful of rice or toor dal. By the end of the event, we''ll have\\ngathered enough to bring a smile to someone in need!\\n","aicteMapping":"Social Service","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/45VxYWhiybvfRPWpgqwLY.jpeg","certificateAttached":true,"detailedReportPageNo":"17-18","signatureOfCounsellor":""},{"id":"x4oqDwYG_rb6ZCaNaP5k2","name":"Eyes Of Youth","slNo":10,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/wTMtTZnaPjyKANWg1lkvz.jpeg"],"endDate":"2024-12-18","duration":1,"outcomes":"We got a chance to show what the world looks like to us and also a chance to win a prize pool\\nof 3500.\\n","semester":"5","startDate":"2024-12-18","hoursSpent":2,"description":"All the photographs must be original work.\\nSubmissions must align with only one of the 17 UN SDGs.\\nIndicate the SDG number with the logo linked to the photo and write a brief story/description\\n(between 100-\\n150 words) explaining how the photo is linked to the respective SDG.\\nEach participant can submit one entry only.\\nOnly minimal editing is allowed.\\nThe top 25 shortlisted submissions (after the plagiarism Image check and relevance check) will\\nbe uploaded\\non the official Instagram page of SPARK.\\nThe submissions that receive the most likes (genuine) by the audience as of 18 December 2024\\nat 23:59 will be\\nconsidered winners.\\n","aicteMapping":"Sustainable Development Goals","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/nM3hbP2ALmyUeNXvJ6O8E.jpeg","certificateAttached":true,"detailedReportPageNo":"19-20","signatureOfCounsellor":""},{"id":"Uh2MzBfIuLmDLVL6Dd9JU","name":"Utsarga Marathon","slNo":11,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/DlCRFolbyM4cqItWEoHYC.jpeg"],"endDate":"2025-04-06","duration":1,"outcomes":"Our contribution helped us participate in this meaningful initiative. Our involvement\\nsignificantly contributed to the success of this cause.\\n","semester":"6","startDate":"2025-04-06","hoursSpent":6,"description":"This marathon is dedicated to the cause of \"Help a Child, Change the World.\" This initiative\\naims to support underprivileged children through education, healthcare, and welfare programs.","aicteMapping":"Community Development","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/cy0frCv8IezS1ILBJUOWY.jpeg","certificateAttached":true,"detailedReportPageNo":"21-22","signatureOfCounsellor":""},{"id":"jisoHNKOiAF7zp9_us6cO","name":"Blood Donation Camp","slNo":12,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/5N_IqJUSCDfyGitWGhiz6.jpeg"],"endDate":"2025-10-30","duration":1,"outcomes":"My blood group is AB+ and it has:\\nAbility to receive blood from A, B, AB, and O blood types (specifically for AB+).\\n\\nPresence of both A and B antigens.\\n\\nAbsence of anti-A and anti-B antibodies.","semester":"7","startDate":"2025-10-30","hoursSpent":3,"description":"Donated my blood to the blood bank for a social cause. Every drop counts — one pint of blood\\ncan save up to three lives. This was our chance to give someone a second chance at life, right\\nhere on campus.\\n","aicteMapping":"Social Service","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/65d73c17-34fc-4e70-a182-5d44b46b5974/aAUR3P_tNc4vAKiUh2Lar.jpeg","certificateAttached":true,"detailedReportPageNo":"23-24","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-30 06:53:20.08604+00', '2026-01-30 07:06:43.517554+00'), ('1b190542-22d7-452d-8ff0-4dbe51fb4275', 'aa54c5fc-1678-4d4f-bea7-89f8506738b7', '{"student":{"usn":"","name":"","period":"2022-2026","department":"","totalPoints":0},"activities":[],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-29 18:27:42.895205+00', '2026-01-29 18:27:43.805381+00'), ('1bb62852-3cf9-4e1c-a089-c9903f4265fa', '3e26df13-6690-434a-90d2-1ead38b48677', '{"student":{"usn":"1RV22BT010","name":"Bazilla Wani","period":"2022-2026","department":"Biotechnology","totalPoints":0},"activities":[{"id":"dKrIKluORj2348pxiW7CH","name":"Fast-Trek","slNo":1,"place":"Huthridurga Hills, Karnataka ","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/31VsEbbuPeJOQMQn8jLq4.png","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/AKl3pezM5k_h0HyULyeY4.png"],"endDate":"","duration":1,"outcomes":"The trek was a resounding success, creating unforgettable memories for all while advancing our mission to provide life-saving financial support for vulnerable children with heart diseases. It fostered strong camaraderie, high participant satisfaction, and meaningful progress toward the charity goal.","semester":"1","startDate":"2023-02-12","hoursSpent":0,"description":"On a vibrant morning, our team organized a charity trek to Huthridurga Betta, driven by a heartfelt social cause: raising financial aid for underprivileged children battling heart diseases. The event kicked off at 7:30 AM as enthusiastic participants boarded the bus to the trek site, buzzing with excitement. En route, we shared essential safety instructions and event details to ensure everyone was prepared. Participants then conquered the scenic hills, enjoying complimentary breakfast and lunch at the summit amid stunning natural surroundings.","aicteMapping":"Economic and Community Development","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/U0sDQvQOhiJVZwRk8ABcI.jpeg","certificateAttached":true,"detailedReportPageNo":"1-2","signatureOfCounsellor":""},{"id":"bVNHfdudZNH9-ev1ST82f","name":"Gandhain Principles (Essay Writing)","slNo":1,"place":"RVCE Campus","photos":[],"endDate":"","duration":1,"outcomes":"The essay writing competition successfully enhanced students'' awareness and understanding of Gandhian principles and their relevance to contemporary social challenges. Participants developed their literary and analytical skills through articulating complex philosophical concepts while demonstrating enthusiastic engagement across various disciplines. The event effectively fulfilled AICTE guidelines under the Community Development category, promoting value-based education and fostering a sense of social responsibility among engineering students at RVCE.","semester":"3","startDate":"2024-12-09","hoursSpent":0,"description":"The National Service Scheme (NSS) unit of RV College of Engineering (RVCE) organized an Essay Writing Competition on Gandhian Principles on 9th December 2024 at the Department of Civil Engineering, RV Campus. This event was conducted as part of the Community Development activities under the AICTE guidelines.\\nThe competition aimed to encourage students to reflect upon and articulate Mahatma Gandhi''s timeless principles of truth, non-violence, self-reliance, and social justice. Through this literary initiative, students were provided with a platform to express their understanding of Gandhian philosophy and its relevance in contemporary society. The event emphasized the importance of ethical values, moral responsibility, and community service—core tenets of both Gandhian ideology and the NSS mission.\\nParticipants were invited to write essays on various themes related to Gandhi''s teachings, including Satyagraha, Ahimsa, Swaraj, Swadeshi, communal harmony, rural development, and sustainable living. The competition fostered critical thinking, creative expression, and a deeper appreciation for the Father of the Nation''s contributions to India''s freedom struggle and nation-building.\\nThe Civil Department provided the venue and necessary infrastructure support, facilitating a conducive environment for students to engage meaningfully with Gandhian ideals through written expression.","aicteMapping":"Community Development","pointsEarned":2,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/W5Jv3VmpZ5Sx-GB_uOln-.jpeg","certificateAttached":true,"detailedReportPageNo":"3-4","signatureOfCounsellor":""},{"id":"0x0r8i_whmNwm2FLPjGAT","name":"Fast-Trek 2.0","slNo":2,"place":"Kunagalu Betta Hills","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/JmynD0zrMtM2gLjClKjRR.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/A5SE8zZtBDhBUrq7KW_tV.jpeg"],"endDate":"","duration":0,"outcomes":"The Fast-Trek event successfully engaged over 750 individuals in an enriching trekking experience, fostering environmental awareness and social responsibility among participants. The cleanliness drive during the trek contributed to preserving the natural beauty of Kunagalu Betta Hills while promoting eco-conscious behavior among students. The event strengthened community bonds, encouraged physical fitness and outdoor activities, and created a vibrant atmosphere of enthusiasm and collective participation, demonstrating the Rotaract Club''s commitment to combining adventure with meaningful social causes.","semester":"3","startDate":"2024-01-28","hoursSpent":0,"description":"The Rotaract Club of RVCE conducted its flagship event Fast-Trek on 28th January 2024, which witnessed active participation from college students. The social cause behind the project was a cleanliness drive during the trek, dedicated to preserving the environment.\\nCommencing at 7:30 AM, participants eagerly boarded the bus to the trekking site, brimming with enthusiasm for the day ahead. Prior to embarking on the adventure, comprehensive safety instructions and event particulars were disseminated to all attendees. The trek traversed the picturesque Kunagalu Betta Hills, unfolding as a resounding success and offering participants a memorable journey amidst breathtaking landscapes. The event combined adventure, environmental consciousness, and community engagement, providing students with an opportunity to connect with nature while contributing to its preservation.","aicteMapping":"Economic and Community Development","pointsEarned":12,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/8jAhjHiVi72INtQnfjXUD.jpeg","certificateAttached":true,"detailedReportPageNo":"5-6","signatureOfCounsellor":""},{"id":"WY9jskiYa-uXMXQG2DURY","name":"Akshara","slNo":3,"place":"Bangalore Schools","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/GDF_G7OE9RmQgbXM0KI1v.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/8P3IyAocEO2KltA7U-1cw.jpeg"],"endDate":"","duration":0,"outcomes":"The AKSHARA initiative successfully impacted over 1000 underprivileged students across eight schools, enhancing their academic understanding and essential skill sets through interactive learning methods. Volunteers from RVCE gained valuable teaching experience and developed a deeper appreciation for the profession while addressing educational inequalities in society. The project effectively demonstrated the power of volunteerism in bridging educational gaps and underscored the critical need for quality education accessibility for all sections of society, fulfilling the Rotaract Club''s commitment to community development and social responsibility.","semester":"4","startDate":"2024-06-08","hoursSpent":0,"description":"The Rotaract Club of RVCE conducted AKSHARA, a skill development initiative on 8th June 2024, reaching out to eight Bangalore schools and benefiting over 1000 underprivileged students. Targeting financially modest backgrounds, the sessions were designed to enhance academic understanding and provide essential skills to students who lack access to quality educational resources.\\nThe schools visited included BET Convent, Sai Sri Vidya Chethana, Vishwa Bharathi High School, Kengeri High School, Government Model Primary School, Nehru Memorial School, Priyadarshini Vidhya Kendra School, and Mount Carmel English School. The initiative employed interactive and innovative methods with curriculum-based learning to ensure relevance and active student engagement. Volunteer participants from RVCE gained valuable hands-on experience as teachers, fostering appreciation for the teaching profession while addressing critical educational disparities in underprivileged communities.","aicteMapping":"Educational Outreach","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/RhS4_VubWHOt0rIHsvphS.jpeg","certificateAttached":true,"detailedReportPageNo":"7-8","signatureOfCounsellor":""},{"id":"QS-J1ETzD4yad52y5-Mg7","name":"Paper Drive","slNo":5,"place":"Bengaluru","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/zo3t6wc-f4WxmE9P4A-E1.jpeg"],"endDate":"","duration":0,"outcomes":"The Paper Drive was a resounding success, with over 400 student volunteers actively participating in the collection drive across Bangalore. The event resulted in a significant collection of books, papers, and waste materials that were channeled to charities and NGOs to support their social initiatives. Beyond resource collection, the drive successfully raised community awareness about recycling, environmental conservation, and the importance of community involvement in addressing social issues. The initiative fostered a strong sense of social responsibility among participants and Bangalore residents, demonstrating the power of collective student engagement in creating meaningful social impact and promoting sustainable practices in the community.","semester":"4","startDate":"2024-06-23","hoursSpent":0,"description":"On 23rd June 2024, the Rotaract Club of RVCE organized the \"Paper Drive,\" engaging over 400 student volunteers to collect books, papers, and waste materials across various areas of Bangalore. The students started early in the morning, going door-to-door and visiting businesses to gather donations.\\nThe initiative aimed to collect recyclable materials to support charities and NGOs in their efforts to assist people in need. Volunteers spread across different localities of Bangalore, educating residents about the importance of recycling and resource conservation while collecting substantial quantities of paper and reading materials. The collected materials were intended to help charitable organizations and NGOs support their initiatives, particularly in areas of education and environmental sustainability.","aicteMapping":"Social Cause","pointsEarned":12,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/hQrKy334JT-Fz8Nq3w6L_.jpeg","certificateAttached":true,"detailedReportPageNo":"9-10","signatureOfCounsellor":""},{"id":"AGQ-oeu1oh2xGajibIdxE","name":"QUIEEEZ Fest","slNo":6,"place":"ETE Seminar Hall","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/d2sSE9keGwIUxPWp49oQE.jpeg","https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/YhvP_BsaDdbBRLHT4kxpG.jpeg"],"endDate":"","duration":0,"outcomes":"The QU-IEEE-Z FEST successfully engaged students in an intellectually stimulating quiz competition, fostering technical knowledge, critical thinking, and teamwork skills. The event provided a competitive platform for students to test their understanding across multiple domains while promoting healthy academic competition. Participants enhanced their problem-solving abilities and gained exposure to diverse technical concepts through the multi-round quiz format. The event strengthened the IEEE SPS Student Chapter''s presence on campus and encouraged greater student participation in technical society activities, contributing to the overall academic and co-curricular development of the engineering student community.","semester":"4","startDate":"2024-09-07","hoursSpent":0,"description":"The IEEE SPS RVCE Student Chapter organized \"QU-IEEE-Z FEST\" on 7th July 2024 at the MTE Seminar Hall, RV Campus. Branded as \"The Ultimate Quiz Mania,\" this technical quiz competition was designed to test participants'' knowledge across various domains of engineering, technology, and general awareness. The event was open to all students with team sizes of 2-3 members and an entry fee of ₹150 per team.\\nThe fest featured up to 5 activity rounds, challenging participants with diverse questions and problem-solving tasks. With a prize pool worth ₹3,000, the competition attracted enthusiastic participation from students eager to showcase their technical acumen and collaborative skills. The event was coordinated by faculty advisor Dr. Nagamani K and student organizers Yuvraj Singh, Abhitosh Anand, Atharva S Kulkarni, and Ayush Raj. Attendance certificates and 5 activity points were provided to all participants, encouraging active involvement in co-curricular activities.","aicteMapping":" Technical Activities","pointsEarned":3,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/aAZVXY9WQN74EsQVRUeFv.jpeg","certificateAttached":true,"detailedReportPageNo":"11-12","signatureOfCounsellor":""},{"id":"dlY8SM38qYOE3u8D68ItW","name":"Project Pustak","slNo":7,"place":"Bengaluru","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/c0vIVUm82BsPjovMUBfh6.jpeg"],"endDate":"2024-08-06","duration":75,"outcomes":"Project Pustak successfully provided essential school supplies to underprivileged students across rural areas of Devanahalli and Bidadi, Karnataka, creating a more conducive learning environment for children who lacked access to basic educational materials. The initiative, which raised funds through donor contributions, enabled the distribution of textbooks, stationery, and backpacks, directly addressing educational disparities in rural communities. The project gained widespread media recognition for its transformative impact in empowering underprivileged children and enhancing their educational opportunities. Through active involvement of faculty members and student volunteers, the initiative demonstrated the power of collaborative community service in bridging educational gaps and fostering a sense of social responsibility among participants while making a tangible difference in the lives of rural students.","semester":"5","startDate":"","hoursSpent":0,"description":"Project Pustak, led by the Rotaract Club of RVCE in partnership with the Pranav Foundation, was conducted from 24th May to 6th August 2024. This inspiring initiative was dedicated to equipping underprivileged students in rural areas of Devanahalli and Bidadi, Karnataka, with essential school supplies to foster a conducive learning environment.\\nFunds totaling ₹100 or ₹350 were raised through generous contributions from donors. The project was executed in two phases across Devanahalli and Bidadi, where faculty members and student volunteers actively participated in distributing educational materials including textbooks, stationery, and backpacks to students in need. The initiative addressed the critical gap in educational resources faced by children in rural areas, ensuring they had access to the basic materials necessary for effective learning.\\nThe project gained significant media recognition for its impactful role in fostering education in underserved rural communities, highlighting the collaborative efforts between the Rotaract Club and Pranav Foundation in creating meaningful educational opportunities for disadvantaged students.","aicteMapping":"Social Cause","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/4WYeCHOzPOVCPdBw8tOWk.jpeg","certificateAttached":true,"detailedReportPageNo":"13-14","signatureOfCounsellor":""},{"id":"fmcUsqWoe2wlyfL7RWFK3","name":"Plog Run Along Vrishavathi Valley","slNo":8,"place":"Bengaluru","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/s68hkb2KiE2rW7AtI8rgn.jpeg"],"endDate":"","duration":0,"outcomes":"The Plog Run successfully engaged students in a unique blend of fitness and environmental conservation, resulting in the collection of substantial amounts of litter from the Vrishabhavathi Valley area. Participants developed heightened environmental awareness and a deeper understanding of the impact of pollution on local ecosystems and water bodies. The event promoted healthy lifestyle habits while instilling a sense of civic responsibility and environmental stewardship among students. Through this hands-on initiative, the NSS Club effectively demonstrated how individual efforts in community service can create tangible environmental improvements, fostering a culture of sustainability and active citizenship among the student community at RVCE.","semester":"5","startDate":"2024-12-06","hoursSpent":0,"description":"The National Service Scheme (NSS) Club of RVCE organized a Plog Run along Vrishabhavathi Valley on 6th December 2024. This innovative event combined jogging with environmental conservation by engaging participants in picking up litter while running, promoting both physical fitness and ecological responsibility.\\nThe plog run took place along the scenic Vrishabhavathi Valley, where participants actively collected plastic waste, bottles, and other pollutants that had accumulated in the area. The activity aimed to raise awareness about environmental pollution, particularly the degradation of water bodies and surrounding ecosystems. Students enthusiastically participated in this dual-purpose initiative, which fostered a sense of environmental stewardship while encouraging healthy lifestyle practices. The event emphasized the importance of individual action in addressing environmental challenges and demonstrated how simple activities can contribute to significant positive change in local communities and natural habitats.","aicteMapping":"Social Cause","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/4n0kRybL2aXjjaZlA5lOm.jpeg","certificateAttached":true,"detailedReportPageNo":"15-16","signatureOfCounsellor":""},{"id":"BltQliaiB-kyqEGwac3YS","name":"Police Marshal ","slNo":9,"place":"IEM Auditorium","photos":[],"endDate":"","duration":0,"outcomes":"The Police Marshals Launch successfully created widespread awareness about cyber crime and drug abuse dangers among RVCE students. Selected NSS volunteers were appointed as Police Marshals to serve as change agents within the college and community. The collaboration with Bengaluru City Police established a strong partnership for ongoing prevention initiatives. Students gained critical knowledge about preventing cyber frauds and drug abuse while fostering social responsibility. The NSS website launch provided a platform for sustained engagement and awareness beyond the event.","semester":"5","startDate":"2024-12-18","hoursSpent":0,"description":"The National Service Scheme (NSS) of RV College of Engineering, in collaboration with Bengaluru City Police and Aarohan, organized the Police Marshals Launch program on 18th December 2024 from 11:30 AM to 2:00 PM at the IEM Auditorium, RVCE. This inspiring initiative aimed to prevent cyber crime, combat drug abuse, and build a responsible society among students and youth.\\nThe event featured a comprehensive schedule with an invocation dance, welcome address by NSS Programme Officer Dr. M. Lokeshwari, and detailed presentations on drug abuse and cyber crime awareness. Distinguished guests included Assistant Commissioner of Police Mr. Basavaraj A Teli and Deputy Commissioner of Police Mr. Girish S IPS, who delivered impactful speeches on rising cyber crimes and drug abuse concerns. Principal Dr. K N Subramanya addressed the gathering, emphasizing the institution''s commitment to social responsibility. The program included powerful awareness performances: a mime show \"Ganja Hodibeda,\" an English skit \"Awareness Saves Life,\" and a Kannada skit \"Scam Guru Scam.\" The highlight was the Police Marshals Capping Ceremony where selected NSS volunteers were appointed as ambassadors against cyber crime and drug abuse, followed by the NSS Website Launch and oath-taking ceremony.","aicteMapping":"Social Cause","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/zYPvXY_3oThArqOR74wAh.jpeg","certificateAttached":true,"detailedReportPageNo":"17-18","signatureOfCounsellor":""},{"id":"RiDmOuviKWR9poFO30z-L","name":"Utsarga Marathon","slNo":10,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/yHvb_3BiHwhY_QZfw-Sh_.jpeg"],"endDate":"","duration":0,"outcomes":"The Utsarga Marathon was successfully executed with effective coordination from NSS RVCE volunteers who managed certifications and registrations efficiently. Volunteers gained practical experience in event management, logistics coordination, and participant engagement while contributing to a community health initiative. The event promoted physical fitness and wellness awareness among participants and the broader community. NSS volunteers demonstrated strong organizational capabilities and teamwork, ensuring smooth registration processes and timely certification distribution. The initiative strengthened the NSS unit''s commitment to community development while providing students with valuable co-curricular learning opportunities in service and leadership.","semester":"6","startDate":"2025-04-06","hoursSpent":0,"description":"The National Service Scheme (NSS) of RVCE organized volunteers for the Utsarga Marathon on 6th April 2025, categorized under Community Development. This event mobilized NSS volunteers to support the successful execution of a large-scale marathon aimed at promoting health, fitness, and community engagement.\\nNSS volunteers played crucial roles in the event''s logistics, primarily handling certifications and registrations for marathon participants. The core organizing team of 16 volunteers earned 20 activity points each for their extensive involvement in planning and execution, while additional volunteer support team members earned activity points ranging from 7-15 points based on their level of participation. Volunteers were responsible for managing participant registration processes, ensuring smooth check-in procedures, distributing runner kits, and handling post-marathon certification distribution. This hands-on experience provided students with valuable exposure to large-scale event management, crowd coordination, and community service. The marathon served as a platform to promote physical wellness and healthy lifestyle habits within the community while fostering teamwork and organizational skills among NSS volunteers.","aicteMapping":"Run for a Social Cause ","pointsEarned":7,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/byLd8QijwW_QUHnsdvHpJ.jpeg","certificateAttached":true,"detailedReportPageNo":"19-20","signatureOfCounsellor":""},{"id":"QVJQP4zm3LirCWSB0idN4","name":"Uptown Junk","slNo":11,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/i7z0M0_p3HnBBVFHUIHP0.jpeg"],"endDate":"","duration":0,"outcomes":"Uptown Junk successfully engaged over 400 students in hands-on recycling and creative reuse activities, effectively promoting environmental sustainability through practical application. The event significantly enhanced participants'' awareness of waste management issues and the importance of recycling in reducing environmental impact. Students developed innovative thinking and problem-solving skills by transforming junk materials into creative, useful products. The collaborative team-based format fostered teamwork, communication, and social responsibility among participants. The event successfully demonstrated that sustainability can be both educational and entertaining, inspiring students to adopt eco-friendly practices in their daily lives and contributing to the broader goal of building an environmentally conscious student community at RVCE.","semester":"6","startDate":"","hoursSpent":0,"description":"The Rotaract Club of RVCE organized Uptown Junk on 21st April 2025, an innovative environmental awareness event that witnessed the participation of over 400 students. The event focused on promoting recycling and creative reuse through engaging and interactive activities that encouraged environmental consciousness and responsible waste management practices.\\nThe event featured a unique format combining a treasure hunt with a \"Best Out of Waste\" competition, where junk materials were auctioned using creative \"Rota Money\" currency. Participants formed teams and purchased recyclable materials through the auction system, which they then utilized to design innovative models and creative products. These creations were later evaluated by judges based on criteria including creativity, presentation quality, and practical utility. The competitive yet collaborative format challenged students to think innovatively while working together, transforming discarded materials into useful and aesthetically appealing products. The hands-on approach provided students with practical experience in upcycling and demonstrated how waste materials could be given new life through creative thinking and sustainable practices.","aicteMapping":"Environment & Sustainability / Creative  Innovation ","pointsEarned":4,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/NQVcftBcwpCd4tmRMW1I_.jpeg","certificateAttached":true,"detailedReportPageNo":"21-22","signatureOfCounsellor":""},{"id":"VSNDrx1N0gfeA7_UBnY3N","name":"Design and Literary ","slNo":12,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/j2IKG8eGKlupaSGzSXdhW.jpeg"],"endDate":"","duration":0,"outcomes":"The Literary Team successfully supported all Rotaract Club activities throughout the year through effective documentation and communication efforts. Team members developed strong writing, editing, and content creation skills while contributing to the club''s visibility and outreach. The team ensured comprehensive documentation of all events and initiatives, creating a valuable archive of the club''s activities and impact. Participants enhanced their creative thinking, time management, and collaborative skills while working on diverse literary projects. The team''s efforts strengthened the club''s communication strategy and helped build a strong organizational identity. Members gained practical experience in professional writing, digital content creation, and media management, which contributed to their overall personal and professional development.","semester":"4","startDate":"","hoursSpent":0,"description":"Literary Team of the Rotaract Club of RVCE served as a year-round initiative where student volunteers contributed to various literary and documentation activities throughout the academic year. Team members worked for varying durations ranging from 1 to 12 months, contributing to the club''s communication, content creation, and documentation efforts.\\nThe Literary Team was responsible for creating engaging content for Rotaract events, managing social media communications, designing promotional materials, writing event reports and articles, maintaining official documentation, and ensuring effective outreach through written content. Team members developed their writing, editing, and creative communication skills while supporting the club''s various community development and social service initiatives. The team played a crucial role in documenting the club''s activities, maintaining records, creating awareness about events, and ensuring effective communication with stakeholders. Members worked collaboratively to produce high-quality content that reflected the club''s values and mission while enhancing their own literary and professional communication abilities.","aicteMapping":"Student Club Activities","pointsEarned":8,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/zUbvbtXRG1WN6TWOmX6SC.jpeg","certificateAttached":true,"detailedReportPageNo":"23-24","signatureOfCounsellor":""},{"id":"dhP3knnA5u-Ns5A277R9w","name":"Blood Donation Camp","slNo":13,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/Hh450VIW1St4rnCCI5ZpG.jpeg"],"endDate":"","duration":0,"outcomes":"The BDC 2024 successfully collected blood donations that would potentially save numerous lives, addressing critical blood supply needs in healthcare facilities. Over 40 volunteers gained valuable experience in event management, healthcare coordination, and community service while demonstrating strong organizational and interpersonal skills. The camp raised significant awareness about voluntary blood donation and its life-saving importance within the RVCE community. Participants developed a sense of social responsibility and empathy while contributing to a humanitarian cause. The event strengthened the Rotaract Club''s commitment to health and welfare initiatives and fostered a culture of voluntary service among students, creating lasting impact beyond the immediate blood collection.","semester":"4","startDate":"2024-06-28","hoursSpent":0,"description":"The Rotaract Club of RVCE organized a Blood Donation Camp (BDC) on 28th June 2024, mobilizing a dedicated team of over 40 student volunteers to facilitate this life-saving initiative. The event aimed to address the critical need for blood supplies in hospitals and blood banks while creating awareness about voluntary blood donation among the college community.\\nVolunteers played essential roles in coordinating various aspects of the camp including donor registration, managing donor queues, assisting medical staff, providing refreshments to donors, maintaining records, and ensuring smooth operations throughout the event. The team worked collaboratively to create a comfortable and efficient environment for blood donors, addressing their concerns and providing necessary support before, during, and after donation. Volunteers also engaged in pre-event promotional activities to encourage maximum participation from students, faculty, and staff. The camp was conducted in partnership with authorized blood banks and qualified medical professionals who ensured all safety protocols and medical standards were strictly followed. This initiative provided volunteers with hands-on experience in organizing large-scale health and welfare events while contributing meaningfully to society.","aicteMapping":"Social Cause","pointsEarned":14,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/3e26df13-6690-434a-90d2-1ead38b48677/BM9ckKsaMFPoDGL_XZXT1.png","certificateAttached":true,"detailedReportPageNo":"25-26","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-02-01 15:02:56.103788+00', '2026-02-01 18:48:57.074513+00'), ('1c1d7fe4-395d-4da0-bdb9-4c57d1a162e4', 'b2256176-4531-41db-ad8f-ece09993ab8f', '{"student":{"usn":"1RV22CY013","name":"Arun","period":"2022-2026","department":"Computer Science & Engineering - Cybersecurity","totalPoints":0},"activities":[{"id":"uwvAMhANipk_eDKT9Nj6a","name":"Mere Pehele Vote Desh keliye","slNo":1,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/e0ZK0ACIMMqDyW8G3G9rz.jpeg"],"endDate":"2023-03-06","duration":1,"outcomes":"Increased awareness among students about the importance of voting and democratic values. Motivation of first-time voters to actively participate in elections. Enhanced understanding of electoral rights, responsibilities, and the voting process. Development of a sense of patriotism and social responsibility among participants. Encouraged students to become informed citizens and contribute positively to nation-building. Strengthened the idea that every single vote matters for the future of the country","semester":"3","startDate":"2023-03-06","hoursSpent":2,"description":"The event “Mera Pehle Vote – Desh Ke Liye” was organized with the objective of creating awareness among students and citizens about the importance of voting in a democratic nation. \\nThe program aimed to motivate first-time voters to actively participate in the electoral process and understand their role in nation-building. The program successfully encouraged young voters to be informed, responsible, and proactive citizens who contribute to strengthening democracy.","aicteMapping":"Awareness Drive","pointsEarned":4,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/KfKxvxRDwb8bqVUDjIkuA.jpg","certificateAttached":true,"detailedReportPageNo":"1-2","signatureOfCounsellor":""},{"id":"Hw41fqNbkoYDDRiMhfXEM","name":"Utsarga Marathon - Participant","slNo":3,"place":"RVCE Campus","photos":[],"endDate":"2024-02-04","duration":1,"outcomes":"The activity enhanced awareness among participants about the importance of physical fitness and maintaining a healthy lifestyle while strengthening interaction and bonding between students and the local community. It helped develop a strong sense of social responsibility, discipline, and volunteerism among students. Through active involvement in planning and execution, students improved their organizational, leadership, andteamwork skills. Overall, the program contributed positively to community well-being and encouraged continued participation in health-oriented and socially responsible activities.","semester":"3","startDate":"2024-02-04","hoursSpent":4,"description":"The Utsarga Marathon was organized as a Community Development initiative with the objective  of promoting health awareness, social responsibility, and community participation among  students and the general public. The event focused on encouraging physical fitness, discipline, and a sense of social commitment while spreading awareness about healthy lifestyles and community well-being. Students, faculty members, and local community participants actively took part in the marathon. The program also aimed to instill values of teamwork, leadership, and service towards society, aligning with the objectives of AICTE’s community engagement and social outreach initiatives.","aicteMapping":"Community  Development","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/frTtNLjaHqiKk1gxmMdE6.jpeg","certificateAttached":true,"detailedReportPageNo":"3-4","signatureOfCounsellor":""},{"id":"7wVwP-rkXYFZ3udV3XKC3","name":"PROJECT PUSTAK","slNo":4,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/rpVMhp762ka3FJdmkwWG3.jpeg"],"endDate":"2024-05-24","duration":1,"outcomes":"Through Project Pustak, I learned the importance of social responsibility and community engagement. The activity highlighted how small interventions, such as providing basic stationery, can create a significant impact on a child’s education. I gained a deeper understanding of the challenges faced by students from economically disadvantaged backgrounds and how lack of resources can affect attendance and learning outcomes. This initiative strengthened my sense of empathy, teamwork, and leadership, and reinforced the role of engineers and students in contributing positively to society beyond academics.","semester":"4","startDate":"2024-05-24","hoursSpent":3,"description":"Project Pustak is a joint initiative by the RV College of Engineering and the Pranav Foundation, aimed at supporting children in rural government schools. In 2024, the program made a meaningful impact by providing essential stationery like notebooks and geometry boxes to students from underprivileged communities. Many of these children, from economically disadvantaged families, often missed classes due to a lack of basic supplies. Pustak helps bridge this gap, ensuring every child has the tools they need to participate in their education.","aicteMapping":"Community  Development","pointsEarned":10,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"5","signatureOfCounsellor":""},{"id":"b7z7p64XGWBU_CRS4Hrk8","name":"Vikasit Bharath Quiz","slNo":5,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/mG94i2mQkzQH9lhE_zv9c.jpeg"],"endDate":"2024-12-01","duration":1,"outcomes":"The activity enhanced participants’ understanding of India’s developmental roadmap and the role of citizens, especially youth, in nation-building. It improved awareness of government initiatives, current affairs, and socio-economic challenges. The quiz also helped develop critical thinking, teamwork, and competitive spirit among students, while fostering a sense of patriotism and responsibility towards contributing to a Viksit Bharat.","semester":"4","startDate":"2024-12-01","hoursSpent":1,"description":"The Viksit Bharat Quiz Activity was organized to create awareness among students about the Government of India’s vision for a developed nation (Viksit Bharat). The quiz focused on key themes such as economic growth, digital transformation, innovation, sustainability, infrastructure development, and social inclusion. It encouraged participants to learn about national policies, flagship schemes, and India’s long-term development goals through an interactive and engaging format.","aicteMapping":"Community Development","pointsEarned":2,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/8U9bopD4OAJXnFZbWzAj1.png","certificateAttached":true,"detailedReportPageNo":"6-7","signatureOfCounsellor":""},{"id":"WJkHIoeehlAP1OxHNvbwb","name":"Fist Full","slNo":6,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/EzEP8mgJC9anrK0AWsb22.jpeg"],"endDate":"2024-11-29","duration":15,"outcomes":"The initiative received an overwhelming response, with over 6,700 kg of rice and 800 kg of toor dal donated by more than 1,750 students. The collected food grains contributed significantly to supporting underprivileged communities. The activity reinforced the impact of collective action and demonstrated how small individual contributions can lead to meaningful societal change. Participants gained a deeper sense of compassion, teamwork, and civic responsibility, strengthening RVCE’s commitment to community welfare and social solidarity.","semester":"4","startDate":"2024-11-15","hoursSpent":3,"description":"“Fist Full” is a social service initiative organized by the Rotaract Club of RV College of Engineering (RVCE) in collaboration with Rotary Bangalore Spandana, conducted from 15th to 29th November. The initiative aimed to combat hunger and food insecurity by encouraging students to donate 5 kg of rice or 2 kg of toor dal. Daily collections were carried out in the Civil Department, ensuring smooth coordination and participation. The drive witnessed enthusiastic involvement from students, reflecting a strong culture of empathy and social responsibility within the campus.","aicteMapping":"Community Development","pointsEarned":10,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"8","signatureOfCounsellor":""},{"id":"aNjKOwjN693ChYMsdHChW","name":"CHEELA MELA- Paper bag Workshop","slNo":7,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/Nh7BcRAwCpsLCoPTUmuBM.jpeg"],"endDate":"2024-11-12","duration":2,"outcomes":"The workshop successfully increased awareness about environmental conservation and the need to reduce plastic usage. Participants developed practical skills in making paper bags and understood how small eco-friendly initiatives can contribute to environmental protection. The activity fostered creativity, teamwork, and a sense of social responsibility, encouraging participants to adopt and promote sustainable practices in their daily lives and community events such as Cheela Mela.","semester":"4","startDate":"2024-11-11","hoursSpent":10,"description":"The Cheela Mela Paper Bag Workshop was organized to promote environmental awareness and sustainable practices among students and the local community. The workshop focused on training participants to make eco-friendly paper bags as an alternative to single-use plastic bags. Participants were guided through the process of designing and creating durable paper bags using recyclable materials, while also being educated about the harmful effects of plastic pollution and the importance of adopting sustainable lifestyle choices","aicteMapping":"Community Development","pointsEarned":20,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"9","signatureOfCounsellor":""},{"id":"AFWUEbYz-JW3EC-QwjvzF","name":"Police Marshal","slNo":8,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/fwKvhOzdZXOt2XJ2ldr6u.jpeg"],"endDate":"2024-12-18","duration":1,"outcomes":"The program enhanced students’ understanding of traffic regulations, public safety measures, and emergency response practices. Participants developed a sense of civic duty, discipline, and leadership by learning the responsibilities of police marshals. The event strengthened coordination between students and law enforcement agencies, encouraged responsible citizenship, and contributed to safer campus surroundings and public spaces.","semester":"5","startDate":"2024-12-18","hoursSpent":2,"description":"The Police Marshal Program was conducted at RV College in association with the Bangalore Police to promote road safety awareness, civic responsibility, and disciplined public behavior \\namong students. The program focused on educating participants about traffic rules, pedestrian safety, emergency response, and the role of police marshals in assisting law enforcement during public events and peak traffic hours. Officials from the Bangalore Police interacted with           students through demonstrations and awareness sessions, emphasizing the importance of cooperation between citizens and the police for maintaining public safety. The event aligned with AICTE’s  objectives of community engagement and social responsibility.","aicteMapping":"Awareness Drive","pointsEarned":5,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"10","signatureOfCounsellor":""},{"id":"8NioJlcZqLAXg0dEC6soS","name":"Utsarga Marathon - Participant","slNo":9,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/_H1PBvdIHf19un41clWuT.jpeg"],"endDate":"2025-04-06","duration":1,"outcomes":"The activity enhanced awareness among participants about the importance of physical fitness and maintaining a healthy lifestyle while strengthening interaction and bonding between students and the local community. It helped develop a strong sense of social responsibility, discipline, and volunteerism among students. Through active involvement in planning and execution, students improved their organizational, leadership, and teamwork skills. Overall, the program contributed positively to community well-being and encouraged continued participation in health-oriented and socially responsible activities.","semester":"5","startDate":"2025-04-06","hoursSpent":4,"description":"The Utsarga Marathon was organized as a Community Development initiative with the objective of promoting health awareness, social responsibility, and community participation among students and the general public. The event focused on encouraging physical fitness, discipline, and a sense of social commitment while spreading awareness about healthy lifestyles and community well-being. Students, faculty members, and local community participants actively took part in the marathon. The program also aimed to instill values of teamwork, leadership, and service towards society, aligning with the objectives of AICTE’s community engagement and social outreach initiatives.","aicteMapping":"Community  Development","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/PEq27WxvQFAMRUsLRXOn3.jpeg","certificateAttached":true,"detailedReportPageNo":"11-12","signatureOfCounsellor":""},{"id":"SZ0spRhzO80vWBXvBOPD3","name":"International Yoga Day Celebration  @ DD Chandana","slNo":10,"place":"DD Chandana Studio  Bangalore","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/0v7Nj8aGyPGRsMAGAoP1A.jpeg"],"endDate":"2025-06-21","duration":1,"outcomes":"The event enhanced awareness among participants about the benefits of yoga for physical fitness and mental harmony. It encouraged the adoption of yoga as a daily practice for a healthy lifestyle and stress management. Participants gained practical knowledge of correct postures and breathing techniques, fostering self-discipline and mindfulness. The program also strengthened community participation, promoted a culture of wellness, and supported the objectives ofInternational Yoga Day by spreading the message of health, peace, and well-being.","semester":"6","startDate":"2025-06-21","hoursSpent":3,"description":"The village camp resulted in tangible improvements to local infrastructure, including a safer and renovated bridge, enhanced school facilities, educational wall paintings, installation of flag poles, and the successful implementation of a sustainable solar-powered water supply system. Volunteers developed leadership qualities, teamwork, discipline, and a strong sense of social responsibility through hands-on community engagement. Environmental awareness was strengthened through plantation drives, cleanliness activities, and themes focusing on water \\nconservation, renewable energy, and climate action. The household survey provided valuable socio-economic insights for future development initiatives. Cultural programs andinteractions fostered mutual respect and strong bonds between volunteers and villagers. Overall, the camp significantly contributed to community development while enriching volunteers with practical experience, empathy, and civic consciousness in line with NSS and AICTE objectives","aicteMapping":"Community  Developmen","pointsEarned":5,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"13","signatureOfCounsellor":""},{"id":"S5OZTyVM7JepbqheLu3tC","name":"Buy a T-shirt, Plant a Tree","slNo":11,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/4G01v_H665291Oj1KAPrp.jpeg"],"endDate":"2025-07-07","duration":1,"outcomes":"The initiative successfully raised awareness about environmental protection and the importance of afforestation. Students actively contributed to sustainability efforts by planting saplings, fostering a sense of ownership and responsibility toward the environment. The activity reinforced eco-friendly values, promoted green practices on campus, and highlighted the role of individual actions in addressing environmental challenges. Participants developed greater environmental consciousness and commitment to long-term ecological sustainability.","semester":"6","startDate":"2025-07-07","hoursSpent":2,"description":"“Buy a T-shirt, Plant a Tree” was a community service and environmental awareness initiative organized by the Kannada Sangha to promote sustainability and individual responsibility among students. As part of the initiative, students who purchased a T-shirt were provided with a tree sapling along with clear guidelines on planting and maintenance. The distribution of T-shirts and saplings was conducted within the college campus, encouraging students to actively participate in environmental conservation by planting and nurturing trees.","aicteMapping":"Community Development","pointsEarned":15,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"14","signatureOfCounsellor":""},{"id":"02-BUlFARuAn5TTwiwnJs","name":"Nasha Muktha Bharath","slNo":12,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/_yB__zTLEtB_lyemUoL-8.jpeg"],"endDate":"2025-08-14","duration":1,"outcomes":"The activity successfully increased awareness about substance abuse and its long-term impact on individuals and society. Participants gained a better understanding of the importance of self-control, mental well-being, and healthy lifestyle choices. The initiative fostered a sense of social responsibility and encouraged students to act as ambassadors of a Nasha Mukta Bharat by spreading awareness among peers and the wider community. It also strengthened students’ commitment to personal discipline and community welfare.","semester":"6","startDate":"2025-08-14","hoursSpent":2,"description":"The Nasha Mukta Bharat Abhiyan activity was organized to create awareness among students and the community about the harmful effects of substance abuse and to promote a drug-free lifestyle. The activity focused on educating participants about the physical, mental, and social consequences of addiction through awareness sessions, discussions, and interactive activities. Emphasis was placed on prevention, responsible decision-making, and the importance of maintaining a healthy and disciplined life.","aicteMapping":"Community Development","pointsEarned":2,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/iSDNHELfdfVwGtd9KbS4r.jpg","certificateAttached":true,"detailedReportPageNo":"15-16","signatureOfCounsellor":""},{"id":"4ltKAgeMgxTkijKi4DFK-","name":"Vikasit Bharath Quiz","slNo":13,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/riJpoZC3xL_2COUQCS9UZ.jpeg"],"endDate":"2025-09-11","duration":1,"outcomes":"The activity enhanced participants’ understanding of India’s developmental roadmap and the role of citizens, especially youth, in nation-building. It improved awareness of government \\ninitiatives, current affairs, and socio-economic challenges. The quiz also helped develop critical thinking, teamwork, and competitive spirit among students, while fostering a sense of patriotism and responsibility towards contributing to a Viksit Bharat.","semester":"6","startDate":"2025-09-11","hoursSpent":2,"description":"The Viksit Bharat Quiz Activity was organized to create awareness among students about the Government of India’s vision for a developed nation (Viksit Bharat). The quiz focused \\non key themes such as economic growth, digital transformation, innovation, sustainability, infrastructure development, and social inclusion. It encouraged participants to learn about national policies, flagship schemes, and India’s long-term development goals through an interactive and engaging format.","aicteMapping":"Community  Development","pointsEarned":2,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/b2256176-4531-41db-ad8f-ece09993ab8f/E7pGGFaQV_uIu3fI-Zd2F.png","certificateAttached":true,"detailedReportPageNo":"17-18","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"Dr Mohana","designation":"Associate Professor, Department of CSE(Cyber Security),                                                                                                                                                          RV College of Engineering, Bengaluru"},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-30 06:38:37.398683+00', '2026-01-30 16:06:57.337207+00'), ('1c3e9477-756b-4c2b-9fd0-05da4df8b848', '2a53e9ca-d474-4185-8a34-c2e6d1a1a95c', '{"student":{"usn":"1RV22CV076","name":"PRAJWAL K GOWDA","period":"2022-2026","department":"Civil Engineering","totalPoints":0},"activities":[{"id":"sxvZiu1uZZUbAUh20sJE9","name":"Mera Phale Vote","slNo":1,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2a53e9ca-d474-4185-8a34-c2e6d1a1a95c/-ArR2PXthgFZVTIdXhSyh.png"],"endDate":"2023-03-06","duration":1,"outcomes":"The primary outcome of this activity was a significant enhancement in personal awareness regarding the functioning of the Indian electoral system and the critical value of a single vote. By successfully completing the quiz and the pledge, I demonstrated both technical knowledge of democratic processes and a moral commitment to ethical voting. This initiative instilled a strong sense of civic responsibility and national pride, preparing me to be a conscientious participant in the nation''s governance.","semester":"1","startDate":"","hoursSpent":0,"description":"I actively participated in the \"Mera Pehla Vote – Desh Ke Liye\" campaign, a significant national initiative facilitated by the NSS unit of RVCE to foster electoral literacy among the youth. Conducted via the government''s MyGov platform, this event was designed to address the crucial need for engaging young and aspiring voters in the democratic process of Bharat. The initiative highlighted the power of the youth voice in shaping the nation''s future and served as a digital call to action for students to recognize their pivotal role in the governance of the country.\\n\\nThe participation involved a two-fold engagement strategy to ensure a holistic understanding of civic duties. Firstly, I took a solemn \"Voter''s Pledge,\" formally committing to uphold the democratic traditions of the country and to vote in every election fearlessly and without being influenced by considerations of religion, race, caste, or community. Secondly, I completed a specialized quiz centered on India’s Democracy. This interactive assessment was aimed at testing and improving knowledge regarding the constitutional rights of voters, the electoral machinery, and the importance of the franchise, ultimately emphasizing that the strength of a democracy lies in an informed and active electorate.","aicteMapping":"Awareness Drive","pointsEarned":4,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2a53e9ca-d474-4185-8a34-c2e6d1a1a95c/eqrDjbgKNeTpzA0T7N8VV.jpg","certificateAttached":true,"detailedReportPageNo":"1-2","signatureOfCounsellor":""},{"id":"2B4ats8QRNp4jG8PcLs7g","name":"Blood donation camp","slNo":2,"place":"RVCE","photos":[],"endDate":"","duration":0,"outcomes":"Directly contributed to community welfare and public health by aiding those in need of medical assistance. Cultivated a deep sense of social responsibility, altruism, and civic duty, while understanding the vital role students play in addressing healthcare shortages.","semester":"1","startDate":"2023-06-06","hoursSpent":0,"description":"Participated in a voluntary Blood Donation Camp organized by the institute during the first semester. The activity involved undergoing a preliminary health check-up and donating blood to support local blood banks and healthcare facilities in meeting their critical supply requirements.","aicteMapping":"","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2a53e9ca-d474-4185-8a34-c2e6d1a1a95c/LaqEt3c5oQCTnxXgSeA4t.jpeg","certificateAttached":true,"detailedReportPageNo":"3-4","signatureOfCounsellor":""},{"id":"YFY9iHHnjrrMtb0d1tuVh","name":"T Shirt for Smiles","slNo":3,"place":"RVCE","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/2a53e9ca-d474-4185-8a34-c2e6d1a1a95c/CqoZ2hYRRJii9opF2YHkN.jpg"],"endDate":"","duration":0,"outcomes":"Contributed financially to a meaningful cause, directly aiding in the welfare of underprivileged children at the Prajakirana Seva Charitable Trust. Demonstrated social responsibility and solidarity by actively supporting the community service efforts organized by the student body.","semester":"4","startDate":"2024-07-07","hoursSpent":0,"description":"Participated in the \"T-Shirt for Smiles\" initiative organized by the Kannada Sangha on July 7, 2024. This charitable event involved purchasing a T-shirt to support the Prajakirana Seva Charitable Trust Anathashram in Kumbalgodu, Bengaluru, with the proceeds aimed at supporting and bringing joy to the children residing at the orphanage.","aicteMapping":"","pointsEarned":5,"certificateImage":"","certificateAttached":false,"detailedReportPageNo":"5-6","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"Prof. Shashi Kiran.C.R","designation":"Assistant Professor"},"evaluator1":{"name":"Signature of Evaluator","designation":" "},"evaluator2":{"name":"Signature of Evaluator","designation":" "}}}', '2026-01-29 18:14:55.153984+00', '2026-01-29 18:20:04.299979+00'), ('1ccd2e8e-3543-48f0-b7d2-8aebc787c52b', 'da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa', '{"student":{"usn":"1RV22EC090","name":"Mahima Gowda R G","period":"2022-2026","department":"Electronics & Communication Engineering","totalPoints":0},"activities":[{"id":"i9jVgBrK_zwdpXq36mBrr","name":"Utsarga 2024 – NSS Club, RVCE","slNo":1,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/IdkI9h4U8w0FApmJQ7Jzl.jpeg"],"endDate":"2024-02-04","duration":1,"outcomes":"This marathon celebration of health and fitness focused on a social mission to help reshape children''s futures by raising funds to provide education for underprivileged students. ","semester":"1","startDate":"2024-02-04","hoursSpent":4.5,"description":"The Utsarga Marathon is an extraordinary event and a celebration of health, fitness, and making a difference, with a social mission to help reshape a child''s future by supporting education for those in need.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/PXbf5ZrSG1OOzFzlsBNzb.jpeg","certificateAttached":true,"detailedReportPageNo":"1-2","signatureOfCounsellor":""},{"id":"LWJXp514R28T8SrcF2fUI","name":"Utsarga 2025 – NSS Club, RVCE","slNo":2,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/_6rgdibNPS1WXLhwDvVZP.jpeg"],"endDate":"2025-04-06","duration":1,"outcomes":"This marathon celebration of health and fitness focused on a social mission to help reshape children''s futures by raising funds to provide education for underprivileged students.","semester":"6","startDate":"2025-04-06","hoursSpent":4.5,"description":"The Utsarga Marathon is an extraordinary event and a celebration of health, fitness, and making a difference, with a social mission to help reshape a child''s future by supporting education for those in need.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/4jAmzP2-GbTRPlu512-WT.jpeg","certificateAttached":true,"detailedReportPageNo":"3-4","signatureOfCounsellor":""},{"id":"Y-LnHtfu7KkuQiyiFYqGf","name":"IEEE Volunteering","slNo":3,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/pnAFOF_gd21EKr-D2amSX.jpeg"],"endDate":"2025-06-01","duration":1,"outcomes":"The workshop enhanced participants’ understanding of advanced antenna concepts and emerging research trends in wireless and satellite  communications.  It also inspired students  to  pursue innovation and research in antenna technologies while strengthening industry–academia interaction.","semester":"5","startDate":"2025-06-01","hoursSpent":6,"description":"An IEEE Distinguished Lecturer (DL) Workshop on Advanced Antenna Technologies was conducted at RV College of Engineering, Bangalore, jointly organized by the IEEE AP-S Bangalore Chapter and the IEEE MTT-S RVCE Student Chapter. The workshop featured technical talks by IEEE Fellows and experts on satellite and ground antenna systems, hybrid UTD–ECM methods, polarization in electromagnetics, and open-source 5G testbeds. The event attracted around 100 students, researchers, and professionals, facilitating effective knowledge exchange with academic and industry experts.","aicteMapping":"Promotion of appropriate technologies","pointsEarned":8,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/2_mQsx4H-f0SQ4IFdN4qW.jpg","certificateAttached":true,"detailedReportPageNo":"5-6","signatureOfCounsellor":""},{"id":"6mfw4OhimtpdRhRudhl5G","name":"Paper Bag 1– NSS Club, RVCE ","slNo":4,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/yimesfFu9C4AyEaYE70qg.png"],"endDate":"2025-01-13","duration":1,"outcomes":"Continuing the sustainable collaboration with Youth For Seva, this workshop resulted in the creation of 200 newspaper bags by the student to reduce environmental waste. ","semester":"5","startDate":"2025-01-13","hoursSpent":8,"description":"NSS RVCE, in collaboration with Youth For Seva, is organizing a paper bag workshop. Go green by creating newspaper bags and contribute towards a sustainable environment! ","aicteMapping":"Preparing an actionable business proposal for enhancing the village income","pointsEarned":18,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/4gk49YwSnPdjDl_oalTKN.jpg","certificateAttached":true,"detailedReportPageNo":"7-8","signatureOfCounsellor":""},{"id":"JB0MBOYJ7W8vsMrpd34JN","name":"Fist Full 2024 – Rotaract, RVCE ","slNo":5,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/ES-RHQCoBvUQU6cPYyQua.png"],"endDate":"2024-11-15","duration":1,"outcomes":"This large-scale hunger combat initiative successfully collected over 5,700 kg of rice and 800 kg of toor dal from students to support community welfare and solidarity.","semester":"5","startDate":"2024-11-15","hoursSpent":2,"description":"The “Fist Full” initiative by Rotaract Club of RVCE in collaboration with Rotary Bangalore Spandana encouraged students to donate rice or toor dal to support hunger relief. The drive collected significant contributions, highlighting student solidarity and RVCE’s commitment to community welfare.","aicteMapping":"Food preservation/packaging","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/agcJ3OfIworvQMMgU1SqX.jpg","certificateAttached":true,"detailedReportPageNo":"9-10","signatureOfCounsellor":""},{"id":"lymTrVsCdCaOLsZxZG3bQ","name":"Fist Full 2025 – Rotaract, RVCE ","slNo":6,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/ZvxGJtrz4Bxiv5gP760ri.png"],"endDate":"2025-12-12","duration":1,"outcomes":"This large-scale hunger combat initiative successfully collected over 5,700 kg of rice and 800 kg of toor dal from students to support community welfare and solidarity.","semester":"7","startDate":"2025-12-12","hoursSpent":2,"description":"The “Fist Full” initiative by Rotaract Club of RVCE in collaboration with Rotary Bangalore Spandana encouraged students to donate rice or toor dal to support hunger relief. The drive collected significant contributions, highlighting student solidarity and RVCE’s commitment to community welfare.","aicteMapping":"Food preservation/packaging","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/47KKSoQVe4aidYd9cF0ir.png","certificateAttached":true,"detailedReportPageNo":"11-12","signatureOfCounsellor":""},{"id":"pYNlxtqD5FiGFFIB_C3Oi","name":"Paper Drive","slNo":7,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/tcbbRexxqkWtWbgbIoKiv.jpeg"],"endDate":"2024-06-27","duration":1,"outcomes":"The paper drive reduced landfill waste by ensuring proper recycling through door-to-door collection while creating strong awareness about waste segregation and recycling. It encouraged community participation, built volunteer teamwork and leadership skills, and supported tree conservation through sustainable environmental practices.","semester":"4","startDate":"2024-06-27","hoursSpent":8,"description":"The Paper Drive in Bangalore promoted recycling and responsible waste management through door-to-door collection of used paper from homes, offices, and institutions, while spreading awareness on waste segregation. The collected paper was sent to authorized recyclers, reducing landfill waste and encouraging eco-friendly habits, while participants gained practical knowledge of environmental responsibility.","aicteMapping":"Reduction in energy consumption","pointsEarned":8,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/ebi3z7uFqOx2NvAG9P_mx.jpg","certificateAttached":true,"detailedReportPageNo":"13-14","signatureOfCounsellor":""},{"id":"RU0JFJzGmk7XpOnatCUs7","name":"Eye Donation Fortnight","slNo":8,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/eSJAPG5qfs14svjerUvxN.png"],"endDate":"2024-09-24","duration":1,"outcomes":"Many students enrolled as Sight Ambassadors, strengthening awareness of eye donation across campus and beyond. The program successfully promoted social responsibility while supporting the national effort to increase eye-donor registrations.","semester":"4","startDate":"2024-09-24","hoursSpent":1,"description":"Eye Donation Fortnight, organized by NSS RVCE, aimed to spread awareness about eye donation by encouraging students to register as Sight Ambassadors and pledge their eyes through a simple online process. The initiative focused on educating participants about the importance of corneal donation and motivating peer advocacy.","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/tG7lI2lwBufex5g1wkYWH.jpeg","certificateAttached":true,"detailedReportPageNo":"15-16","signatureOfCounsellor":""},{"id":"_4zWxn5M8I6t_4xes-VkW","name":"Mera Phala Vote – NSS Club, RVCE ","slNo":9,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/2onCHpuR10CVNZ_MICqnm.png"],"endDate":"2024-03-05","duration":1,"outcomes":"This online awareness event engaged young voters, resulting in participants taking a formal pledge to exercise their democratic rights and encourage others to build a \"New India\".","semester":"3","startDate":"2024-03-05","hoursSpent":1,"description":"An Online Event organized by NSS RVCE with a focus on engaging young and aspiring voters.","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":4,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/nFwlnFdHNcK-_b8X4rejv.jpeg","certificateAttached":true,"detailedReportPageNo":"17-18","signatureOfCounsellor":""},{"id":"xah3YsPe0THsEjrSUElZW","name":"Plantation Drive 2024","slNo":10,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/Lv1MNNslggppFBjpAD_M4.jpeg"],"endDate":"2024-05-26","duration":1,"outcomes":"Participants contributed directly to increasing green cover while gaining awareness about sustainable living. The program successfully completed 427 consecutive Green Sundays, demonstrating consistent community engagement and impact on urban environmental restoration.","semester":"4","startDate":"2024-05-26","hoursSpent":5,"description":"Green Sunday is a tree-planting and nurturing program by Adamya Chetana that encourages citizens and students to actively participate in environmental conservation through regular plantation drives. The initiative focuses on building long-term responsibility toward nature by involving participants in planting and caring for saplings.","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":3,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/DLdLwDuau1BrsS8tXBFdS.jpg","certificateAttached":true,"detailedReportPageNo":"19-20","signatureOfCounsellor":""},{"id":"_b7c02FiJ75g1s1BIsGJI","name":"ONE STUDENT-ONE PLANT: GREEN ","slNo":11,"place":"Jnanabharathi Forest Area","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/G4wXwViY9ijClHzzL--Xa.jpeg"],"endDate":"2023-07-11","duration":1,"outcomes":"Participants contributed directly to increasing green cover while gaining awareness about sustainable living. The program successfully completed 427 consecutive Green Sundays, demonstrating consistent community engagement and impact on urban environmental restoration.","semester":"2","startDate":"2023-07-11","hoursSpent":7,"description":"Green Sunday is a tree-planting and nurturing program by Adamya Chetana that encourages citizens and students to actively participate in environmental conservation through regular plantation drives. The initiative focuses on building long-term responsibility toward nature by involving participants in planting and caring for saplings.","aicteMapping":"Automation of local activities","pointsEarned":5,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/YplvKQBxDNfIpn4ohtSRp.png","certificateAttached":true,"detailedReportPageNo":"21-22","signatureOfCounsellor":""},{"id":"rRNmLhyKGPO8IU9WNbQ5W","name":"AEC Plantation Drive 1","slNo":12,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/Hm3kwdTgmwPTMr42OxS6g.jpeg"],"endDate":"2023-03-22","duration":1,"outcomes":"Participants contributed directly to increasing green cover while gaining awareness about sustainable living. The program successfully completed 427 consecutive Green Sundays, demonstrating consistent community engagement and impact on urban environmental restoration.","semester":"1","startDate":"2023-03-22","hoursSpent":5,"description":"Green Sunday is a tree-planting and nurturing program by Adamya Chetana that encourages citizens and students to actively participate in environmental conservation through regular plantation drives. The initiative focuses on building long-term responsibility toward nature by involving participants in planting and caring for saplings.","aicteMapping":"Promotion of appropriate technologies","pointsEarned":2,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/dwHWvmNwKTJuBSOrgp8ox.jpg","certificateAttached":true,"detailedReportPageNo":"23-24","signatureOfCounsellor":""},{"id":"VEl0BsMBU5smvnX2zJF0s","name":"AEC Plantation Drive 2","slNo":13,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/SI0AsKli_LG_BH6GqSGWq.jpeg"],"endDate":"2023-07-22","duration":1,"outcomes":"Participants contributed directly to increasing green cover while gaining awareness about sustainable living. The program successfully completed 427 consecutive Green Sundays, demonstrating consistent community engagement and impact on urban environmental restoration.","semester":"2","startDate":"2023-07-22","hoursSpent":5,"description":"Green Sunday is a tree-planting and nurturing program by Adamya Chetana that encourages citizens and students to actively participate in environmental conservation through regular plantation drives. The initiative focuses on building long-term responsibility toward nature by involving participants in planting and caring for saplings.","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":2,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/da9cb3b9-4167-4c4d-a5fb-e8ef67ac57fa/wFFb36sfCtKjRfNgkmoNW.png","certificateAttached":true,"detailedReportPageNo":"25-26","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"Dr. Rajasree P.M","designation":"Assistant Professor"},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-30 05:07:17.959353+00', '2026-02-01 17:36:09.472927+00'), ('1d00e373-3fe4-427d-a9bf-c046adeca817', 'ebf4a42c-99f3-41b4-b892-1a93a32d4221', '{"student":{"usn":"1RV22CY041","name":"Mohammed Ammar Mansoor","period":"2022-2026","department":"Computer Science & Engineering - Cybersecurity","totalPoints":0},"activities":[{"id":"_aojeI330iyv_oGZYhhgs","name":"Fast Trek 2.0","slNo":1,"place":"Kudagalu Hills Trek","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/MUgN4-OgJzeAdYhDeuYg3.png"],"endDate":"2024-01-28","duration":1,"outcomes":"Gained practical experience in organizing and participating in a community-based environmental initiative.\\n\\nDeveloped a strong sense of social responsibility and awareness about environmental cleanliness and conservation.\\n\\nLearned the importance of teamwork, coordination, and discipline while working with a large group of participants.\\n\\nImproved leadership, communication, and time-management skills through active involvement in the event.\\n\\nUnderstood the significance of following safety protocols and planning in outdoor activities such as trekking.\\n\\nExperienced the positive impact of collective efforts in maintaining natural ecosystems and promoting sustainable practices","semester":"3","startDate":"2024-01-28","hoursSpent":24,"description":"The project was undertaken with a strong social objective of promoting environmental cleanliness through a cleanliness drive conducted during the trek. The event commenced at 7:30 AM, with participants enthusiastically boarding buses to reach the trekking location. Prior to the start of the trek, all participants were briefed with comprehensive safety instructions and event details to ensure a safe and well-organized experience. The trek across the scenic Kunagalu Betta Hills proved to be highly successful, offering participants a memorable journey through breathtaking natural landscapes. More than 750 individuals actively participated in the trekking activity, significantly contributing to the vibrant and energetic atmosphere of the event.","aicteMapping":"Developing and managing efficient garbage disposable system","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/HqbVVGW7Dg9waUkkCQ8YJ.png","certificateAttached":true,"detailedReportPageNo":"2","signatureOfCounsellor":""},{"id":"dz0CycahG43EJUnnYkjxU","name":"Utsarga Marathon 2024","slNo":2,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/qT2T_dG7unLZvKP6nKjNO.jpg"],"endDate":"2024-02-04","duration":1,"outcomes":"The activity enhanced awareness among participants about the importance of physical fitness \\nand maintaining a healthy lifestyle while strengthening interaction and bonding between \\nstudents and the local community. It helped develop a strong sense of social responsibility, \\ndiscipline, and volunteerism among students. Through active involvement in planning and \\nexecution, students improved their organizational, leadership, andteamwork skills. Overall, \\nthe program contributed positively to community well-being and encouraged continued \\nparticipation in health-oriented and socially responsible activities.","semester":"3","startDate":"2024-02-04","hoursSpent":24,"description":"The Utsarga Marathon was organized as a Community Development initiative with the \\nobjective of promoting health awareness, social responsibility, and community participation \\namong students and the general public. The event focused on encouraging physical fitness, \\ndiscipline, and a sense of social commitment while spreading awareness about healthy lifestyles \\nand community well-being. Students, faculty members, and local community participants \\nactively took part in the marathon. The program also aimed to instill values of teamwork, \\nleadership, and service towards society, aligning with the objectives of AICTE’s community \\nengagement and social outreach initiatives. ","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/6bpu5xexlcGNUH18_loKs.jpg","certificateAttached":true,"detailedReportPageNo":"4","signatureOfCounsellor":""},{"id":"mJ9UlcQGh5qlNbG9rqceq","name":"Project Pustak","slNo":3,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/MhoC9fMZnbQcmBDofAQUl.png"],"endDate":"2024-05-24","duration":1,"outcomes":"Understood the importance of education as a fundamental tool for social development, especially for underprivileged students in rural areas.\\n\\nGained practical exposure to planning and executing a social service initiative, including fund collection and resource allocation.\\n\\nLearned how small individual contributions, when combined collectively, can create a significant positive impact on society.\\n\\nDeveloped teamwork, coordination, and communication skills by working alongside Rotaract Club of RVCE and Pranav Foundation.\\n\\nEnhanced awareness about social inequality and the role of student-led initiatives in addressing educational gaps.\\n\\nExperienced a sense of responsibility, empathy, and fulfillment by contributing towards improving learning opportunities for needy students.","semester":"4","startDate":"2024-05-24","hoursSpent":24,"description":"Project Pustak is a socially responsible initiative aimed at supporting underprivileged students in rural areas by providing them with essential school supplies. The project focused on collecting funds from generous donors, with contributions of Rs. 100 or Rs. 350 from each individual. These funds were efficiently utilized to procure important educational materials such as textbooks, notebooks, stationery items, school bags, and other learning resources necessary for creating a conducive educational environment. The initiative was carried out in collaboration with the Rotaract Club of RVCE and Pranav Foundation, ensuring proper planning and transparent utilization of resources. Through this project, essential school supplies were distributed to deserving students, thereby contributing to improved access to education and encouraging academic growth among rural children.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/7ryzdpv7XaELA7tPF6LC_.jpg","certificateAttached":true,"detailedReportPageNo":"6","signatureOfCounsellor":""},{"id":"65_9isEoFTu7ee7rsvCP6","name":"FIST FULL","slNo":4,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/p2B2NNO2kFxxby3hUfnUi.png"],"endDate":"2024-12-01","duration":154,"outcomes":"Developed a strong sense of empathy and social responsibility towards orphaned and underprivileged children.\\n\\nUnderstood how small daily contributions can collectively create a significant and long-term impact.\\n\\nGained experience in planning, coordinating, and executing a community service initiative.\\n\\nImproved teamwork, leadership, and communication skills through collaboration with Rotaract Club of Bangalore Spandana.\\n\\nLearned the importance of resource management and organized collection for charitable distribution.\\n\\nExperienced personal satisfaction and motivation by contributing to the welfare of the community.","semester":"4","startDate":"2024-07-01","hoursSpent":24,"description":"The FIST FULL project is a humanitarian initiative aimed at supporting orphaned and underprivileged children by encouraging participants to contribute a small portion of daily food grains for a noble cause. The initiative motivated individuals to set aside a fistful of rice or dal in dedicated bags on a daily basis, which were later collected and donated to those in need. The project was carried out in collaboration with the Rotaract Club of Bangalore Spandana, R.I. District 3191.\\n\\nThe event concluded successfully with the collection of 325 kg of rice, 115 kg of dal, 20 kg of wheat flour, and 15 kg of moong dal. These provisions are expected to sustain 91 refugee orphans and underprivileged children for approximately three months. The collection was conducted at R V College of Engineering, and the donated provisions were handed over to Adyava Educational and Charitable Trust. Through this initiative, the project demonstrated the power of collective effort and reinforced the values of empathy, social responsibility, and community service.","aicteMapping":"Helping local schools to achieve good result and enhance their enrolment in Higher technical/vocational education","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/cHwGyM7Am_1OEyIDOk8Jj.png","certificateAttached":true,"detailedReportPageNo":"8","signatureOfCounsellor":""},{"id":"dfxYHozuGMUtccxZRt6Uk","name":"Viksit Bharat Quiz Challenge","slNo":5,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/SO8F-TDmofSMU_UjGKRHS.png"],"endDate":"2025-01-01","duration":1,"outcomes":"The activity enhanced participants’ understanding of India’s developmental roadmap and the \\nrole of citizens, especially youth, in nation-building. It improved awareness of government \\ninitiatives, current affairs, and socio-economic challenges. The quiz also helped develop critical \\nthinking, teamwork, and competitive spirit among students, while fostering a sense of patriotism \\nand responsibility towards contributing to a Viksit Bharat.","semester":"5","startDate":"2025-01-01","hoursSpent":24,"description":" The Viksit Bharat Quiz Activity was organized to create awareness among students about \\nthe Government of India’s vision for a developed nation (Viksit Bharat). The quiz focused \\non key themes such as economic growth, digital transformation, innovation, sustainability, \\ninfrastructure development, and social inclusion. It encouraged participants to learn about \\nnational policies, flagship schemes, and India’s long-term development goals through an \\ninteractive and engaging format.","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":2,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/nYkOSce88Abknc8XidxST.jpg","certificateAttached":true,"detailedReportPageNo":"10","signatureOfCounsellor":""},{"id":"jdZ7ntE8BRm5GHpb6fYPq","name":"FAST TREK 3.0","slNo":6,"place":"Narayangiri Hills","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/nVZ5i0utnrbYXSjL_M9bi.png"],"endDate":"2025-01-12","duration":1,"outcomes":"Developed a strong sense of environmental responsibility through active participation in a cleanliness drive in a natural setting.\\n\\nGained practical experience in organizing and managing a large-scale outdoor event involving over 500 participants.\\n\\nLearned the importance of teamwork, coordination, and mutual support during physically demanding activities such as trekking.\\n\\nImproved leadership, communication, and decision-making skills through group interaction and collective problem-solving.\\n\\nEnhanced awareness of eco-conscious practices and the need to preserve natural landscapes.\\n\\nExperienced personal growth, confidence, and motivation by successfully completing the trek and contributing to a social cause.","semester":"5","startDate":"2025-01-12","hoursSpent":24,"description":"FAST TREK 3.0, the flagship event of the Rotaract Club of RVCE, was successfully conducted on 12th January 2025 at the scenic Narayanagiri Hills. The event brought together over 500 enthusiastic participants from the college, combining adventure trekking with a meaningful cleanliness drive to promote environmental responsibility. The trek commenced early in the morning, offering participants an exciting journey through the rugged trails of the hills. Along the route, participants actively engaged in cleaning the surroundings, collecting litter, and spreading awareness about eco-friendly practices.\\n\\nThe initiative not only contributed to preserving the natural beauty of Narayanagiri Hills but also instilled a strong sense of social and environmental responsibility among students. Beyond the cause, FAST TREK 3.0 fostered teamwork, camaraderie, and mutual encouragement, making the experience both impactful and memorable. The event concluded on a successful note, leaving a lasting positive impact on the participants and setting a benchmark for future community-oriented adventure events.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/ekSrYbfdLw6LB9HmCpKyx.png","certificateAttached":true,"detailedReportPageNo":"12","signatureOfCounsellor":""},{"id":"_UqRKyG9toGq13hUf9Sds","name":"Utsarga Marathon 2025","slNo":7,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/vvWDZ_fEltHKBt9FdkI3b.png"],"endDate":"2025-04-06","duration":1,"outcomes":"The activity enhanced awareness among participants about the importance of physical fitness \\nand maintaining a healthy lifestyle while strengthening interaction and bonding between \\nstudents and the local community. It helped develop a strong sense of social responsibility, \\ndiscipline, and volunteerism among students. Through active involvement in planning and \\nexecution, students improved their organizational, leadership, andteamwork skills. Overall, \\nthe program contributed positively to community well-being and encouraged continued \\nparticipation in health-oriented and socially responsible activities","semester":"6","startDate":"2025-04-06","hoursSpent":24,"description":"The Utsarga Marathon was organized as a Community Development initiative with the \\nobjective of promoting health awareness, social responsibility, and community participation \\namong students and the general public. The event focused on encouraging physical fitness, \\ndiscipline, and a sense of social commitment while spreading awareness about healthy lifestyles \\nand community well-being. Students, faculty members, and local community participants \\nactively took part in the marathon. The program also aimed to instill values of teamwork, \\nleadership, and service towards society, aligning with the objectives of AICTE’s community \\nengagement and social outreach initiatives","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/DI1TBt85RBdjQjNJCdr_v.jpg","certificateAttached":true,"detailedReportPageNo":"14","signatureOfCounsellor":""},{"id":"VQg9-VjqlVHCi7Sd3_yNx","name":"Encanto","slNo":9,"place":"","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/v79I8HWdMwqC5C6Eozogn.png"],"endDate":"2025-04-20","duration":2,"outcomes":"To provide a platform for leadership development and skill enhancement among Rotaract members.\\n\\nTo encourage meaningful interaction and collaboration between different Rotaract clubs.\\n\\nTo inspire participants through motivational talks and real-life leadership experiences.\\n\\nTo promote idea-sharing and innovation through activities such as Rota Pitch.\\n\\nTo strengthen camaraderie and unity through cultural and networking activities.\\n\\nTo reinforce the core values of discipline, service, and teamwork within the Rotaract community.","semester":"6","startDate":"2025-04-19","hoursSpent":48,"description":"ENCANTO, the Second Annual Rotaract District Conference, was held on 19th and 20th April 2025 at RV Dental College. The two-day conference brought together Rotaract members from various clubs, with 45 participants representing our college. The event was designed to promote leadership development, inter-club interaction, and idea exchange among Rotaractors.\\n\\nThe conference featured an inspiring motivational address by Major Raghavendra C, emphasizing the values of discipline, leadership, and service. Participants actively engaged in Rota Pitch, where innovative project ideas were presented and discussed with peers and mentors. Cultural performances by Footprints and Alaap added vibrancy to the event and fostered a sense of unity and celebration. In addition to structured sessions, informal networking opportunities enabled meaningful connections between clubs. Overall, ENCANTO provided a well-rounded platform for learning, collaboration, and personal growth.","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":12,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/VRcxsscrI_FTjhl5ygf5o.png","certificateAttached":true,"detailedReportPageNo":"16","signatureOfCounsellor":""},{"id":"nV58JWyU9r8fDTu-N-50h","name":"Project Pustak 2025","slNo":9,"place":"RVCE Campus","photos":[],"endDate":"2025-10-01","duration":93,"outcomes":"Successfully mobilized large-scale participation, with 1,022 students contributing towards a common social cause.\\n\\nGained practical experience in planning, organizing, and executing a structured fundraising initiative.\\n\\nUnderstood the importance of collective effort in addressing educational inequalities among underprivileged children.\\n\\nDeveloped teamwork, coordination, and communication skills through collaboration with Pranav Foundation and internal club members.\\n\\nLearned effective fund management and transparent utilization of resources for social welfare activities.\\n\\nContributed to improving access to educational materials for students in government schools, thereby promoting inclusive education.\\n\\nEnhanced a sense of social responsibility, empathy, and commitment to community service among participants.","semester":"6","startDate":"2025-07-01","hoursSpent":24,"description":"The Rotaract Club of RVCE successfully launched Phase-1 of its flagship initiative, Project Pustak, from 23rd to 30th April, in collaboration with the Pranav Foundation. The project, recognized and appreciated by UGRAM, was undertaken with the objective of supporting the education of underprivileged children by providing essential learning materials. Phase-1 of the initiative focused on collecting funds and resources from within the RVCE community to ensure maximum participation and impact.\\n\\nThe project received an overwhelming response, successfully raising a total sum of ₹3,50,000 through contributions from 1,022 students, reflecting the strong spirit of generosity and collective social responsibility among participants. Students who contributed ₹350 were acknowledged with a certificate for 10 Activity Points. The funds collected during Phase-1 were utilized in Phase-2 for the procurement and distribution of stationery kits and books to children studying in government schools. Through this initiative, Project Pustak effectively contributed to promoting education and reducing resource gaps for students in need.","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/xKQ6xl1o4BPG5Lki01hLW.png","certificateAttached":true,"detailedReportPageNo":"18","signatureOfCounsellor":""},{"id":"NR-2QnoBn2fviMguVs1Xz","name":"Lakshya","slNo":10,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/M_KrKmZR5Yu7xzbI-35VS.png"],"endDate":"2025-04-26","duration":1,"outcomes":"To enhance concentration, discipline, and precision through supervised shooting practice.\\n\\nTo promote teamwork, focus, and self-control among participating students.\\n\\nTo create awareness about environmental conservation through sapling distribution.\\n\\nTo encourage students to actively participate in sustainable and eco-friendly practices.\\n\\nTo integrate skill development with social and environmental responsibility.\\n\\nTo foster holistic growth by combining physical training with civic awareness.","semester":"6","startDate":"2025-04-26","hoursSpent":24,"description":"Lakshya was a shooting event organized by the NCC unit at R V College of Engineering on 26th and 27th April 2025. The event was designed to promote discipline, focus, teamwork, and precision among students through supervised shooting activities. Beyond skill development, the initiative emphasized environmental responsibility by integrating a sapling distribution drive as part of the event.\\n\\nEach participant was provided with a sapling along with instructions on proper planting and care, encouraging students to contribute personally to environmental sustainability within the college campus and beyond. The event successfully blended technical skill enhancement with social and environmental consciousness, making Lakshya more than just a competitive activity. By combining physical discipline with ecological awareness, the initiative reinforced the values of responsibility, sustainability, and holistic student development.","aicteMapping":"Setting of the information imparting club for women leading to contributing in social and economic issues","pointsEarned":10,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/-LZoydmfotwlja-rL7Ckz.jpg","certificateAttached":true,"detailedReportPageNo":"20","signatureOfCounsellor":""},{"id":"D-BqYeu9jNfgPbRfONRjv","name":"Buy a T-shirt, Plant a Tree","slNo":11,"place":"RVCE Campus","photos":["https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/o8VJiLvCBb0jIs7M8Eeqh.png"],"endDate":"2025-07-07","duration":1,"outcomes":"The initiative successfully raised awareness about environmental protection and the importance \\nof afforestation. Students actively contributed to sustainability efforts by planting saplings, \\nfostering a sense of ownership and responsibility toward the environment. The activity \\nreinforced eco-friendly values, promoted green practices on campus, and highlighted the role \\nof individual actions in addressing environmental challenges. Participants developed greater \\nenvironmental consciousness and commitment to long-term ecological sustainability.\\n","semester":"6","startDate":"2025-07-07","hoursSpent":24,"description":"“Buy a T-shirt, Plant a Tree” was a community service and environmental awareness initiative \\norganized by the Kannada Sangha to promote sustainability and individual responsibility among \\nstudents. As part of the initiative, students who purchased a T-shirt were provided with a tree \\nsapling along with clear guidelines on planting and maintenance. The distribution of T-shirts \\nand \\nsaplings was conducted within the college campus, encouraging students to actively participate \\nin environmental conservation by planting and nurturing trees.\\n","aicteMapping":"Spreading public awareness under rural outreach program","pointsEarned":15,"certificateImage":"https://gsqebbosjbvoeqfxocmu.supabase.co/storage/v1/object/public/activity-evidence/ebf4a42c-99f3-41b4-b892-1a93a32d4221/A4xS3KuHy-O5YRlHPT-41.png","certificateAttached":true,"detailedReportPageNo":"22","signatureOfCounsellor":""}],"evaluations":[],"signatories":{"counsellor":{"name":"","designation":""},"evaluator1":{"name":"","designation":""},"evaluator2":{"name":"","designation":""}}}', '2026-01-31 09:51:05.319005+00', '2026-01-31 12:09:43.724591+00'), ('1e321331-4b20-4569-acae-892c733875c5', '3645a852-deae-4b2c-91d4-cd5e0e628c93', '{"student":{"usn":"1RV22EC199","name":"Smriti V Soolebhavi","period":"2022-2026","department":"Electronics & Communication Engineering","totalPoints":0},"activities":[{"id":"hd9Zz_7mgjAqTZv4G6JJm","name":"Akshara 2023 - School Teaching","slNo":1,"place":"Kengeri Government School","photos":[],"endDate":"2023-06-10","duration":32,"outcomes":"","semester":"2","startDate":"2023-05-10","hoursSpent":10,"description":"","aicteMapping":"Helping local schools to achieve good result and enhance their enrolment in Higher technical/vocational education","pointsEarned":5,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"1","signatureOfCounsellor":""},{"id":"ZjNEjt6WHm5BxWhHVQclb","name":"Under The Peepal Tree - 2023 ","slNo":2,"place":"RVCE Campus","photos":[],"endDate":"2023-07-16","duration":3,"outcomes":"","semester":"2","startDate":"2023-07-14","hoursSpent":30,"description":"","aicteMapping":"Contribution to any national level initiative of Government of India. For eg. Digital India, Skill India, Swachh Bharat Internship etc","pointsEarned":15,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"3","signatureOfCounsellor":""},{"id":"S61_RZLYFQRbyKpnFg53r","name":"Sattva Club’s School Engagement Initiative","slNo":3,"place":"Kengeri Government School","photos":[],"endDate":"2024-01-26","duration":9,"outcomes":"","semester":"3","startDate":"2024-01-18","hoursSpent":5,"description":"","aicteMapping":"Helping local schools to achieve good result and enhance their enrolment in Higher technical/vocational education","pointsEarned":5,"certificateImage":"","certificateAttached":true,"detailedReportPageNo":"8","signatureOfCounsellor":""},{"id":"thMcSPfu-E9XV2UNvV49c","name":"Utsarga Marathon - 2024","slNo":4,"place":"RVCE Campus","photos":[],"endDate":"2024-02-04","duration":1,"outcomes":"","semester":"3","startDate":"2024-0